try:
    import pydantic
    from pydantic import BaseModel, Field  # type: ignore
    if hasattr(pydantic, "VERSION") and str(pydantic.VERSION).startswith("2"):
        from pydantic import field_validator, model_validator, ConfigDict  # type: ignore

        def validator(*fields, **kwargs):
            pre = kwargs.pop("pre", False)
            mode = "before" if pre else "after"
            check_fields = kwargs.pop("check_fields", None)

            def decorator(func):
                field_decorator = field_validator(*fields, mode=mode, check_fields=check_fields)

                @functools.wraps(func)
                def compat_wrapper(cls, value, info):
                    signature = inspect.signature(func)
                    kwargs_map = {}
                    if "values" in signature.parameters:
                        kwargs_map["values"] = dict(getattr(info, "data", {}) or {})
                    if "field" in signature.parameters:
                        kwargs_map["field"] = SimpleNamespace(name=getattr(info, "field_name", ""))
                    if "info" in signature.parameters:
                        kwargs_map["info"] = info
                    return func(cls, value, **kwargs_map) if kwargs_map else func(cls, value)

                return field_decorator(compat_wrapper)

            return decorator

        def root_validator(*args, **kwargs):
            def decorator(func):
                return model_validator(mode="before")(func)
            return decorator
    else:
        from pydantic import validator, root_validator  # type: ignore
except ImportError:
    class BaseModel:
        def __init__(self, **kwargs):
            for k, v in kwargs.items():
                setattr(self, k, v)
        def dict(self):
            return self.__dict__
    class Field:
        def __init__(self, *args, **kwargs):
            pass
    def validator(*args, **kwargs):
        def decorator(func):
            return func
        return decorator
    def root_validator(*args, **kwargs):
        def decorator(func):
            return func
        return decorator

