@dataclass
class DeepSeekIntegrationWrapper:
    """Simple DeepSeek-compatible client kept inside the main model."""

    def __init__(self, api_key: Optional[str] = None, base_url: Optional[str] = None,
                 model: Optional[str] = None, timeout: int = 10) -> None:
        self.api_key = api_key or os.environ.get("DEEPSEEK_API_KEY", "")
        self.base_url = (base_url or os.environ.get("DEEPSEEK_API_BASE_URL", "https://api.deepseek.com")).rstrip("/")
        self.model = model or os.environ.get("DEEPSEEK_MODEL", "deepseek-chat")
        self.timeout = int(os.environ.get("DEEPSEEK_TIMEOUT", str(timeout)))
        self.enabled = bool(self.api_key)

    def ping(self) -> bool:
        if not self.enabled:
            return False
        try:
            req = urllib.request.Request(
                f"{self.base_url}/v1/ping",
                headers={"Accept": "application/json", "Authorization": f"Bearer {self.api_key}"},
            )
            with urllib.request.urlopen(req, timeout=self.timeout) as resp:
                return resp.status == 200
        except Exception:
            return False

    def generate(self, prompt: str, **kwargs: Any) -> Dict[str, Any]:
        if not self.enabled:
            raise RuntimeError("DeepSeek client is disabled")
        payload = {"model": self.model, "prompt": prompt}
        payload.update(kwargs)
        headers = {
            "Content-Type": "application/json",
            "Accept": "application/json",
            "Authorization": f"Bearer {self.api_key}",
        }
        req = urllib.request.Request(
            f"{self.base_url}/v1/generate",
            data=json.dumps(payload).encode("utf-8"),
            headers=headers,
            method="POST",
        )
        with urllib.request.urlopen(req, timeout=self.timeout) as resp:
            body = resp.read().decode("utf-8")
            return json.loads(body) if body else {}


