class JSONFormatter(logging.Formatter):
    def format(self, record):
        log_obj = {"timestamp": time.time(), "level": record.levelname, "module": record.module,
                   "message": record.getMessage(), "extra": getattr(record, "extra", {})}
        if record.exc_info: log_obj["exception"] = traceback.format_exc()
        sensitive = ['token', 'key', 'secret', 'password', 'authorization', 'bearer']
        extra = log_obj["extra"]
        for k in list(extra.keys()):
            if any(s in k.lower() for s in sensitive):
                extra[k] = "***REDACTED***"
        return json.dumps(log_obj)

def get_trace_id():
    return uuid.uuid4().hex[:16]

log = logging.getLogger("LHM")
log.setLevel(logging.INFO)
if not log.handlers:
    fh = RotatingFileHandler("lhm_prod.log", maxBytes=CONFIG.log_rotation_mb*1024*1024, backupCount=10)
    fh.setFormatter(JSONFormatter()); log.addHandler(fh)
    ch = logging.StreamHandler(); ch.setFormatter(JSONFormatter()); log.addHandler(ch)

if STRUCTLOG_AVAILABLE and structlog is not None:
    structlog.configure(
        processors=[
            structlog.stdlib.add_log_level,
            structlog.stdlib.PositionalArgumentsFormatter(),
            structlog.processors.TimeStamper(fmt="iso"),
            structlog.processors.JSONRenderer()
        ],
        logger_factory=structlog.stdlib.LoggerFactory()
    )
    prod_log = structlog.get_logger("lhm-production")
else:
    prod_log = log

