    @field_validator('odds_home', 'odds_draw', 'odds_away', mode='before')
    def validate_odds(cls, v, info):
        if v is None or v <= 1.0 or not np.isfinite(v):
            log.debug(f"Invalid odds {v}, defaulting to 2.0")
            return 2.0
        if v > 1000:
            log.warning(f"Extreme odds capped from {v} to 1000")
            return 1000
        return v

    @field_validator('home_xg', 'away_xg', mode='after')
    def validate_xg(cls, v, info):
        if v is None or not np.isfinite(v):
            return 1.2
        if v > 10:
            return 10
        return v

    @model_validator(mode='after')
    def validate_consistency(self):
        if self.home_xg + self.away_xg < 0.1:
            self.home_xg = 1.2
            self.away_xg = 1.0
        home = max(float(self.odds_home or 2.0), 1.01)
        draw = max(float(self.odds_draw or 3.5), 1.01)
        away = max(float(self.odds_away or 4.0), 1.01)
        implied_sum = (1.0 / home) + (1.0 / draw) + (1.0 / away)
        if implied_sum <= 0 or implied_sum > 1.50:
            log.warning(f"Implied probability sum out of bounds ({implied_sum:.3f}); resetting 1X2 odds to defaults.")
            self.odds_home = 2.0
            self.odds_draw = 3.5
            self.odds_away = 4.0
        return self

