# ======================================================================
# BIAS DETECTOR
# ======================================================================
class BiasDetector:
    def __init__(self, db_pool=None):
        self.db = db_pool
        self.bias_metrics = defaultdict(list)
        self.threshold = CONFIG.bias_alert_threshold
        self._lock = asyncio.Lock()
        self._bin_counts = defaultdict(lambda: defaultdict(int))
        self._loaded = False

    async def load(self):
        if self.db and not self._loaded:
            rows = await self.db.fetchall("SELECT market, outcome, predicted_prob, actual FROM bias_metrics")
            for row in rows:
                self.bias_metrics[f"{row['market']}_{row['outcome']}"].append((row['predicted_prob'], row['actual']))
            self._loaded = True

    async def record(self, market: str, outcome: str, predicted_prob: float, actual: int):
        async with self._lock:
            key = f"{market}_{outcome}"
            self.bias_metrics[key].append((predicted_prob, actual))
            if len(self.bias_metrics[key]) > 1000:
                self.bias_metrics[key] = self.bias_metrics[key][-1000:]
            bin_idx = min(9, int(predicted_prob * 10))
            self._bin_counts[(market, outcome, bin_idx)][actual] += 1
            if self.db:
                try:
                    await self.db.execute(
                        "INSERT INTO bias_metrics (market, outcome, predicted_prob, actual, bias, timestamp) VALUES (?,?,?,?,?,?)",
                        (market, outcome, predicted_prob, actual, float(actual) - float(predicted_prob), time.time())
                    )
                except Exception as exc:
                    log.warning(f"BiasDetector DB write failed: {exc}")

    def compute_bias(self, market: str, outcome: str) -> Optional[float]:
        key = f"{market}_{outcome}"
        data = self.bias_metrics.get(key, [])
        if len(data) < 50:
            return None
        probs = np.array([p for p, _ in data])
        actuals = np.array([a for _, a in data])
        mean_prob = np.mean(probs)
        mean_actual = np.mean(actuals)
        return float(mean_actual - mean_prob)

    def is_biased(self, market: str, outcome: str) -> bool:
        bias = self.compute_bias(market, outcome)
        if bias is None:
            return False
        return abs(bias) > self.threshold

    def correction_factor(self, market: str, outcome: str) -> float:
        bias = self.compute_bias(market, outcome)
        if bias is None:
            return 1.0
        corrected = 1.0 - bias if bias > 0 else 1.0 + abs(bias)
        return max(0.5, min(1.5, corrected))

    def get_bias_report(self) -> Dict:
        report = {}
        for key in self.bias_metrics:
            bias = self.compute_bias(*key.split('_', 1))
            if bias is not None:
                report[key] = bias
        return report

    async def alert_if_biased(self, market: str, outcome: str, prob: float):
        bias = self.compute_bias(market, outcome)
        if bias is not None and abs(bias) > self.threshold:
            send_alert(
                f"BIAS DETECTED: {market}/{outcome} bias={bias:.3f} (threshold={self.threshold:.3f})",
                level="warning"
            )

# ======================================================================
# SAFE EXPRESSION EVALUATOR (ast.literal_eval first, then restricted eval whitelist)
# ======================================================================
class SafeExpressionEvaluator:
    _allowed_names = {
        "abs": abs, "min": min, "max": max, "sum": sum, "round": round,
        "len": len, "float": float, "int": int, "str": str, "bool": bool,
        "log": math.log, "log10": math.log10, "exp": math.exp, "sqrt": math.sqrt,
        "sin": math.sin, "cos": math.cos, "tan": math.tan, "asin": math.asin,
        "acos": math.acos, "atan": math.atan, "atan2": math.atan2,
        "pi": math.pi, "e": math.e, "tau": math.tau,
        "np": np  # allow numpy but only for vectorized ops; restrict further if needed
    }
    @classmethod
    def evaluate(cls, expr, context):
        try:
            return ast.literal_eval(expr)
        except (ValueError, SyntaxError):
            pass
        tree = ast.parse(expr, mode='eval')
        for node in ast.walk(tree):
            if isinstance(node, ast.Call):
                if isinstance(node.func, ast.Name):
                    if node.func.id not in cls._allowed_names and node.func.id not in context:
                        raise ValueError(f"Function {node.func.id} not allowed")
                elif isinstance(node.func, ast.Attribute):
                    if isinstance(node.func.value, ast.Name):
                        # Allow both np.log-style and direct log calls
                        if node.func.value.id == 'np':
                            # For np.* calls, allow if attr is in allowed_names or context
                            if node.func.attr not in cls._allowed_names and node.func.attr not in context:
                                raise ValueError(f"Function np.{node.func.attr} not allowed")
                        elif node.func.value.id in cls._allowed_names or node.func.value.id in context:
                            # Allow module.function calls if module is in allowed names
                            continue
                        else:
                            raise ValueError("Only simple function calls allowed")
                    else:
                        raise ValueError("Only simple function calls allowed")
                else:
                    raise ValueError("Only simple function calls allowed")
            elif isinstance(node, ast.Attribute):
                if isinstance(node.value, ast.Name) and node.value.id == 'np':
                    continue
                raise ValueError("Attribute access only allowed on np")
            elif isinstance(node, ast.Subscript):
                raise ValueError("Subscription access is not allowed")
            elif isinstance(node, ast.Name):
                if node.id in {"__builtins__", "True", "False", "None"}:
                    raise ValueError("Unsafe name access")
                if node.id not in cls._allowed_names and node.id not in context:
                    raise ValueError(f"Name {node.id} not allowed")
            elif isinstance(node, (ast.Import, ast.ImportFrom)):
                raise ValueError("Imports not allowed")
        code = compile(tree, '<string>', 'eval')
        safe_globals = {"__builtins__": {}}
        eval_context = dict(cls._allowed_names)
        eval_context.update(context)
        numpy_aliases = {
            'log': np.log, 'log10': np.log10, 'exp': np.exp, 'sqrt': np.sqrt,
            'sin': np.sin, 'cos': np.cos, 'tan': np.tan,
            'abs': np.abs, 'min': np.minimum, 'max': np.maximum,
        }
        for alias, func in numpy_aliases.items():
            eval_context[alias] = func
        safe_globals.update(eval_context)
        try:
            return cls._safe_eval_node(ast.parse(expr, mode='eval'), eval_context)
        except ValueError:
            raise
        except Exception as exc:
            raise ValueError(f"Expression evaluation failed for: {expr}") from exc

    @classmethod
    def _safe_eval_node(cls, node, context):
        if isinstance(node, ast.Expression):
            return cls._safe_eval_node(node.body, context)
        if isinstance(node, ast.Constant):
            return node.value
        if isinstance(node, ast.Name):
            if node.id in context:
                return context[node.id]
            raise ValueError(f"Name {node.id} not allowed")
        if isinstance(node, ast.BinOp):
            left = cls._safe_eval_node(node.left, context)
            right = cls._safe_eval_node(node.right, context)
            op = node.op
            if isinstance(op, ast.Add):
                return left + right
            if isinstance(op, ast.Sub):
                return left - right
            if isinstance(op, ast.Mult):
                return left * right
            if isinstance(op, ast.Div):
                return left / right
            if isinstance(op, ast.Pow):
                return left ** right
            if isinstance(op, ast.Mod):
                return left % right
            raise ValueError(f"Unsupported binary operator {op}")
        if isinstance(node, ast.UnaryOp):
            operand = cls._safe_eval_node(node.operand, context)
            if isinstance(node.op, ast.USub):
                return -operand
            if isinstance(node.op, ast.UAdd):
                return +operand
            raise ValueError(f"Unsupported unary operator {node.op}")
        if isinstance(node, ast.Call):
            if isinstance(node.func, ast.Name):
                func_name = node.func.id
                if func_name not in context:
                    raise ValueError(f"Function {func_name} not allowed")
                func = context[func_name]
                args = [cls._safe_eval_node(arg, context) for arg in node.args]
                kwargs = {kw.arg: cls._safe_eval_node(kw.value, context) for kw in node.keywords}
                return func(*args, **kwargs)
            if isinstance(node.func, ast.Attribute):
                if isinstance(node.func.value, ast.Name) and node.func.value.id == 'np':
                    attr = node.func.attr
                    if attr not in context:
                        raise ValueError(f"Function np.{attr} not allowed")
                    func = context[attr]
                    args = [cls._safe_eval_node(arg, context) for arg in node.args]
                    kwargs = {kw.arg: cls._safe_eval_node(kw.value, context) for kw in node.keywords}
                    return func(*args, **kwargs)
                raise ValueError("Only np.* attribute calls are allowed")
            raise ValueError("Only simple function calls are allowed")
        if isinstance(node, ast.Attribute):
            if isinstance(node.value, ast.Name) and node.value.id == 'np':
                return getattr(context.get('np'), node.attr)
            raise ValueError("Attribute access only allowed on np")
        if isinstance(node, ast.Subscript):
            raise ValueError("Subscription access is not allowed")
        if isinstance(node, ast.Tuple):
            return tuple(cls._safe_eval_node(elt, context) for elt in node.elts)
        if isinstance(node, ast.List):
            return [cls._safe_eval_node(elt, context) for elt in node.elts]
        if isinstance(node, ast.Dict):
            return {cls._safe_eval_node(k, context): cls._safe_eval_node(v, context) for k, v in zip(node.keys, node.values)}
        raise ValueError(f"Unsupported expression node: {type(node).__name__}")

# ======================================================================
# MATH ENGINE
# ======================================================================
class AdvancedMathEngine:
    @staticmethod
    def bivariate_poisson_pmf(x: int, y: int, lambda_1: float, lambda_2: float, lambda_3: float) -> float:
        if lambda_1 <= 0 or lambda_2 <= 0:
            return 0.0
        lambda_3 = max(0.0, min(lambda_3, lambda_1, lambda_2))
        if lambda_3 < 1e-12:
            return poisson.pmf(x, lambda_1) * poisson.pmf(y, lambda_2)
        log_term = -(lambda_1 + lambda_2 + lambda_3)
        log_base = x * np.log(lambda_1) + y * np.log(lambda_2) - (math.lgamma(x+1) + math.lgamma(y+1))
        log_summation = []
        max_k = min(x, y)
        for k in range(max_k + 1):
            try:
                comb_xk = math.comb(x, k)
                comb_yk = math.comb(y, k)
            except AttributeError:
                if not getattr(AdvancedMathEngine, "_comb_fallback_logged", False):
                    log.warning("math.comb unavailable; using slower factorial fallback in bivariate_poisson_pmf.")
                    setattr(AdvancedMathEngine, "_comb_fallback_logged", True)
                comb_xk = math.factorial(x) // (math.factorial(k) * math.factorial(x-k))
                comb_yk = math.factorial(y) // (math.factorial(k) * math.factorial(y-k))
            coef = comb_xk * comb_yk * math.factorial(k)
            cov_ratio = (lambda_3 / (lambda_1 * lambda_2)) ** k if (lambda_1 * lambda_2) > 0 else 0
            if coef * cov_ratio > 0:
                log_summation.append(math.log(coef * cov_ratio + 1e-300))
        if not log_summation:
            return 0.0
        log_sum = np.logaddexp.reduce(log_summation)
        return np.exp(log_term + log_base + log_sum)

    @staticmethod
    def dynamic_copula_match_probs(lam_home: float, lam_away: float, max_goals: int = Constants.DEFAULT_MAX_GOALS,
                                   cov_factor: float = 0.2, league_volatility: float = Constants.DEFAULT_LEAGUE_VOLATILITY,
                                   time_decay: float = 1.0) -> NDArray:
        try:
            lam_home = max(1e-6, float(lam_home))
            lam_away = max(1e-6, float(lam_away))
            ks = np.arange(max_goals + 1)
            home_pmf = np.asarray(poisson.pmf(ks, lam_home), dtype=float)
            away_pmf = np.asarray(poisson.pmf(ks, lam_away), dtype=float)
            home_cdf = np.cumsum(home_pmf)
            away_cdf = np.cumsum(away_pmf)
            theta = np.clip(3.0 * max(0.1, min(1.0, float(league_volatility or 0.5))) * max(0.1, min(1.0, float(cov_factor or 0.2))) * max(0.3, min(1.2, float(time_decay or 1.0))), 0.05, 8.0)

            def frank_cdf(u: float, v: float) -> float:
                if abs(theta) < 1e-9:
                    return float(u * v)
                u = float(np.clip(u, 1e-9, 1.0 - 1e-9))
                v = float(np.clip(v, 1e-9, 1.0 - 1e-9))
                return -math.log(1.0 + (((math.exp(-theta * u) - 1.0) * (math.exp(-theta * v) - 1.0)) / (math.exp(-theta) - 1.0))) / theta

            probs = np.zeros((max_goals + 1, max_goals + 1))
            for hg in range(max_goals + 1):
                u0 = home_cdf[hg - 1] if hg > 0 else 0.0
                u1 = home_cdf[hg]
                for ag in range(max_goals + 1):
                    v0 = away_cdf[ag - 1] if ag > 0 else 0.0
                    v1 = away_cdf[ag]
                    cell_prob = frank_cdf(u1, v1) - frank_cdf(u0, v1) - frank_cdf(u1, v0) + frank_cdf(u0, v0)
                    probs[hg, ag] = max(0.0, float(cell_prob))
            total = probs.sum()
            return probs / total if total > 0 else probs
        except Exception:
            return AdvancedMathEngine.bivariate_match_probs(lam_home, lam_away, max_goals, cov_factor)

    @staticmethod
    def bivariate_match_probs(lam_home: float, lam_away: float, max_goals: int = Constants.DEFAULT_MAX_GOALS, cov_factor: float = 0.2) -> NDArray:
        lam3 = lam_home * lam_away * cov_factor
        lam3 = max(0.0, min(lam3, lam_home, lam_away))
        probs = np.zeros((max_goals + 1, max_goals + 1))
        for hg in range(max_goals + 1):
            for ag in range(max_goals + 1):
                probs[hg, ag] = AdvancedMathEngine.bivariate_poisson_pmf(hg, ag, lam_home, lam_away, lam3)
        total = probs.sum()
        if total > 0:
            probs /= total
        return probs

    @staticmethod
    def zero_inflated_nbinom_probs(lam_home: float, lam_away: float, max_goals: int = Constants.DEFAULT_MAX_GOALS,
                                    p0_home: float = 0.08, p0_away: float = 0.08,
                                    dispersion: float = 10.0) -> NDArray:
        r = max(2.0, min(40.0, float(dispersion or 10.0)))
        probs = np.zeros((max_goals + 1, max_goals + 1))
        for hg in range(max_goals + 1):
            for ag in range(max_goals + 1):
                p_h = (1 - p0_home) * nbinom.pmf(hg, r, r / (r + max(1e-6, lam_home))) + p0_home * (1 if hg == 0 else 0)
                p_a = (1 - p0_away) * nbinom.pmf(ag, r, r / (r + max(1e-6, lam_away))) + p0_away * (1 if ag == 0 else 0)
                probs[hg, ag] = p_h * p_a
        total = probs.sum()
        return probs / total if total > 0 else probs

    @staticmethod
    def fit_tail_risk_gpd(losses: List[float], threshold: float) -> Tuple[float, float]:
        excess = [l - threshold for l in losses if l > threshold]
        if len(excess) < 10:
            return 0.0, 1.0
        def nll(params):
            xi, beta = params
            if beta <= 0 or xi <= -1:
                return 1e10
            val = 1 + (xi * np.array(excess)) / beta
            if np.any(val <= 0):
                return 1e10
            return len(excess) * math.log(beta) + (1 + 1/xi) * np.sum(np.log(val))
        init = [0.1, float(np.std(excess)) if np.std(excess) > 0 else 1.0]
        bounds = [(-0.8, 1.2), (0.001, 25.0)]
        try:
            res = minimize(nll, init, method='L-BFGS-B', bounds=bounds)
            return float(res.x[0]), float(res.x[1])
        except Exception:
            return 0.0, 1.0

    @staticmethod
    def tail_risk_adjustment(shape: float, scale: float) -> float:
        return max(0.0, shape * scale)

    @staticmethod
    def compute_cvar(returns: NDArray, alpha: float = 0.05) -> float:
        sorted_returns = np.sort(returns)
        idx = int(alpha * len(sorted_returns))
        if idx == 0:
            return 0.0
        return -float(np.mean(sorted_returns[:idx]))

# ======================================================================
# SURROGATE MODEL, IMPORTANCE SAMPLER, SOBOL, TAIL GUARD, ONLINE CALIBRATOR
# ======================================================================
class SurrogateModel:
    def __init__(self, model=None):
        self.model = model
        self._cache = {}
        self._cache_ts = {}
        self._cache_lock = asyncio.Lock()
        self._cache_ttl = CONFIG.cache_ttl
        self._max_size = CONFIG.feature_cache_max_size

    async def _prune_cache(self, now: Optional[float] = None) -> None:
        now = float(now or time.time())
        cutoff = now - max(float(self._cache_ttl), 3600.0)
        stale_keys = [key for key, ts in self._cache_ts.items() if float(ts) < cutoff]
        for key in stale_keys:
            self._cache.pop(key, None)
            self._cache_ts.pop(key, None)
        if len(self._cache) > self._max_size:
            keys = sorted(self._cache_ts.items(), key=lambda kv: kv[1])[: max(1, len(self._cache) // 2)]
            for key, _ in keys:
                self._cache.pop(key, None)
                self._cache_ts.pop(key, None)

    async def predict_probs(self, features: Dict[str, float]) -> NDArray:
        cache_key = hashlib.md5(str(sorted(features.items())).encode()).hexdigest()
        now = time.time()
        # Check cache without holding lock during prune
        if cache_key in self._cache and now - self._cache_ts.get(cache_key,0) < self._cache_ttl:
            return self._cache[cache_key]
        order = FeatureEngine.feature_order()
        x = np.array([features.get(k, 0.0) for k in order], dtype=np.float32).reshape(1, -1)
        if self.model is None:
            h = features.get("home_xg", 1.2)
            a = features.get("away_xg", 1.0)
            joint = Calculator.match_probs(h, a)
            p_home = float(np.sum(joint[np.tril_indices_from(joint, k=-1)]))
            p_draw = float(np.sum(np.diag(joint)))
            p_away = max(0.0, 1.0 - p_home - p_draw)
            result = np.array([p_home, p_draw, p_away], dtype=float)
            result = result / (result.sum() + 1e-9)
        else:
            try:
                result = self.model.predict_proba(x)[0]
            except Exception:
                result = np.array([0.4, 0.25, 0.35])
        async with self._cache_lock:
            await self._prune_cache(now)
            self._cache[cache_key] = result
            self._cache_ts[cache_key] = now
        return result

class ImportanceSampler:
    @staticmethod
    def sample_goals(lam_h, lam_a, bias_factor=1.3):
        lam_h_b = lam_h * bias_factor
        lam_a_b = lam_a * bias_factor
        hg = np.random.poisson(lam_h_b)
        ag = np.random.poisson(lam_a_b)
        w = (poisson.pmf(hg, lam_h) * poisson.pmf(ag, lam_a)) / (poisson.pmf(hg, lam_h_b) * poisson.pmf(ag, lam_a_b) + 1e-12)
        return hg, ag, w

class SobolSampler:
    def __init__(self, dim=2):
        self.engine = qmc.Sobol(d=dim, scramble=True)

    def next_pair(self):
        u = self.engine.random(1)[0]
        return u[0], u[1]

class TailGuard:
    @staticmethod
    def effective_sample_size(weights):
        w = np.array(weights)
        return (w.sum()**2) / (np.sum(w**2) + 1e-12)

    @staticmethod
    def throttle_factor(xi, beta):
        rf = max(0.2, min(1.0, 1.0 - xi * beta * 3.0))
        return rf

class OnlineCalibrator:
    def __init__(self, a=1.0, b=1.0):
        self.a = a
        self.b = b

    def update(self, outcome_win: int):
        self.a += outcome_win
        self.b += (1 - outcome_win)

    def mean(self):
        return self.a / (self.a + self.b)

    def to_dict(self):
        return {"a": self.a, "b": self.b}

    @classmethod
    def from_dict(cls, data):
        return cls(data["a"], data["b"])

# ======================================================================
# OPERATIONAL BRIDGE
# ======================================================================
class HardenedOperationalBridge:
    def __init__(self, config: Settings):
        self.cfg = config
        if TORCH_AVAILABLE:
            self.device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
        else:
            self.device = "cpu"
        self.baseline_distribution = None
        self.snapshot_toggle = False
        self._snapshot_lock = asyncio.Lock()
        self._impute_values = None

    def enforce_shape_guardrails(self, df: DataFrameType) -> TensorType:
        numeric_data = df.select_dtypes(include=[np.number]).to_numpy()
        rows, cols = numeric_data.shape
        if rows == 0:
            raise ValueError("Zero-row matrix passed to Ingestion Pipeline.")
        if cols < self.cfg.target_state_dim:
            if self._impute_values is not None:
                pad = np.tile(self._impute_values[:self.cfg.target_state_dim - cols], (rows,1))
            else:
                pad = np.zeros((rows, self.cfg.target_state_dim - cols))
            sanitized_np = np.hstack((numeric_data, pad))
        else:
            sanitized_np = numeric_data[:, :self.cfg.target_state_dim]
        if self.baseline_distribution is None:
            self.baseline_distribution = np.mean(sanitized_np, axis=0)
        if TORCH_AVAILABLE:
            return torch.tensor(sanitized_np, dtype=torch.float32, device=self.device)
        else:
            return sanitized_np

    def monitor_data_drift_kl(self, current_tensor: TensorType) -> float:
        if self.baseline_distribution is None:
            return 0.0
        if TORCH_AVAILABLE and hasattr(current_tensor, 'mean'):
            current_mean = torch.mean(current_tensor, dim=0).detach().cpu().numpy()
        elif isinstance(current_tensor, np.ndarray):
            current_mean = np.mean(current_tensor, axis=0)
        else:
            current_mean = np.mean(np.array(current_tensor), axis=0)
        p = np.clip(self.baseline_distribution, 1e-5, None)
        q = np.clip(current_mean, 1e-5, None)
        kl_div = 0.5 * (np.sum(p * np.log(p / q)) + np.sum(q * np.log(q / p)))
        if kl_div > self.cfg.drift_threshold_kl:
            log.warning(f"HIGH DISTRIBUTION DRIFT DETECTED: KL={kl_div:.4f}. Contracting allocation.")
        return kl_div

    def compute_feature_psi(self, live_data: DataFrameType, reference_data: DataFrameType) -> Dict[str, float]:
        psi_scores = {}
        for col in live_data.select_dtypes(include=[np.number]).columns:
            if col in reference_data.columns:
                live_hist, bins = np.histogram(live_data[col].dropna(), bins=10)
                ref_hist, _ = np.histogram(reference_data[col].dropna(), bins=bins)
                live_p = live_hist / (live_hist.sum() + 1e-9)
                ref_p = ref_hist / (ref_hist.sum() + 1e-9)
                psi = np.sum((live_p - ref_p) * np.log((live_p + 1e-9) / (ref_p + 1e-9)))
                psi_scores[col] = float(psi)
        return psi_scores

    def execute_safe_backward_step(self, loss: TensorType, parameters: list) -> bool:
        if torch.isnan(loss) or torch.isinf(loss):
            log.error("CRITICAL: Loss tripwire triggered. NaN/Inf encountered. Skipping batch.")
            return False
        loss.backward()
        torch.nn.utils.clip_grad_norm_(parameters, max_norm=self.cfg.max_grad_norm)
        return True

    async def serialize_double_buffered_snapshot(self, state_dict: dict):
        if not self.cfg.enable_warm_snapshot:
            return
        async with self._snapshot_lock:
            target_path = self.cfg.snapshot_path_a if self.snapshot_toggle else self.cfg.snapshot_path_b
            try:
                with open(target_path, "wb") as f:
                    joblib.dump(state_dict, f, protocol=pickle.HIGHEST_PROTOCOL)
            except Exception as e:
                log.error(f"Serialization to {target_path} failed: {e}")
            self.snapshot_toggle = not self.snapshot_toggle

    def purge_hardware_cache(self):
        if TORCH_AVAILABLE and torch.cuda.is_available():
            torch.cuda.empty_cache()
        gc.collect()

# ======================================================================
# WARM SNAPSHOT
# ======================================================================
class WarmSnapshot:
    @staticmethod
    def load():
        if not CONFIG.enable_warm_snapshot:
            return None, None
        path = CONFIG.resolve_snapshot_path(CONFIG.warm_snapshot_path)
        if os.path.exists(path):
            try:
                if joblib is not None:
                    with open(path, "rb") as f:
                        data = joblib.load(f)
                else:
                    with open(path, "rb") as f:
                        data = pickle.load(f)
                if data.get("checksum") and hashlib.md5(pickle.dumps(data["state"])).hexdigest() != data["checksum"]:
                    log.warning("Snapshot checksum mismatch, ignoring.")
                    return None, None
                return data.get("state"), data.get("models")
            except Exception as exc:
                log.warning(f"Snapshot load failed for {path}: {exc}")
        return None, None

