# EXCHANGE CLIENT
# ======================================================================
class ExchangeClient:
    """Betting exchange API wrapper (Betfair/Betdaq) with order placement and market streaming."""
    def __init__(self):
        self.exchange_type = CONFIG.exchange_type.lower()
        self.key = CONFIG.exchange_key
        self.secret = CONFIG.exchange_secret
        self.session_token = CONFIG.exchange_session_token
        self._session = None
        self._logged_in = False
        self._token_expiry = 0
        self._client = None

    async def login(self):
        if self._logged_in and time.time() < self._token_expiry - 60:
            return True
        if self.exchange_type == "betfair" and (not self.key or not self.secret or not self.session_token):
            log.error("Exchange credentials missing: exchange_key/exchange_secret/exchange_session_token")
            return False
        try:
            if self.exchange_type == "betfair":
                try:
                    import betfairlightweight
                except ImportError:
                    log.error("betfairlightweight not installed")
                    return False
                self._client = betfairlightweight.APIClient(
                    username=self.key,
                    password=self.secret,
                    app_key=self.session_token
                )
                self._client.login()
                self._logged_in = True
                self._token_expiry = time.time() + 3600
                log.info("Betfair login successful")
            else:
                log.warning(f"Exchange type {self.exchange_type} not fully implemented")
                self._logged_in = True
            return True
        except Exception as e:
            log.error(f"Exchange login failed: {e}")
            return False

    async def place_order(self, market_id: str, selection_id: str, side: str, odds: float, stake: float, client_ref: str = None):
        if not self._logged_in:
            if not await self.login():
                return None
        try:
            if self.exchange_type == "betfair" and self._client:
                order = await asyncio.wait_for(
                    asyncio.to_thread(
                        self._client.betting.place_orders,
                        market_id=market_id,
                        instructions=[{
                            "selectionId": selection_id,
                            "side": "BACK" if side.lower() == "back" else "LAY",
                            "orderType": "LIMIT",
                            "limitOrder": {"size": stake, "price": odds},
                            "customerOrderRef": client_ref or str(uuid.uuid4())
                        }]
                    ),
                    timeout=max(5, int(CONFIG.timeout)),
                )
                return {"order_id": order, "status": "success"}
        except asyncio.TimeoutError:
            log.error("Order placement timed out")
        except Exception as e:
            log.error(f"Order placement failed: {e}")
        return None

    async def cancel_order(self, market_id: str, bet_id: str):
        try:
            if self.exchange_type == "betfair" and self._client:
                return self._client.betting.cancel_orders(
                    market_id=market_id,
                    bet_ids=[bet_id]
                )
        except Exception as e:
            log.error(f"Order cancellation failed: {e}")
        return None

    async def get_balance(self):
        try:
            if self.exchange_type == "betfair" and self._client:
                return self._client.accounting.get_account_funds()
        except Exception as e:
            log.error(f"Balance fetch failed: {e}")
        return None

EXCHANGE = ExchangeClient()


