class PinnacleClient:
    def __init__(self):
        self._client = None
        self._logged_in = False

    async def login(self):
        if self._logged_in:
            return True
        try:
            from ps3838api.api.client import PinnacleClient as PC
            self._client = PC(
                login=CONFIG.exchange_key,
                password=CONFIG.exchange_secret,
            )
            self._logged_in = True
            log.info("Pinnacle login successful")
            return True
        except ImportError:
            log.warning("ps3838api not installed; Pinnacle unavailable")
        except Exception as e:
            log.error(f"Pinnacle login failed: {e}")
        return False

    async def place_order(self, market_id: str, selection_id: str, side: str, odds: float, stake: float, client_ref: str = None):
        if not self._logged_in:
            if not await self.login():
                return None
        try:
            import ps3838api
            from ps3838api.models.bet import BetDecision, BetTarget
            target = BetTarget.HOME if selection_id.lower() == "home" else (
                BetTarget.AWAY if selection_id.lower() == "away" else BetTarget.DRAW
            )
            decision = BetDecision(target=target, stake=int(stake * 100), odds=odds, event_id=market_id)
            result = self._client.place_bet(decision, test=CONFIG.dry_run)
            return {"order_id": str(result.get("bet_id", client_ref)), "status": "success"}
        except Exception as e:
            log.error(f"Pinnacle order failed: {e}")
        return None


class BetPawaClient:
    def __init__(self):
        self._logged_in = False
        self._session = None

    async def login(self):
        if self._logged_in and self._session:
            return True
        if not CONFIG.betpawa_phone or not CONFIG.betpawa_password:
            log.warning("BetPawa credentials missing; set betpawa_phone and betpawa_password in config")
            return False
        try:
            import aiohttp
            self._session = aiohttp.ClientSession()
            login_url = "https://www.betpawa.co.ke/api/v1/auth/login"
            payload = {"phone": CONFIG.betpawa_phone, "password": CONFIG.betpawa_password}
            async with self._session.post(login_url, json=payload, timeout=15) as resp:
                if resp.status == 200:
                    data = await resp.json()
                    self._token = data.get("token") or data.get("access_token")
                    if self._token:
                        self._logged_in = True
                        log.info("BetPawa login successful")
                        return True
            log.warning(f"BetPawa login failed: HTTP {resp.status}")
        except ImportError:
            log.warning("aiohttp not installed; BetPawa unavailable")
        except Exception as e:
            log.error(f"BetPawa login error: {e}")
        return False

    async def place_order(self, market_id: str, selection_id: str, side: str, odds: float, stake: float, client_ref: str = None):
        if not self._logged_in:
            if not await self.login():
                return None
        try:
            bet_url = f"https://www.betpawa.co.ke/api/v1/bets/place"
            headers = {"Authorization": f"Bearer {self._token}", "Content-Type": "application/json"}
            payload = {
                "event_id": market_id,
                "market": "1X2",
                "outcome": selection_id,
                "odds": odds,
                "stake": stake,
                "client_ref": client_ref,
            }
            async with self._session.post(bet_url, json=payload, headers=headers, timeout=15) as resp:
                if resp.status in (200, 201):
                    data = await resp.json()
                    return {"order_id": data.get("bet_id", client_ref), "status": "success"}
                log.warning(f"BetPawa bet failed: HTTP {resp.status}")
        except ImportError:
            log.warning("aiohttp not installed; BetPawa bet placement unavailable")
        except Exception as e:
            log.error(f"BetPawa order error: {e}")
        return None

    async def get_balance(self):
        if not self._logged_in:
            return None
        try:
            async with self._session.get("https://www.betpawa.co.ke/api/v1/user/balance", timeout=10) as resp:
                if resp.status == 200:
                    return await resp.json()
        except Exception:
            pass
        return None


