class BookmakerManager:
    """Manages multiple bookmaker clients, bet placement, settlement, and limit tracking."""
    def settle_bet(self, selection, actual_score, market, stake, odds, handicap=0.0, void=False):
        """Atomic settlement with push/half-win/loss handling."""
        try:
            home, away = actual_score
            total = home + away
            
            if void:
                return {"profit": 0.0, "status": "void"}
            
            if market == "1X2":
                if selection == "home" and home > away:
                    profit = stake * (odds - 1)
                    return {"profit": profit, "status": "win"}
                elif selection == "draw" and home == away:
                    profit = stake * (odds - 1)
                    return {"profit": profit, "status": "win"}
                elif selection == "away" and away > home:
                    profit = stake * (odds - 1)
                    return {"profit": profit, "status": "win"}
                else:
                    return {"profit": -stake, "status": "loss"}
            
            elif market == "totals":
                line = CONFIG.over_line
                if selection == "over" and total > line:
                    profit = stake * (odds - 1)
                    return {"profit": profit, "status": "win"}
                elif selection == "under" and total < line:
                    profit = stake * (odds - 1)
                    return {"profit": profit, "status": "win"}
                elif total == line:
                    return {"profit": 0.0, "status": "push"}
                else:
                    return {"profit": -stake, "status": "loss"}
            
            elif market == "btts":
                if selection == "yes" and home > 0 and away > 0:
                    profit = stake * (odds - 1)
                    return {"profit": profit, "status": "win"}
                elif selection == "no" and (home == 0 or away == 0):
                    profit = stake * (odds - 1)
                    return {"profit": profit, "status": "win"}
                else:
                    return {"profit": -stake, "status": "loss"}
            
            elif market == "asian_handicap":
                if handicap == 0.0:
                    if home > away:
                        profit = stake * (odds - 1) / 2
                        return {"profit": profit, "status": "half_win"}
                    elif home == away:
                        return {"profit": 0.0, "status": "push"}
                    else:
                        return {"profit": -stake, "status": "loss"}
                else:
                    if selection == "home" and (home + handicap) > away:
                        profit = stake * (odds - 1)
                        return {"profit": profit, "status": "win"}
                    elif (home + handicap) == away:
                        return {"profit": 0.0, "status": "push"}
                    else:
                        return {"profit": -stake, "status": "loss"}
            
            return {"profit": -stake, "status": "loss"}
        except Exception as e:
            log.error(f"Settlement error: {e}")
            raise
    def __init__(self):
        self._clients = {
            "betfair": EXCHANGE,
            "pinnacle": PinnacleClient(),
            "betpawa": BetPawaClient(),
            "betika": BetikaClient(),
        }

    def get_client(self, bookmaker: str):
        return self._clients.get(bookmaker.lower())

    async def place_order(self, decision):
        client = self.get_client(decision.bookmaker)
        if client is None:
            log.warning(f"No client for bookmaker {decision.bookmaker}; falling back to ExchangeClient")
            client = EXCHANGE
        return await client.place_order(
            market_id=decision.fixture_id,
            selection_id=decision.outcome,
            side="BACK",
            odds=decision.odds,
            stake=decision.stake,
            client_ref=decision.bet_id,
        )

    async def cancel_order(self, bookmaker: str, market_id: str, bet_id: str):
        client = self.get_client(bookmaker)
        if client is None:
            log.warning(f"No client for bookmaker {bookmaker}; skipping cancel")
            return None
        try:
            return await client.cancel_order(market_id, bet_id)
        except Exception as e:
            log.warning(f"Cancel failed for {bookmaker}: {e}")
        return None

    async def get_balance(self, bookmaker: str):
        client = self.get_client(bookmaker)
        if client is None:
            return None
        try:
            return await client.get_balance()
        except Exception:
            return None


BOOKMAKER_MANAGER = BookmakerManager()

# ======================================================================
# S3 MODEL STORAGE
# ======================================================================
class S3Storage:
    def __init__(self):
        self.endpoint = CONFIG.s3_endpoint
        self.bucket = CONFIG.s3_bucket
        self.key = CONFIG.s3_key
        self.secret = CONFIG.s3_secret
        self._client = None

    async def connect(self):
        if not self.endpoint:
            return
        try:
            import boto3
            self._client = boto3.client(
                's3',
                endpoint_url=self.endpoint,
                aws_access_key_id=self.key,
                aws_secret_access_key=self.secret
            )
            self._client.head_bucket(Bucket=self.bucket)
        except Exception as e:
            log.warning(f"S3 connection failed: {e}")

    async def upload_model(self, model_path: str, model_key: str):
        if not self._client:
            return False
        try:
            self._client.upload_file(model_path, self.bucket, model_key)
            log.info(f"Model uploaded to s3://{self.bucket}/{model_key}")
            return True
        except Exception as e:
            log.error(f"S3 upload failed: {e}")
            return False

    async def download_model(self, model_key: str, local_path: str):
        if not self._client:
            return False
        try:
            self._client.download_file(self.bucket, model_key, local_path)
            log.info(f"Model downloaded from s3://{self.bucket}/{model_key}")
            return True
        except Exception as e:
            log.error(f"S3 download failed: {e}")
            return False

S3_STORAGE = S3Storage()

# ======================================================================
# MATCH SPECIALISATION ENGINE
# ======================================================================
class BrutalSpecialisationEngine:
    """Operational specialization adapter for the existing monolithic flow.

    The engine stays inside the single-file architecture and computes a compact,
    lazy adjustment vector from fixture-level history, referee context, and form
    strength before those values reach the calculator.
    """

    def __init__(self, state: Any, db: Optional[Any] = None):
        self.state = state
        self.db = db
        self._cache: Dict[Tuple[str, str], Dict[str, float]] = {}
        self._cache_max_size = 512
        self._cache_ttl = 3600.0
        self._cache_timestamps: Dict[Tuple[str, str], float] = {}

    @staticmethod
    def _safe_float(value: Any, default: float = 0.0) -> float:
        if value is None:
            return float(default)
        try:
            numeric = float(value)
            if math.isfinite(numeric):
                return numeric
        except Exception:
            pass
        return float(default)

    @staticmethod
    def _safe_series(values: Any, fallback: Optional[List[float]] = None) -> List[float]:
        if isinstance(values, list):
            seq = values
        elif isinstance(values, tuple):
            seq = list(values)
        else:
            seq = fallback or []
        out = []
        for v in seq:
            try:
                value = float(v)
                if math.isfinite(value):
                    out.append(value)
            except Exception:
                continue
        return out

    @staticmethod
    def _clip(value: float, lo: float, hi: float) -> float:
        return max(lo, min(hi, float(value)))

    @staticmethod
    def _weighted_recent_average(values: List[float], weights: Optional[List[float]] = None) -> float:
        if not values:
            return 0.0
        if weights is None:
            weights = [0.5, 0.3, 0.2]
        recent = list(values)[-len(weights):]
        if not recent:
            return 0.0
        total_weight = sum(weights[-len(recent):])
        if total_weight <= 0:
            return float(np.mean(recent)) if HAS_NUMPY else float(sum(recent) / max(1, len(recent)))
        weighted = 0.0
        for idx, item in enumerate(recent):
            weight = weights[-len(recent) + idx] if len(weights) >= len(recent) else weights[idx]
            weighted += float(item) * float(weight)
        return float(weighted / total_weight)

    @staticmethod
    def _safe_mapping(value: Any) -> Dict[str, Any]:
        if isinstance(value, dict):
            return value
        return {}

    def _blueprint_heuristic(self, feature_id: int, match_row: Dict[str, Any], feats: Dict[str, float], specialisation: Dict[str, float], home_form_strength: float, away_form_strength: float, weighted_goal_diff: float, ref_home_bias: float, travel_altitude_home: float, travel_altitude_away: float) -> float:
        raise DeprecationError("_blueprint_heuristic is deprecated; use _build_blueprint_inventory bounded feature set instead")

    def _build_blueprint_inventory(self, match_row: Dict[str, Any], feats: Dict[str, float], specialisation: Dict[str, float], home_form_strength: float, away_form_strength: float, weighted_goal_diff: float, ref_home_bias: float, travel_altitude_home: float, travel_altitude_away: float) -> Dict[str, float]:
        inventory: Dict[str, float] = {}
        home_xg = self._safe_float(feats.get("home_xg", 1.2), 1.2)
        away_xg = self._safe_float(feats.get("away_xg", 1.0), 1.0)
        market_pressure = self._safe_float(feats.get("bookmaker_margin", 0.05), 0.05)
        crowd_density = self._safe_float(match_row.get("crowd_density", 0.72), 0.72)
        stadium_altitude = self._safe_float(match_row.get("stadium_altitude", 120.0), 120.0)
        pitch_width = self._safe_float(match_row.get("pitch_width", 68.0), 68.0)
        pitch_length = self._safe_float(match_row.get("pitch_length", 105.0), 105.0)
        kickoff_time = str(match_row.get("kickoff_time", "15:00")).lower()
        night_game = 1.0 if any(t in kickoff_time for t in ("18", "20", "21", "22")) else 0.0
        manager_tension = self._safe_float(match_row.get("manager_pressure", 0.5), 0.5)
        referee_leniency = self._safe_float(match_row.get("referee_leniency", 0.5), 0.5)
        player_fatigue = self._safe_float(match_row.get("player_fatigue_index", 0.52), 0.52)
        social_volume = self._safe_float(match_row.get("social_volume", 0.5), 0.5)
        odds_delta = self._safe_float(feats.get("sharp_money", 0.0), 0.0)
        raw = {
            "blueprint_feature_xg_home": home_xg / 5.0,
            "blueprint_feature_xg_away": away_xg / 5.0,
            "blueprint_feature_xg_total": (home_xg + away_xg) / 8.0,
            "blueprint_feature_form_home": home_form_strength,
            "blueprint_feature_form_away": away_form_strength,
            "blueprint_feature_form_diff": (home_form_strength - away_form_strength + 1.0) / 2.0,
            "blueprint_feature_ref_bias_home": (ref_home_bias + 1.0) / 2.0,
            "blueprint_feature_ref_bias_away": (ref_home_bias + 1.0) / 2.0,
            "blueprint_feature_travel_home": (travel_altitude_home - 0.9) / 0.16,
            "blueprint_feature_travel_away": (travel_altitude_away - 0.9) / 0.16,
            "blueprint_feature_crowd_density": crowd_density,
            "blueprint_feature_stadium_altitude": stadium_altitude / 3000.0,
            "blueprint_feature_pitch_width": (pitch_width - 60.0) / 40.0,
            "blueprint_feature_pitch_length": (pitch_length - 90.0) / 40.0,
            "blueprint_feature_night_game": night_game,
            "blueprint_feature_manager_tension": manager_tension,
            "blueprint_feature_referee_leniency": referee_leniency,
            "blueprint_feature_player_fatigue": player_fatigue,
            "blueprint_feature_social_volume": social_volume,
            "blueprint_feature_odds_delta": (odds_delta + 1.0) / 2.0,
            "blueprint_feature_market_pressure": market_pressure,
            "blueprint_feature_goal_diff": (weighted_goal_diff + 4.0) / 8.0,
            "blueprint_feature_specialisation_score": specialisation.get("specialisation_score", 0.5),
            "blueprint_feature_h2h_multiplier_home": specialisation.get("specialisation_h2h_multiplier_home", 1.0),
            "blueprint_feature_h2h_multiplier_away": specialisation.get("specialisation_h2h_multiplier_away", 1.0),
        }
        for name, value in raw.items():
            inventory[name] = self._clip(float(value), 0.0, 1.0)
        return inventory

    def _global_avg_elo(self) -> float:
        team_elo = self.state.get("team_elo", {}) if hasattr(self.state, "get") else {}
        if not isinstance(team_elo, dict):
            return 1500.0
        values = [float(v) for v in team_elo.values() if isinstance(v, (int, float))]
        if not values:
            return 1500.0
        return float(np.mean(values)) if HAS_NUMPY else float(sum(values) / len(values))

    def _team_elo(self, team_name: str) -> float:
        team_elo = self.state.get("team_elo", {}) if hasattr(self.state, "get") else {}
        if not isinstance(team_elo, dict):
            return 1500.0
        return self._safe_float(team_elo.get(team_name), 1500.0)

    def ingest_all_signals(self, match_row: Dict[str, Any], feats: Dict[str, float]) -> Dict[str, float]:
        vector = self.compute_specialisation_vector(match_row, feats)
        vector["specialisation_vector_ready"] = 1.0
        vector["specialisation_signal_count"] = float(len(vector))
        vector["blueprint_inventory_ready"] = 1.0
        vector["blueprint_feature_count"] = float(sum(1 for key in vector if key.startswith("blueprint_feature_")))
        return vector

    def compute_specialisation_vector(self, match_row: Dict[str, Any], feats: Dict[str, float]) -> Dict[str, float]:
        home = str(match_row.get("home", "Home"))
        away = str(match_row.get("away", "Away"))
        fixture_id = str(match_row.get("fixture_id", match_row.get("id", "")))
        match_date = str(match_row.get("date", match_row.get("match_date", "")))
        pair_key = (home, away, fixture_id, match_date)
        now = time.time()
        if pair_key in self._cache:
            ts = self._cache_timestamps.get(pair_key, 0.0)
            if now - ts <= self._cache_ttl:
                return self._cache[pair_key]
            del self._cache[pair_key]
            self._cache_timestamps.pop(pair_key, None)
        if len(self._cache) >= self._cache_max_size:
            oldest = min(self._cache_timestamps, key=self._cache_timestamps.get)
            self._cache.pop(oldest, None)
            self._cache_timestamps.pop(oldest, None)

        home_xg = self._safe_float(feats.get("home_xg", 1.2), 1.2)
        away_xg = self._safe_float(feats.get("away_xg", 1.0), 1.0)
        home_form = self._safe_float(feats.get("form_home", 0.5), 0.5)
        away_form = self._safe_float(feats.get("form_away", 0.5), 0.5)
        ref_cards = self._safe_float(feats.get("referee_avg_cards", 4.5), 4.5)
        ref_home_bias = self._safe_float(feats.get("referee_home_bias", 0.0), 0.0)
        travel_home = self._safe_float(feats.get("travel_home", 0.0), 0.0)
        travel_away = self._safe_float(feats.get("travel_away", 0.0), 0.0)
        home_elo = self._team_elo(home)
        away_elo = self._team_elo(away)
        global_avg_elo = self._global_avg_elo()

        home_hist_xg = self._safe_series(match_row.get("history_home_xg"), [home_xg])
        away_hist_xg = self._safe_series(match_row.get("history_away_xg"), [away_xg])
        total_goals_hist = self._safe_series(match_row.get("history_total_goals"), [home_xg + away_xg])
        goal_diff_hist = self._safe_series(match_row.get("history_goal_diff"), [home_xg - away_xg])

        weighted_home_xg = self._weighted_recent_average(home_hist_xg, [0.5, 0.3, 0.2])
        weighted_away_xg = self._weighted_recent_average(away_hist_xg, [0.5, 0.3, 0.2])
        weighted_total_goals = self._weighted_recent_average(total_goals_hist, [0.5, 0.3, 0.2])
        weighted_goal_diff = self._weighted_recent_average(goal_diff_hist, [0.5, 0.3, 0.2])

        h2h_home_multiplier = self._clip(weighted_home_xg / max(home_xg, 0.05), 0.85, 1.15)
        h2h_away_multiplier = self._clip(weighted_away_xg / max(away_xg, 0.05), 0.85, 1.15)
        total_goals_bias = self._clip(weighted_total_goals / max(home_xg + away_xg, 0.1), 0.85, 1.15)
        scoreline_bias = self._clip(1.0 + 0.04 * weighted_goal_diff, 0.9, 1.1)

        referee_home_delta = self._safe_float(match_row.get("referee_avg_cards_for_home"), ref_cards)
        referee_away_delta = self._safe_float(match_row.get("referee_avg_cards_for_away"), ref_cards)
        referee_home_factor = self._clip(referee_home_delta / max(ref_cards, 0.5), 0.8, 1.25)
        referee_away_factor = self._clip(referee_away_delta / max(ref_cards, 0.5), 0.8, 1.25)

        home_form_strength = self._clip(home_form * (home_elo / max(global_avg_elo, 1.0)), 0.0, 1.5)
        away_form_strength = self._clip(away_form * (away_elo / max(global_avg_elo, 1.0)), 0.0, 1.5)

        home_bleed = away_bleed = 0.0
        last_goal_diff = goal_diff_hist[-1] if goal_diff_hist else 0.0
        if last_goal_diff >= 2.0:
            home_bleed = -0.03
            away_bleed = 0.05
        elif last_goal_diff <= -2.0:
            home_bleed = 0.05
            away_bleed = -0.03

        travel_altitude_home = self._clip(1.0 - 0.0005 * travel_home + (0.02 if ref_home_bias > 0 else 0.0), 0.9, 1.06)
        travel_altitude_away = self._clip(1.0 - 0.0005 * travel_away + (0.02 if ref_home_bias < 0 else 0.0), 0.9, 1.06)

        specialisation = {
            "weighted_h2h_home_xg": self._clip(weighted_home_xg, 0.0, 6.0),
            "weighted_h2h_away_xg": self._clip(weighted_away_xg, 0.0, 6.0),
            "weighted_h2h_total_goals": self._clip(weighted_total_goals, 0.0, 10.0),
            "weighted_h2h_goal_diff": self._clip(weighted_goal_diff, -4.0, 4.0),
            "referee_team_card_delta_home": self._clip(referee_home_factor, 0.5, 1.5),
            "referee_team_card_delta_away": self._clip(referee_away_factor, 0.5, 1.5),
            "form_strength_home": self._clip(home_form_strength, 0.0, 1.5),
            "form_strength_away": self._clip(away_form_strength, 0.0, 1.5),
            "last_result_bleed_home": self._clip(home_bleed, -0.05, 0.05),
            "last_result_bleed_away": self._clip(away_bleed, -0.05, 0.05),
            "specialisation_travel_altitude_home": self._clip(travel_altitude_home, 0.9, 1.06),
            "specialisation_travel_altitude_away": self._clip(travel_altitude_away, 0.9, 1.06),
            "specialisation_streak_quality_home": self._clip(home_form_strength * 0.75 + 0.35, 0.0, 1.5),
            "specialisation_streak_quality_away": self._clip(away_form_strength * 0.75 + 0.35, 0.0, 1.5),
            "specialisation_h2h_multiplier_home": self._clip(h2h_home_multiplier, 0.85, 1.15),
            "specialisation_h2h_multiplier_away": self._clip(h2h_away_multiplier, 0.85, 1.15),
            "home_xg_specialisation_multiplier": self._clip(h2h_home_multiplier * total_goals_bias * (1.0 + home_bleed), 0.85, 1.15),
            "away_xg_specialisation_multiplier": self._clip(h2h_away_multiplier * total_goals_bias * (1.0 + away_bleed), 0.85, 1.15),
            "specialisation_score": self._clip((home_form_strength + away_form_strength + abs(weighted_goal_diff) * 0.05 + ref_home_bias * 0.02) / 3.0, 0.0, 1.0),
        }
        specialisation.update(self._build_blueprint_inventory(
            match_row,
            feats,
            specialisation,
            home_form_strength,
            away_form_strength,
            weighted_goal_diff,
            ref_home_bias,
            travel_altitude_home,
            travel_altitude_away,
        ))
        self._cache[pair_key] = specialisation
        self._cache_timestamps[pair_key] = time.time()
        return specialisation


SpecialisationEngine = BrutalSpecialisationEngine


class MatchFeatureIntegrityGate:
    """Hard feature-coverage gate for match-level execution.

    The model is allowed to run only if the core context buckets are present or
    sufficiently proxied from the live fixture row. This prevents the math core
    from silently executing on incomplete research context.
    """

    REQUIRED_BUCKETS = {
        "weather": ("weather_temp", "weather_humidity", "weather_wind", "weather_rain"),
        "travel": ("travel_home", "travel_away"),
        "referee": ("referee_avg_cards", "referee_home_bias"),
        "form": ("form_home", "form_away", "form_trend_home", "form_trend_away"),
        "h2h": ("h2h_home_win_rate", "h2h_avg_goals"),
        "lineup": ("lineup_strength_home", "lineup_strength_away"),
        "injury": ("injury_impact_home", "injury_impact_away"),
        "market": ("sharp_money", "public_money", "bookmaker_margin"),
        "social": ("public_hype_home", "public_hype_away", "awareness_score", "herd_bias_score"),
        "research": ("research_confidence", "source_reliability"),
        "fixture": ("stadium_altitude_m", "pitch_width_m", "pitch_length_m", "kickoff_hour"),
    }

    @staticmethod
    def _present_score(feats: Dict[str, Any], keys: Tuple[str, ...]) -> float:
        if not keys:
            return 0.0
        present = 0
        total = len(keys)
        for key in keys:
            value = feats.get(key)
            if value is None:
                continue
            if isinstance(value, str) and not value.strip():
                continue
            try:
                numeric = float(value)
                if math.isfinite(numeric):
                    present += 1
            except Exception:
                present += 1
        return present / max(1, total)

    def evaluate(self, match_row: Dict[str, Any], feats: Dict[str, Any]) -> Dict[str, float]:
        present_buckets = 0
        missing_buckets = []
        for bucket, keys in self.REQUIRED_BUCKETS.items():
            bucket_score = self._present_score(feats, keys)
            if bucket_score >= 0.75:
                present_buckets += 1
            else:
                missing_buckets.append(bucket)

        research_confidence = float(feats.get("research_confidence", feats.get("source_reliability", 0.0) or 0.0) or 0.0)
        source_reliability = float(feats.get("source_reliability", research_confidence) or 0.0)
        source_coverage = float(match_row.get("source_coverage_count", 0) or 0.0)
        source_total = max(1.0, float(match_row.get("source_coverage_total", 12.0) or 12.0))
        source_ratio = min(1.0, source_coverage / source_total)

        audit_score = (present_buckets / max(1, len(self.REQUIRED_BUCKETS))) * 0.8
        audit_score += min(1.0, research_confidence) * 0.1
        audit_score += min(1.0, source_reliability) * 0.05
        audit_score += source_ratio * 0.05
        audit_score = max(0.0, min(1.0, audit_score))

        return {
            "feature_audit_score": float(audit_score),
            "feature_audit_pass": 1.0 if audit_score >= 0.78 else 0.0,
            "feature_gap_count": float(len(missing_buckets)),
            "feature_gap_buckets": float(len(missing_buckets)),
            "research_confidence": float(research_confidence),
            "source_reliability": float(source_reliability),
            "feature_gate_blocked": 1.0 if audit_score < 0.78 else 0.0,
            "feature_gate_context_coverage": float(source_ratio),
        }


MATCH_FEATURE_INTEGRITY_GATE = MatchFeatureIntegrityGate()

#region Feature Engine
# ======================================================================
# FEATURE ENGINE
# ======================================================================
class FeatureEngine:
    """Extracts, caches, and validates features for matches. 
    
    Uses an async TTL cache to avoid recomputing features for the same fixture.
    Tracks feature statistics for drift detection and missing-data diagnostics.
    """
    _cache = {}
    _cache_ts = {}
    _cache_lock = asyncio.Lock()
    _cache_ttl = CONFIG.cache_ttl
    _max_size = CONFIG.feature_cache_max_size
    _missing_log = defaultdict(int)
    _dynamic_features = []
    _feature_stats: Dict[str, List[float]] = defaultdict(list)
    _feature_stats_lock = asyncio.Lock()

    @classmethod
    def _prune_cache(cls, now: Optional[float] = None) -> None:
        now = float(now or time.time())
        cutoff = now - max(float(cls._cache_ttl), 3600.0)
        stale_keys = [key for key, ts in cls._cache_ts.items() if float(ts) < cutoff]
        for key in stale_keys:
            cls._cache.pop(key, None)
            cls._cache_ts.pop(key, None)
        if len(cls._cache) > cls._max_size:
            keys = sorted(cls._cache_ts.items(), key=lambda kv: kv[1])[: max(1, len(cls._cache) // 2)]
            for key, _ in keys:
                cls._cache.pop(key, None)
                cls._cache_ts.pop(key, None)

    @staticmethod
    def _cleanse(val, default=0.0):
        if val is None:
            return default
        if isinstance(val, float) and (np.isnan(val) or np.isinf(val)):
            return default
        try:
            return float(val)
        except Exception:
            if CONFIG.log_missing_data:
                log.debug(f"Feature cleanse fallback for non-numeric value: {val}")
            return default

    @classmethod
    def _log_missing(cls, field_name: str):
        if CONFIG.log_missing_data:
            cls._missing_log[field_name] += 1

    @classmethod
    def _impute(cls, val, field_name: str, default: float = 0.0) -> float:
        if val is None or (isinstance(val, float) and (np.isnan(val) or np.isinf(val))):
            cls._log_missing(field_name)
            strategy = str(CONFIG.imputation_strategy or "default").lower()
            if strategy == "mean":
                history = cls._feature_stats.get(field_name, [])
                if history:
                    return float(np.mean(history[-500:]))
                return default
            elif strategy == "median":
                history = cls._feature_stats.get(field_name, [])
                if history:
                    return float(np.median(history[-500:]))
                return default
            else:
                return default
        try:
            fv = float(val)
            if math.isfinite(fv):
                cls._feature_stats[field_name].append(fv)
                if len(cls._feature_stats[field_name]) > 2000:
                    cls._feature_stats[field_name] = cls._feature_stats[field_name][-1000:]
            return fv
        except Exception:
            return default

    @staticmethod
    def _safe_series(values: Any, fallback: Optional[List[float]] = None) -> List[float]:
        if isinstance(values, list):
            seq = values
        elif isinstance(values, tuple):
            seq = list(values)
        else:
            seq = fallback or []
        out = []
        for v in seq:
            try:
                fv = float(v)
                if math.isfinite(fv):
                    out.append(fv)
            except Exception:
                continue
        return out

    @staticmethod
    def _adaptive_ewma_from_history(history: List[float], current: float, base_half_life: float = 6.0) -> float:
        if not history:
            return float(current)
        arr = np.array(history[-30:], dtype=float)
        if arr.size < 2:
            return float(current)
        variance = float(np.var(arr))
        median_abs = float(np.median(np.abs(arr - np.median(arr))) + 1e-9)
        shock_ratio = variance / (median_abs * median_abs + 1e-9)
        half_life = max(2.0, base_half_life * (0.5 if shock_ratio > 3.0 else 1.0))
        alpha = 1.0 - math.exp(-math.log(2.0) / half_life)
        ewma = arr[0]
        for value in arr[1:]:
            ewma = alpha * value + (1.0 - alpha) * ewma
        return float(alpha * current + (1.0 - alpha) * ewma)

    @staticmethod
    def _rolling_spearman_proxy(x: List[float], y: List[float], fallback: float = 0.15) -> float:
        n = min(len(x), len(y), 10)
        if n < 4:
            return fallback
        xs = np.array(x[-n:], dtype=float)
        ys = np.array(y[-n:], dtype=float)
        try:
            corr = np.corrcoef(xs.argsort().argsort(), ys.argsort().argsort())[0, 1]
            if not math.isfinite(corr):
                return fallback
            return float(max(-0.8, min(0.8, corr)))
        except Exception:
            return fallback

    @staticmethod
    def _cusum_break_flag(history: List[float], drift: float = 0.03, threshold: float = 0.8) -> float:
        if len(history) < 6:
            return 0.0
        arr = np.array(history[-20:], dtype=float)
        center = float(np.mean(arr))
        pos = neg = 0.0
        for value in arr:
            pos = max(0.0, pos + (value - center - drift))
            neg = min(0.0, neg + (value - center + drift))
            if pos > threshold or abs(neg) > threshold:
                return 1.0
        return 0.0

    @staticmethod
    def _cornish_fisher_var(returns: List[float], alpha: float = 0.95) -> float:
        if len(returns) < 8:
            return 0.0
        arr = np.array(returns[-100:], dtype=float)
        mu = float(np.mean(arr))
        sigma = float(np.std(arr) + 1e-9)
        centered = arr - mu
        skew = float(np.mean((centered / sigma) ** 3))
        kurt = float(np.mean((centered / sigma) ** 4) - 3.0)
        z = 1.6448536269514722 if alpha >= 0.95 else 1.2815515655446004
        z_cf = z + ((z * z - 1.0) * skew / 6.0) + ((z ** 3 - 3.0 * z) * kurt / 24.0) - ((2.0 * z ** 3 - 5.0 * z) * skew * skew / 36.0)
        return float(mu - sigma * z_cf)

    @staticmethod
    def _mahalanobis_guard(vector: List[float], center: List[float], scales: List[float]) -> float:
        if not vector or len(vector) != len(center) or len(vector) != len(scales):
            return 0.0
        total = 0.0
        for i, value in enumerate(vector):
            scale = max(1e-6, float(scales[i]))
            total += ((float(value) - float(center[i])) / scale) ** 2
        distance = math.sqrt(max(0.0, total))
        return 1.0 if distance > 3.2 else 0.0

    @staticmethod
    def _bayes_bootstrap_kelly(prob: float, odds: float, samples: int = 128) -> float:
        if odds <= 1.0:
            return 0.0
        p = min(0.999, max(0.001, float(prob)))
        draws = np.random.beta(1.0 + p * 20.0, 1.0 + (1.0 - p) * 20.0, size=max(32, samples))
        kelly = np.maximum(0.0, (draws * odds - 1.0) / (odds - 1.0 + 1e-9))
        return float(np.percentile(kelly, 5))

    @staticmethod
    def _generate_decay_features(prefix: str, values: List[float], windows: List[int], decays: List[str]) -> Dict[str, float]:
        out = {}
        if not values:
            return out
        series = np.array(values, dtype=float)
        for w in windows:
            chunk = series[-w:] if series.size >= w else series
            if chunk.size == 0:
                continue
            for decay in decays:
                if decay == "linear":
                    weights = np.linspace(0.2, 1.0, num=chunk.size)
                elif decay == "sqrt":
                    weights = np.sqrt(np.linspace(0.1, 1.0, num=chunk.size))
                else:
                    weights = np.exp(np.linspace(-1.0, 0.0, num=chunk.size))
                val = float(np.average(chunk, weights=weights))
                out[f"decayed_{prefix}_{decay}_{w}"] = val
        return out

    @classmethod
    async def build_features(cls, match_row, state):
        fixture_id = match_row.get('fixture_id', '')
        match_date = match_row.get('match_date', '')
        key = f"{fixture_id}_{state.get('elo_version',0)}_{match_date}"
        now = time.time()
        async with cls._cache_lock:
            cls._prune_cache(now)
            if key in cls._cache and now - cls._cache_ts.get(key, 0) < cls._cache_ttl:
                return cls._cache[key]

        feats = {}
        try:
            elo_h = state.get("team_elo", {}).get(match_row.get("home", ""), 1500)
            elo_a = state.get("team_elo", {}).get(match_row.get("away", ""), 1500)
            feats["elo_difference"] = cls._cleanse(elo_h - elo_a)

            feats["home_xg"] = cls._impute(match_row.get("home_xg"), "home_xg", 1.2)
            feats["away_xg"] = cls._impute(match_row.get("away_xg"), "away_xg", 1.0)
            feats["home_shots"] = cls._impute(match_row.get("home_shots"), "home_shots", 10)
            feats["away_shots"] = cls._impute(match_row.get("away_shots"), "away_shots", 8)
            feats["home_corners"] = cls._impute(match_row.get("home_corners"), "home_corners", 5)
            feats["away_corners"] = cls._impute(match_row.get("away_corners"), "away_corners", 4)
            feats["home_cards"] = cls._impute(match_row.get("home_cards"), "home_cards", 2)
            feats["away_cards"] = cls._impute(match_row.get("away_cards"), "away_cards", 2)
            feats["odds_home"] = cls._impute(match_row.get("odds_home"), "odds_home", 2.0)
            feats["odds_draw"] = cls._impute(match_row.get("odds_draw"), "odds_draw", 3.5)
            feats["odds_away"] = cls._impute(match_row.get("odds_away"), "odds_away", 4.0)
            feats["weather_temp"] = cls._impute(match_row.get("weather_temp"), "weather_temp", 15)
            feats["weather_humidity"] = cls._impute(match_row.get("weather_humidity"), "weather_humidity", 50)
            feats["weather_wind"] = cls._impute(match_row.get("weather_wind"), "weather_wind", 5)
            feats["weather_rain"] = cls._impute(match_row.get("weather_rain"), "weather_rain", 0)
            feats["referee_avg_cards"] = cls._impute(match_row.get("referee_avg_cards"), "referee_avg_cards", 4.5)
            feats["referee_home_bias"] = cls._impute(match_row.get("referee_home_bias"), "referee_home_bias", 0)
            feats["referee_penalty_rate"] = cls._impute(match_row.get("referee_penalty_rate"), "referee_penalty_rate", 0.05)
            feats["referee_red_card_rate"] = cls._impute(match_row.get("referee_red_card_rate"), "referee_red_card_rate", 0.02)
            feats["travel_home"] = cls._impute(match_row.get("travel_distance_home", 0), "travel_home", 0) / 1000.0
            feats["travel_away"] = cls._impute(match_row.get("travel_distance_away", 0), "travel_away", 0) / 1000.0
            feats["travel_jetlag_hours"] = cls._impute(match_row.get("travel_jetlag_hours"), "travel_jetlag_hours", 0)
            feats["stadium_altitude_m"] = cls._impute(match_row.get("stadium_altitude"), "stadium_altitude", 120)
            feats["pitch_width_m"] = cls._impute(match_row.get("pitch_width"), "pitch_width", 68)
            feats["pitch_length_m"] = cls._impute(match_row.get("pitch_length"), "pitch_length", 105)
            feats["kickoff_hour"] = cls._impute(match_row.get("kickoff_hour"), "kickoff_hour", 15)
            feats["days_since_last_home"] = cls._impute(match_row.get("days_since_last_home"), "days_since_last_home", 7)
            feats["days_since_last_away"] = cls._impute(match_row.get("days_since_last_away"), "days_since_last_away", 7)
            feats["congestion_home"] = cls._impute(match_row.get("fixtures_14d_home", 2), "congestion_home", 2) / 5.0
            feats["congestion_away"] = cls._impute(match_row.get("fixtures_14d_away", 2), "congestion_away", 2) / 5.0
            league_volatility = cls._cleanse(match_row.get("league_volatility", CONFIG.bivariate_cov_factor), default=0.5)
            form_age_home = cls._cleanse(match_row.get("form_age_days_home", match_row.get("days_since_last_home", 7)), default=7)
            form_age_away = cls._cleanse(match_row.get("form_age_days_away", match_row.get("days_since_last_away", 7)), default=7)
            feats["form_home"] = apply_exponential_time_decay(match_row.get("form_home"), form_age_home, league_volatility, neutral=0.5)
            feats["form_away"] = apply_exponential_time_decay(match_row.get("form_away"), form_age_away, league_volatility, neutral=0.5)
            feats["form_trend_home"] = cls._impute(match_row.get("form_trend_home"), "form_trend_home", 0)
            feats["form_trend_away"] = cls._impute(match_row.get("form_trend_away"), "form_trend_away", 0)
            feats["h2h_home_win_rate"] = cls._impute(match_row.get("h2h_home_win_rate"), "h2h_home_win_rate", 0.5)
            feats["h2h_avg_goals"] = cls._impute(match_row.get("h2h_avg_goals"), "h2h_avg_goals", 2.5)
            feats["h2h_corners_avg"] = cls._impute(match_row.get("h2h_corners_avg"), "h2h_corners_avg", max(4.0, (feats["home_corners"] + feats["away_corners"]) / 2.0))
            feats["h2h_cards_avg"] = cls._impute(match_row.get("h2h_cards_avg"), "h2h_cards_avg", max(3.0, (feats["home_cards"] + feats["away_cards"]) / 2.0))
            feats["h2h_btts_rate"] = cls._impute(match_row.get("h2h_btts_rate"), "h2h_btts_rate", 0.5)
            feats["h2h_clean_sheet_home"] = cls._impute(match_row.get("h2h_clean_sheet_home"), "h2h_clean_sheet_home", 0.4)
            feats["h2h_clean_sheet_away"] = cls._impute(match_row.get("h2h_clean_sheet_away"), "h2h_clean_sheet_away", 0.3)
            feats["h2h_first_half_goal_avg"] = cls._impute(match_row.get("h2h_first_half_goal_avg"), "h2h_first_half_goal_avg", 0.9)
            feats["h2h_second_half_goal_diff"] = cls._impute(match_row.get("h2h_second_half_goal_diff"), "h2h_second_half_goal_diff", 0.0)
            feats["lineup_strength_home"] = cls._impute(match_row.get("lineup_strength_home"), "lineup_strength_home", 0.8)
            feats["lineup_strength_away"] = cls._impute(match_row.get("lineup_strength_away"), "lineup_strength_away", 0.8)
            feats["injury_impact_home"] = cls._impute(match_row.get("injury_impact_home"), "injury_impact_home", 0)
            feats["injury_impact_away"] = cls._impute(match_row.get("injury_impact_away"), "injury_impact_away", 0)
            feats["minutes_played_home_7d"] = cls._impute(match_row.get("minutes_played_home_7d"), "minutes_played_home_7d", 540)
            feats["minutes_played_away_7d"] = cls._impute(match_row.get("minutes_played_away_7d"), "minutes_played_away_7d", 540)
            feats["home_sprints_last_match"] = cls._impute(match_row.get("home_sprints_last_match"), "home_sprints_last_match", 120)
            feats["away_sprints_last_match"] = cls._impute(match_row.get("away_sprints_last_match"), "away_sprints_last_match", 110)
            feats["sharp_money"] = cls._impute(match_row.get("sharp_money_signal"), "sharp_money_signal", 0)
            feats["public_money"] = cls._impute(match_row.get("public_money_signal"), "public_money_signal", 0)
            feats["bookmaker_margin"] = cls._impute(match_row.get("bookmaker_margin"), "bookmaker_margin", 0.05)
            feats["news_volume_home"] = cls._impute(match_row.get("news_volume_home"), "news_volume_home", 0.5)
            feats["news_volume_away"] = cls._impute(match_row.get("news_volume_away"), "news_volume_away", 0.5)
            feats["betting_exchange_liquidity"] = cls._impute(match_row.get("betting_exchange_liquidity"), "betting_exchange_liquidity", 0.5)
            feats["research_confidence"] = cls._impute(match_row.get("research_confidence"), "research_confidence", 0.5)
            feats["source_reliability"] = cls._impute(match_row.get("source_reliability"), "source_reliability", 0.5)

            specialisation_engine = state.get("specialisation_engine") if hasattr(state, "get") else None
            if specialisation_engine is None:
                specialisation_engine = BrutalSpecialisationEngine(state=state)
            specialisation_payload = specialisation_engine.ingest_all_signals(match_row, feats)
            feats.update(specialisation_payload)
            feats["home_xg_specialised"] = cls._cleanse(feats["home_xg"] * float(specialisation_payload.get("home_xg_specialisation_multiplier", 1.0)), default=feats["home_xg"])
            feats["away_xg_specialised"] = cls._cleanse(feats["away_xg"] * float(specialisation_payload.get("away_xg_specialisation_multiplier", 1.0)), default=feats["away_xg"])
            feats["home_xg"] = feats["home_xg_specialised"]
            feats["away_xg"] = feats["away_xg_specialised"]

            feats["pressing_home"] = feats["home_shots"] / 20.0
            feats["pressing_away"] = feats["away_shots"] / 20.0
            pos_h = feats["home_corners"]
            pos_a = feats["away_corners"]
            feats["possession_home"] = pos_h / (pos_h + pos_a + 1e-9)
            feats["possession_away"] = 1 - feats["possession_home"]
            feats["attack_home"] = feats["home_xg"] / 1.5
            feats["attack_away"] = feats["away_xg"] / 1.5
            feats["defense_home"] = 1 - (feats["away_xg"] / 2.0)
            feats["defense_away"] = 1 - (feats["home_xg"] / 2.0)
            feats["regime_volatility"] = cls._impute(match_row.get("regime_volatility"), "regime_volatility", 0)
            feats["corner_rate_home"] = feats["home_corners"] / 10.0
            feats["corner_rate_away"] = feats["away_corners"] / 10.0
            feats["card_rate_home"] = feats["home_cards"] / 5.0
            feats["card_rate_away"] = feats["away_cards"] / 5.0
            feats["is_derby"] = cls._impute(match_row.get("is_derby"), "is_derby", 0)
            feats["is_relegation"] = cls._impute(match_row.get("is_relegation"), "is_relegation", 0)
            feats["is_international_break"] = cls._impute(match_row.get("is_international_break"), "is_international_break", 0)
            feats["is_transfer_window"] = cls._impute(match_row.get("is_transfer_window"), "is_transfer_window", 0)
            feats["sentiment_home"] = cls._impute(match_row.get("sentiment_home"), "sentiment_home", 0.5)
            feats["sentiment_away"] = cls._impute(match_row.get("sentiment_away"), "sentiment_away", 0.5)
            feats["news_sentiment"] = cls._impute(match_row.get("news_sentiment"), "news_sentiment", 0.5)
            feats["public_hype_home"] = cls._impute(match_row.get("public_hype_home"), "public_hype_home", 0.5)
            feats["public_hype_away"] = cls._impute(match_row.get("public_hype_away"), "public_hype_away", 0.5)
            feats["public_model_home_prob"] = cls._impute(match_row.get("public_model_home_prob"), "public_model_home_prob", 0.35)
            feats["public_model_draw_prob"] = cls._impute(match_row.get("public_model_draw_prob"), "public_model_draw_prob", 0.30)
            feats["public_model_away_prob"] = cls._impute(match_row.get("public_model_away_prob"), "public_model_away_prob", 0.35)
            feats["herd_bias_score"] = cls._impute(match_row.get("herd_bias_score"), "herd_bias_score", 0.0)
            feats["sharp_public_divergence"] = cls._impute(match_row.get("sharp_public_divergence"), "sharp_public_divergence", 0.0)
            feats["awareness_score"] = cls._impute(match_row.get("awareness_score"), "awareness_score", 0.5)

            integrity_audit = MATCH_FEATURE_INTEGRITY_GATE.evaluate(match_row, feats)
            feats.update(integrity_audit)

            # Additional advanced stats
            feats["possession_home"] = cls._impute(match_row.get("possession_home"), "possession_home", 0.5)
            feats["possession_away"] = cls._impute(match_row.get("possession_away"), "possession_away", 0.5)
            feats["shots_on_target_home"] = cls._impute(match_row.get("shots_on_target_home"), "shots_on_target_home", 5.0)
            feats["shots_on_target_away"] = cls._impute(match_row.get("shots_on_target_away"), "shots_on_target_away", 4.0)
            feats["big_chances_home"] = cls._impute(match_row.get("big_chances_home"), "big_chances_home", 1.0)
            feats["big_chances_away"] = cls._impute(match_row.get("big_chances_away"), "big_chances_away", 0.8)
            feats["goalkeeper_saves_home"] = cls._impute(match_row.get("goalkeeper_saves_home"), "goalkeeper_saves_home", 3.0)
            feats["goalkeeper_saves_away"] = cls._impute(match_row.get("goalkeeper_saves_away"), "goalkeeper_saves_away", 3.0)
            feats["red_cards_home"] = cls._impute(match_row.get("red_cards_home"), "red_cards_home", 0)
            feats["red_cards_away"] = cls._impute(match_row.get("red_cards_away"), "red_cards_away", 0)
            feats["penalties_home"] = cls._impute(match_row.get("penalties_home"), "penalties_home", 0)
            feats["penalties_away"] = cls._impute(match_row.get("penalties_away"), "penalties_away", 0)
            feats["substitutions_home"] = cls._impute(match_row.get("substitutions_home"), "substitutions_home", 3)
            feats["substitutions_away"] = cls._impute(match_row.get("substitutions_away"), "substitutions_away", 3)
            feats["manager_change_home"] = cls._impute(match_row.get("manager_change_home"), "manager_change_home", 0)
            feats["manager_change_away"] = cls._impute(match_row.get("manager_change_away"), "manager_change_away", 0)
            feats["squad_value_home"] = cls._impute(match_row.get("squad_value_home"), "squad_value_home", 100.0)
            feats["squad_value_away"] = cls._impute(match_row.get("squad_value_away"), "squad_value_away", 100.0)

            feats["shot_accuracy_home"] = feats["shots_on_target_home"] / (feats["home_shots"] + 0.01)
            feats["shot_accuracy_away"] = feats["shots_on_target_away"] / (feats["away_shots"] + 0.01)
            feats["big_chance_conversion_home"] = feats["home_xg"] / (feats["big_chances_home"] + 0.01)
            feats["big_chance_conversion_away"] = feats["away_xg"] / (feats["big_chances_away"] + 0.01)
            feats["saves_ratio_home"] = feats["goalkeeper_saves_home"] / (feats["goalkeeper_saves_home"] + feats["goalkeeper_saves_away"] + 0.01)
            feats["saves_ratio_away"] = 1 - feats["saves_ratio_home"]
            feats["discipline_diff"] = (feats["red_cards_home"] + feats["home_cards"]) - (feats["red_cards_away"] + feats["away_cards"])
            feats["penalty_impact"] = feats["penalties_home"] - feats["penalties_away"]
            feats["subs_remaining_home"] = max(0, 5 - feats["substitutions_home"])
            feats["subs_remaining_away"] = max(0, 5 - feats["substitutions_away"])
            feats["manager_change_flag"] = 1 if (feats["manager_change_home"] + feats["manager_change_away"]) > 0 else 0
            feats["squad_value_ratio"] = feats["squad_value_home"] / (feats["squad_value_away"] + 0.01)
            feats["coverage_pressure_home"] = feats["minutes_played_home_7d"] / 600.0
            feats["coverage_pressure_away"] = feats["minutes_played_away_7d"] / 600.0
            feats["sprint_load_home"] = feats["home_sprints_last_match"] / 150.0
            feats["sprint_load_away"] = feats["away_sprints_last_match"] / 150.0
            feats["speech_pressure_home"] = feats["news_volume_home"] * feats["sentiment_home"]
            feats["speech_pressure_away"] = feats["news_volume_away"] * feats["sentiment_away"]
            feats["market_stress_index"] = feats["sharp_public_divergence"] + feats["bookmaker_margin"]
            feats["goal_control_h2h_bias"] = feats["h2h_clean_sheet_home"] - feats["h2h_clean_sheet_away"]
            feats["dynamic_kickoff_factor"] = max(0.0, min(1.0, abs(feats["kickoff_hour"] - 15.0) / 5.0))

            feats["implied_home"] = 1.0 / max(feats["odds_home"], 1.01)
            feats["implied_draw"] = 1.0 / max(feats["odds_draw"], 1.01)
            feats["implied_away"] = 1.0 / max(feats["odds_away"], 1.01)

            feats["xg_ratio"] = feats["home_xg"] / (feats["away_xg"] + 0.01)
            feats["shot_ratio"] = feats["home_shots"] / (feats["away_shots"] + 0.01)
            feats["form_diff"] = feats["form_home"] - feats["form_away"]

            # Pillar upgrades: non-stationary adaptation, robustness, microstructure and risk guards.
            home_form_hist = cls._safe_series(match_row.get("history_form_home"), [feats["form_home"]])
            away_form_hist = cls._safe_series(match_row.get("history_form_away"), [feats["form_away"]])
            goal_diff_hist = cls._safe_series(match_row.get("history_goal_diff"), [feats["home_xg"] - feats["away_xg"]])
            total_goals_hist = cls._safe_series(match_row.get("history_total_goals"), [feats["home_xg"] + feats["away_xg"]])
            home_xg_hist = cls._safe_series(match_row.get("history_home_xg"), [feats["home_xg"]])
            away_xg_hist = cls._safe_series(match_row.get("history_away_xg"), [feats["away_xg"]])
            odds_home_hist = cls._safe_series(match_row.get("history_odds_home"), [feats["odds_home"]])
            sharp_hist = cls._safe_series(match_row.get("history_sharp_money"), [feats["sharp_money"]])
            sentiment_hist = cls._safe_series(match_row.get("history_news_sentiment"), [feats["news_sentiment"]])
            returns_hist = cls._safe_series(match_row.get("history_returns"), [])

            feats["adaptive_form_home"] = cls._adaptive_ewma_from_history(home_form_hist, feats["form_home"])
            feats["adaptive_form_away"] = cls._adaptive_ewma_from_history(away_form_hist, feats["form_away"])
            feats["manager_break_home"] = cls._cusum_break_flag(home_xg_hist)
            feats["manager_break_away"] = cls._cusum_break_flag(away_xg_hist)
            feats["open_regime_flag"] = 1.0 if np.mean(total_goals_hist[-8:]) > 2.9 else 0.0
            feats["copula_cov_factor_dynamic"] = max(0.05, min(0.35, 0.2 + 0.15 * cls._rolling_spearman_proxy(home_xg_hist, away_xg_hist)))
            feats["odds_ou_z_home"] = (feats["odds_home"] - float(np.mean(odds_home_hist[-12:]))) / (float(np.std(odds_home_hist[-12:])) + 1e-9)

            saves_h = max(0.0, feats["goalkeeper_saves_home"])
            saves_a = max(0.0, feats["goalkeeper_saves_away"])
            prior_alpha = 8.0
            prior_beta = 8.0
            feats["bayes_saves_home"] = (saves_h + prior_alpha) / (saves_h + saves_a + prior_alpha + prior_beta + 1e-9)
            feats["bayes_saves_away"] = 1.0 - feats["bayes_saves_home"]

            feats["sentiment_volatility"] = float(np.std(sentiment_hist[-10:])) if sentiment_hist else 0.0
            feats["market_vwap_home"] = cls._cleanse(match_row.get("market_vwap_home"), default=feats["odds_home"])
            feats["predicted_slippage"] = max(0.0, 0.002 + 0.03 * (cls._cleanse(match_row.get("proposed_stake"), 0.0) / (cls._cleanse(match_row.get("market_depth"), 100.0) + 1e-9)))
            feats["latency_ms"] = cls._cleanse(match_row.get("latency_ms"), default=0.0)
            feats["latency_stale_flag"] = 1.0 if feats["latency_ms"] > 200.0 else 0.0
            feats["market_depth"] = cls._cleanse(match_row.get("market_depth"), default=100.0)
            feats["liquidity_ok"] = 1.0 if feats["market_depth"] >= 100.0 else 0.0

            best_bid = cls._cleanse(match_row.get("best_bid"), default=feats["odds_home"])
            best_ask = cls._cleanse(match_row.get("best_ask"), default=feats["odds_home"])
            bid_vol = max(1.0, cls._cleanse(match_row.get("best_bid_volume"), default=1.0))
            ask_vol = max(1.0, cls._cleanse(match_row.get("best_ask_volume"), default=1.0))
            feats["micro_price_home"] = (best_bid * ask_vol + best_ask * bid_vol) / (bid_vol + ask_vol)

            feats["cornish_fisher_var_95"] = cls._cornish_fisher_var(returns_hist, alpha=0.95)
            feats["kelly_conservative_home"] = cls._bayes_bootstrap_kelly(max(1e-4, feats["implied_home"]), feats["odds_home"])

            vector = [feats["odds_home"], feats["odds_draw"], feats["odds_away"], feats["home_xg"], feats["away_xg"], feats["form_home"], feats["form_away"]]
            center = [2.25, 3.50, 3.60, 1.35, 1.20, 0.50, 0.50]
            scales = [0.80, 1.10, 1.20, 0.70, 0.65, 0.20, 0.20]
            feats["anomaly_mahalanobis_flag"] = cls._mahalanobis_guard(vector, center, scales)
            feats["xg_outlier_flag"] = 1.0 if abs(feats["home_xg"] - 1.35) / 0.70 > 3.0 or abs(feats["away_xg"] - 1.20) / 0.65 > 3.0 else 0.0

            dynamic_decay = {}
            dynamic_decay.update(cls._generate_decay_features("xg_home", home_xg_hist, windows=[5, 10, 20], decays=["linear", "exp", "sqrt"]))
            dynamic_decay.update(cls._generate_decay_features("xg_away", away_xg_hist, windows=[5, 10, 20], decays=["linear", "exp", "sqrt"]))
            dynamic_decay.update(cls._generate_decay_features("goal_diff", goal_diff_hist, windows=[5, 10, 20], decays=["linear", "exp", "sqrt"]))
            dynamic_decay.update(cls._generate_decay_features("sharp", sharp_hist, windows=[5, 10], decays=["linear", "exp"]))
            feats.update(dynamic_decay)

            # Dynamic features from state
            for fname in state.get("seed_features", []):
                if fname in SAFE_FEATURE_LIBRARY:
                    try:
                        val = SAFE_FEATURE_LIBRARY[fname](feats, state)
                        feats[fname] = cls._cleanse(val)
                    except Exception:
                        feats[fname] = 0.0

            feats["data_quality"] = cls._impute(match_row.get("data_quality", 1.0), "data_quality", 1.0)

        except Exception as e:
            log.error(f"Feature build error: {e}")

        async with cls._cache_lock:
            cls._cache[key] = feats
            cls._cache_ts[key] = now
            cls._prune_cache(now)

        return feats

