class RustAccelerator:
    _lib = None
    _load_attempted = False
    _fallback_logged = False

    @classmethod
    def _candidate_paths(cls) -> List[str]:
        base = os.path.dirname(os.path.abspath(__file__))
        env_path = os.environ.get("LHM_RUST_LIB_PATH", "").strip()
        paths = []
        if env_path:
            paths.append(env_path)
        paths.extend([
            os.path.join(base, "polyglot", "rust_execution", "target", "release", "lhm_execution_core.dll"),
            os.path.join(base, "polyglot", "rust_execution", "target", "debug", "lhm_execution_core.dll"),
            os.path.join(base, "polyglot", "rust_execution", "target", "release", "liblhm_execution_core.so"),
            os.path.join(base, "polyglot", "rust_execution", "target", "debug", "liblhm_execution_core.so"),
            os.path.join(base, "polyglot", "rust_execution", "target", "release", "liblhm_execution_core.dylib"),
            os.path.join(base, "polyglot", "rust_execution", "target", "debug", "liblhm_execution_core.dylib"),
        ])
        return paths

    @classmethod
    def _load_lib(cls):
        if cls._load_attempted:
            return cls._lib
        cls._load_attempted = True
        if os.environ.get("LHM_DISABLE_RUST_ACCEL", "0") == "1":
            return None
        for path in cls._candidate_paths():
            if not os.path.exists(path):
                continue
            try:
                lib = ctypes.CDLL(path)
                fn = getattr(lib, "lhm_kelly_fraction", None)
                if fn is None:
                    continue
                fn.argtypes = [ctypes.c_double, ctypes.c_double]
                fn.restype = ctypes.c_double
                cls._lib = lib
                log.info(f"Rust acceleration loaded from {path}")
                return cls._lib
            except Exception as e:
                log.warning(f"Rust library load failed at {path}: {e}")
        if not cls._fallback_logged:
            log.warning("Rust accelerator unavailable; using Python fallback for kelly_fraction.")
            cls._fallback_logged = True
        return None

    @classmethod
    def kelly_fraction(cls, prob: float, odds: float) -> Optional[float]:
        lib = cls._load_lib()
        if lib is None:
            return None
        try:
            return float(lib.lhm_kelly_fraction(float(prob), float(odds)))
        except Exception as e:
            log.warning(f"Rust kelly_fraction call failed: {e}")
            return None


class Calculator:
    """Statistical math engine: joint probability grids, expected goals, and market odds."""
    _match_probs_cache: Dict[Tuple[Any, ...], Tuple[float, NDArray]] = {}

    @staticmethod
    def _prune_match_probs_cache(now: Optional[float] = None) -> None:
        now = float(now or time.time())
        cutoff = now - 3600.0
        stale_keys = [key for key, payload in Calculator._match_probs_cache.items() if float(payload[0]) < cutoff]
        for key in stale_keys:
            Calculator._match_probs_cache.pop(key, None)
        if len(Calculator._match_probs_cache) > 2048:
            keys = sorted(Calculator._match_probs_cache.items(), key=lambda kv: kv[1][0])[:512]
            for key, _ in keys:
                Calculator._match_probs_cache.pop(key, None)

    @staticmethod
    def kelly_fraction(prob, odds):
        try:
            prob = float(prob)
            odds = float(odds)
        except Exception:
            return 0.0
        if not math.isfinite(prob) or not math.isfinite(odds):
            log.warning(f"Kelly input non-finite; prob={prob}, odds={odds}")
            return 0.0
        rust_result = RustAccelerator.kelly_fraction(prob, odds)
        if rust_result is not None:
            return max(0.0, rust_result)
        if odds <= 1.0:
            return 0.0
        kelly = (prob * odds - 1) / (odds - 1)
        return max(0.0, kelly)

    @staticmethod
    def kelly_with_cost(prob, odds, commission=0.02, slippage=0.005):
        net_odds = odds * (1 - commission) * (1 - slippage)
        if net_odds <= 1.0:
            return 0.0
        return (prob * net_odds - 1) / (net_odds - 1)

    @staticmethod
    def match_probs(lam_home: float, lam_away: float, max_goals: int = Constants.DEFAULT_MAX_GOALS, match_row: Optional[Dict[str, Any]] = None) -> NDArray:
        cache_key = (
            round(float(lam_home or 0.0), 4),
            round(float(lam_away or 0.0), 4),
            int(max_goals),
            round(float((match_row or {}).get("league_volatility", 0.5) or 0.5), 3),
            round(float((match_row or {}).get("copula_cov_factor", CONFIG.bivariate_cov_factor) or CONFIG.bivariate_cov_factor), 3),
            round(float((match_row or {}).get("form_age_days_home", (match_row or {}).get("days_since_last_home", 7)) or 7), 2),
        )
        now = time.time()
        Calculator._prune_match_probs_cache(now)
        cached = Calculator._match_probs_cache.get(cache_key)
        if cached and now - cached[0] <= 120:
            return cached[1]
        if CONFIG.enable_advanced_math:
            league_volatility = 0.5
            time_decay = 1.0
            cov_factor = CONFIG.bivariate_cov_factor
            model_blend = 0.6
            dispersion = 10.0
            if match_row is not None:
                try:
                    league_volatility = float(match_row.get("league_volatility", CONFIG.bivariate_cov_factor) or CONFIG.bivariate_cov_factor)
                    time_decay = float(match_row.get("form_age_days_home", match_row.get("days_since_last_home", 7)) or 7)
                    time_decay = max(0.3, min(1.2, 1.0 / (1.0 + 0.03 * time_decay)))
                    cov_factor = max(0.05, min(0.35, float(match_row.get("copula_cov_factor", cov_factor)) or cov_factor))
                    # Adapt model blend by regime and volatility instead of fixed 0.6/0.4.
                    is_derby = float(match_row.get("is_derby", 0) or 0)
                    recent_total = float(match_row.get("recent_total_goals", lam_home + lam_away) or (lam_home + lam_away))
                    chaos = max(0.0, min(1.0, 0.6 * abs(recent_total - 2.6) / 2.6 + 0.4 * min(1.0, league_volatility)))
                    model_blend = max(0.35, min(0.8, 0.65 + 0.1 * is_derby - 0.3 * chaos))
                    dispersion = max(4.0, min(30.0, 14.0 - 10.0 * min(1.0, league_volatility) + 2.0 * is_derby))
                except Exception:
                    pass
            biv = AdvancedMathEngine.dynamic_copula_match_probs(lam_home, lam_away, max_goals, cov_factor, league_volatility, time_decay)
            zinb = AdvancedMathEngine.zero_inflated_nbinom_probs(lam_home, lam_away, max_goals, dispersion=dispersion)
            blended = model_blend * biv + (1.0 - model_blend) * zinb
            total = blended.sum()
            out = blended / total if total > 0 else blended
            Calculator._match_probs_cache[cache_key] = (now, out)
            Calculator._prune_match_probs_cache(now)
            return out
        else:
            hg = np.arange(max_goals+1)
            ag = np.arange(max_goals+1)
            H, A = np.meshgrid(hg, ag)
            probs = poisson.pmf(H, lam_home) * poisson.pmf(A, lam_away)
            Calculator._match_probs_cache[cache_key] = (now, probs)
            Calculator._prune_match_probs_cache(now)
            return probs

    @staticmethod
    def poisson_kelly_optimum(lam_home, lam_away, odds_dict, bankroll, max_stake_pct=0.03, match_row=None):
        """Find the line/outcome with the highest de-vigged edge and return Kelly stake.

        Iterates over odds_dict, strips vig using bookmaker_margin from match_row,
        and returns (best_line, best_edge, best_stake).  Stake is capped at
        max_stake_pct of bankroll.
        """
        best_edge = 0.0
        best_stake = 0.0
        best_line = None
        joint = Calculator.match_probs(lam_home, lam_away)
        base_kelly = max(0.01, min(1.0, float(CONFIG.fractional_kelly_factor)))
        margin = 0.05
        if match_row and isinstance(match_row, dict):
            margin = float(match_row.get('bookmaker_margin', margin))
        overround = 1.0 + margin
        home_corners = 0.0
        away_corners = 0.0
        home_cards = 0.0
        away_cards = 0.0
        if isinstance(match_row, dict):
            home_corners = float(match_row.get("home_corners", 0.0) or 0.0)
            away_corners = float(match_row.get("away_corners", 0.0) or 0.0)
            home_cards = float(match_row.get("home_cards", 0.0) or 0.0)
            away_cards = float(match_row.get("away_cards", 0.0) or 0.0)
        for line, odds in odds_dict.items():
            if not isinstance(odds, (int, float)) or odds <= 1:
                continue
            line_lower = str(line).lower().strip()
            if line_lower.startswith("ah_") or line_lower.startswith("asianhandicap_"):
                try:
                    line_val = float(line.split('_')[1])
                except Exception:
                    continue
                prob = 0.0
                if line_val < 0:
                    for hg in range(joint.shape[0]):
                        for ag in range(joint.shape[1]):
                            if hg - ag > abs(line_val):
                                prob += joint[hg, ag]
                elif line_val > 0:
                    for hg in range(joint.shape[0]):
                        for ag in range(joint.shape[1]):
                            if hg - ag >= -line_val:
                                prob += joint[hg, ag]
                else:
                    for hg in range(joint.shape[0]):
                        for ag in range(joint.shape[1]):
                            if hg != ag:
                                prob += joint[hg, ag]
                edge = prob - (1.0 / odds) / overround
                if edge > best_edge:
                    best_edge = edge
                    kelly_stake = (prob * odds - 1) / (odds - 1) * bankroll * base_kelly if odds > 1.0 else 0.0
                    best_stake = min(kelly_stake, bankroll * max_stake_pct)
                    best_line = line
            elif "ou" in line_lower:
                try:
                    line_val = float(line.split('_')[1])
                except Exception:
                    continue
                prob_over = 0.0
                for hg in range(joint.shape[0]):
                    for ag in range(joint.shape[1]):
                        if hg + ag > line_val:
                            prob_over += joint[hg, ag]
                edge = prob_over - (1.0 / odds) / overround
                if edge > best_edge:
                    best_edge = edge
                    kelly_stake = (prob_over * odds - 1) / (odds - 1) * bankroll * base_kelly if odds > 1.0 else 0.0
                    best_stake = min(kelly_stake, bankroll * max_stake_pct)
                    best_line = line
            elif "cs" in line_lower:
                try:
                    score = line.split('_')[1] if '_' in line else line
                    hg, ag = map(int, score.replace('-', '_').split('_'))
                    prob = joint[hg, ag] if hg < joint.shape[0] and ag < joint.shape[1] else 0.0
                    edge = prob - (1.0 / odds) / overround
                    if edge > best_edge:
                        best_edge = edge
                        kelly_stake = (prob * odds - 1) / (odds - 1) * bankroll * base_kelly if odds > 1.0 else 0.0
                        best_stake = min(kelly_stake, bankroll * max_stake_pct * 0.5)
                        best_line = line
                except Exception:
                    continue
            elif "btts" in line_lower:
                prob_yes = float(np.sum(joint[1:, 1:]))
                prob = prob_yes if ("yes" in line_lower) else (1.0 - prob_yes)
                edge = prob - (1.0 / odds) / overround
                if edge > best_edge:
                    best_edge = edge
                    kelly_stake = (prob * odds - 1) / (odds - 1) * bankroll * base_kelly if odds > 1.0 else 0.0
                    best_stake = min(kelly_stake, bankroll * max_stake_pct)
                    best_line = line
            elif "double_chance" in line_lower or line_lower.startswith("odds_double_chance"):
                prob_home = float(np.sum(joint[np.tril_indices_from(joint, k=-1)]))
                prob_draw = float(np.sum(np.diag(joint)))
                prob_away = max(0.0, 1.0 - prob_home - prob_draw)
                key = line.lower()
                if "1x" in key:
                    prob = prob_home + prob_draw
                elif "x2" in key:
                    prob = prob_away + prob_draw
                else:
                    prob = prob_home + prob_away
                edge = prob - (1.0 / odds) / overround
                if edge > best_edge:
                    best_edge = edge
                    kelly_stake = (prob * odds - 1) / (odds - 1) * bankroll * base_kelly if odds > 1.0 else 0.0
                    best_stake = min(kelly_stake, bankroll * max_stake_pct)
                    best_line = line
            elif "corners" in line_lower or "cards" in line_lower:
                if "corners" in line_lower and (home_corners > 0 or away_corners > 0):
                    total_lambda = home_corners + away_corners
                elif "cards" in line_lower and (home_cards > 0 or away_cards > 0):
                    total_lambda = home_cards + away_cards
                else:
                    total_lambda = lam_home + lam_away
                    if "corners" in line_lower:
                        total_lambda *= 3.8
                    else:
                        total_lambda *= 1.6
                if "over" in line_lower:
                    prob = 1.0 - poisson.cdf(max(0, int(round(total_lambda)) - 1), total_lambda)
                elif "under" in line_lower:
                    prob = poisson.cdf(max(0, int(round(total_lambda))), total_lambda)
                else:
                    continue
                edge = prob - (1.0 / odds) / overround
                if edge > best_edge:
                    best_edge = edge
                    kelly_stake = (prob * odds - 1) / (odds - 1) * bankroll * base_kelly if odds > 1.0 else 0.0
                    best_stake = min(kelly_stake, bankroll * max_stake_pct * 0.8)
                    best_line = line
        return best_line, best_edge, best_stake

    @staticmethod
    def adjust_edge_for_margin(edge, bookmaker_margin):
        if bookmaker_margin < 0.03:
            edge *= 1.0
        elif bookmaker_margin > 0.08:
            edge *= 0.8
        else:
            edge *= (1 - (bookmaker_margin - 0.03) / 0.05 * 0.2)
        return edge


class ShinMethodExtractor:
    @staticmethod
    def strip_vig(odds_home: float, odds_draw: float, odds_away: float) -> Tuple[float, float, float]:
        try:
            o_h = max(1.01, float(odds_home))
            o_d = max(1.01, float(odds_draw))
            o_a = max(1.01, float(odds_away))
        except Exception:
            return 0.0, 0.0, 0.0
        implied_sum = 1.0 / o_h + 1.0 / o_d + 1.0 / o_a
        if implied_sum <= 0 or implied_sum > 1.5:
            return 0.0, 0.0, 0.0
        margin = implied_sum - 1.0
        true_h = (1.0 / o_h) - (margin / 3.0)
        true_d = (1.0 / o_d) - (margin / 3.0)
        true_a = (1.0 / o_a) - (margin / 3.0)
        total = true_h + true_d + true_a
        if total <= 0:
            return 0.0, 0.0, 0.0
        return true_h / total, true_d / total, true_a / total

    @staticmethod
    def shin_prob(odds_home: float, odds_draw: float, odds_away: float) -> Dict[str, float]:
        z = 0.0
        o_h = max(1.01, float(odds_home))
        o_d = max(1.01, float(odds_draw))
        o_a = max(1.01, float(odds_away))
        for _ in range(20):
            denom_h = o_h * (1.0 - z * o_h)
            denom_d = o_d * (1.0 - z * o_d)
            denom_a = o_a * (1.0 - z * o_a)
            s = 1.0 / denom_h + 1.0 / denom_d + 1.0 / denom_a
            if abs(s - 1.0) < 1e-9:
                break
            z = (s - 1.0) / (o_h + o_d + o_a)
            z = max(0.0, min(z, 0.49 / max(o_h, o_d, o_a)))
        p_h = max(0.0, 1.0 / (o_h * (1.0 - z * o_h)))
        p_d = max(0.0, 1.0 / (o_d * (1.0 - z * o_d)))
        p_a = max(0.0, 1.0 / (o_a * (1.0 - z * o_a)))
        total = p_h + p_d + p_a
        if total <= 0:
            return {"home": 0.0, "draw": 0.0, "away": 0.0}
        return {"home": p_h / total, "draw": p_d / total, "away": p_a / total}


