# TRAINER (preserved)
# ======================================================================
class Trainer:
    """Model training pipeline with cross-validation, calibration, and persistence."""
    @staticmethod
    def train_market(data, market, model_type="xgb", scaler=None, feature_mask=None, params=None):
        if data.empty or len(data) < CONFIG.min_samples_train:
            return None, None, None

        if market == "1X2":
            data["label"] = (data["home_goals"] > data["away_goals"]).astype(int)
            objective = "binary:logistic"
        elif market == "OverUnder":
            total_goals = data["home_goals"] + data["away_goals"]
            over_line = CONFIG.over_line
            data["label"] = (total_goals > over_line).astype(int)
            objective = "binary:logistic"
        elif market == "BTTS":
            data["label"] = ((data["home_goals"] > 0) & (data["away_goals"] > 0)).astype(int)
            objective = "binary:logistic"
        elif market == "Corners":
            total_corners = data["home_corners"] + data["away_corners"]
            data["label"] = (total_corners > 9.5).astype(int)
            objective = "binary:logistic"
        elif market == "Cards":
            total_cards = data["home_cards"] + data["away_cards"]
            data["label"] = (total_cards > 45).astype(int)
            objective = "binary:logistic"
        else:
            return None, None, None

        order = FeatureEngine.feature_order()
        def safe_build(row):
            return [FeatureEngine._cleanse(row.get(k, 0.0)) for k in order]

        X_full = np.array([safe_build(row) for _, row in data.iterrows()], dtype=np.float32)
        X_full = np.nan_to_num(X_full)
        y = data["label"].values

        if 'timestamp' in data.columns:
            max_ts = float(data['timestamp'].max())
            # Decay relative to the most recent sample (not wall-clock `now`),
            # otherwise multi-year-old data yields ~0 weights and sklearn errors.
            weights = np.exp(-0.01 * (max_ts - np.asarray(data['timestamp'].values, dtype=float)))
            if not np.any(weights):
                weights = np.ones(len(y))
        else:
            weights = np.ones(len(y))

        if feature_mask is None:
            if xgb is not None:
                temp_model = xgb.XGBClassifier(objective=objective, n_estimators=50, max_depth=3)
                temp_model.fit(X_full, y, sample_weight=weights)
                mask = temp_model.feature_importances_ >= np.percentile(temp_model.feature_importances_, 20)
            else:
                temp_model = RandomForestClassifier(n_estimators=50, max_depth=3)
                temp_model.fit(X_full, y, sample_weight=weights)
                mask = temp_model.feature_importances_ >= np.percentile(temp_model.feature_importances_, 20)
            X = X_full[:, mask]
        else:
            X = X_full[:, feature_mask]
            mask = feature_mask

        split_idx = int(0.8 * len(X))
        split_val = int(0.9 * len(X))
        X_train, X_val, X_test = X[:split_idx], X[split_idx:split_val], X[split_val:]
        y_train, y_val, y_test = y[:split_idx], y[split_idx:split_val], y[split_val:]
        w_train, w_val, w_test = weights[:split_idx], weights[split_idx:split_val], weights[split_val:]

        if scaler is None:
            scaler = StandardScaler()
            X_train_scaled = scaler.fit_transform(X_train)
            X_val_scaled = scaler.transform(X_val)
            X_test_scaled = scaler.transform(X_test)
        else:
            X_train_scaled = scaler.transform(X_train)
            X_val_scaled = scaler.transform(X_val)
            X_test_scaled = scaler.transform(X_test)

        models = {}

        hp = params or {"max_depth": 6, "learning_rate": 0.05, "n_estimators": 100}

        if model_type in ("xgb", "all") and xgb:
            model = xgb.XGBClassifier(
                objective=objective,
                n_estimators=hp.get("n_estimators", 100),
                max_depth=hp.get("max_depth", 6),
                learning_rate=hp.get("learning_rate", 0.05),
                subsample=hp.get("subsample", 0.8),
                colsample_bytree=hp.get("colsample_bytree", 0.8),
                random_state=42,
            )
            fit_kwargs = dict(sample_weight=w_train, verbose=False)
            if hasattr(model, 'fit') and 'eval_set' in inspect.signature(model.fit).parameters:
                fit_kwargs['eval_set'] = [(X_val_scaled, y_val)]
                fit_kwargs['sample_weight_eval_set'] = [w_val]
            model.fit(X_train_scaled, y_train, **fit_kwargs)
            calibrated = CalibratedClassifierCV(model, method='isotonic', cv=3)
            calibrated.fit(X_train_scaled, y_train, sample_weight=w_train)
            models["xgb"] = calibrated

        if model_type in ("lgb", "all") and lgb:
            import lightgbm as lgbm
            model = lgbm.LGBMClassifier(
                objective=objective,
                n_estimators=100,
                max_depth=6,
                learning_rate=0.05,
                random_state=42
            )
            fit_kwargs = dict(sample_weight=w_train)
            if hasattr(model, 'fit') and 'eval_set' in inspect.signature(model.fit).parameters:
                fit_kwargs['eval_set'] = [(X_val_scaled, y_val)]
                fit_kwargs['eval_sample_weight'] = [w_val]
            model.fit(X_train_scaled, y_train, **fit_kwargs)
            calibrated = CalibratedClassifierCV(model, method='isotonic', cv=3)
            calibrated.fit(X_train_scaled, y_train, sample_weight=w_train)
            models["lgb"] = calibrated

        if model_type in ("rf", "all"):
            model = RandomForestClassifier(n_estimators=100, max_depth=6, random_state=42)
            model.fit(X_train_scaled, y_train, sample_weight=w_train)
            calibrated = CalibratedClassifierCV(model, method='isotonic', cv=3)
            calibrated.fit(X_train_scaled, y_train, sample_weight=w_train)
            models["rf"] = calibrated

        if model_type in ("lr", "all"):
            model = SGDClassifier(loss='log_loss', penalty='elasticnet', alpha=0.0001, random_state=42)
            model.fit(X_train_scaled, y_train, sample_weight=w_train)
            calibrated = CalibratedClassifierCV(model, method='isotonic', cv=3)
            calibrated.fit(X_train_scaled, y_train, sample_weight=w_train)
            models["lr"] = calibrated
            models["lr_raw"] = model

        if not models:
            return None, None, None
        return models, scaler, mask

    @staticmethod
    def online_update(model, X_batch, y_batch):
        if hasattr(model, 'partial_fit'):
            model.partial_fit(X_batch, y_batch, classes=[0,1])
            return model
        return None

    @staticmethod
    def train_market_purged(data, market, model_type="xgb", scaler=None, feature_mask=None, params=None):
        if data.empty or len(data) < CONFIG.min_samples_train:
            return None, None, None
        if 'timestamp' not in data.columns:
            data['timestamp'] = time.time()
        order = FeatureEngine.feature_order()
        def safe_build(row):
            return [FeatureEngine._cleanse(row.get(k, 0.0)) for k in order]
        X_full = np.array([safe_build(row) for _, row in data.iterrows()], dtype=np.float32)
        X_full = np.nan_to_num(X_full)
        y = data["label"].values if "label" in data.columns else np.zeros(len(data))
        dates = data['timestamp'].values.astype(float)
        if feature_mask is None:
            if xgb is not None:
                temp_model = xgb.XGBClassifier(objective="binary:logistic", n_estimators=50, max_depth=3)
                temp_model.fit(X_full, y)
                mask = temp_model.feature_importances_ >= np.percentile(temp_model.feature_importances_, 20)
            else:
                temp_model = RandomForestClassifier(n_estimators=50, max_depth=3)
                temp_model.fit(X_full, y)
                mask = temp_model.feature_importances_ >= np.percentile(temp_model.feature_importances_, 20)
            X = X_full[:, mask]
        else:
            X = X_full[:, feature_mask]
            mask = feature_mask
        if scaler is None:
            scaler = StandardScaler()
            X_scaled = scaler.fit_transform(X)
        else:
            X_scaled = scaler.transform(X)
        cv = PurgedGroupTimeSeriesSplit(n_splits=5, purge_gap_days=7)
        best_model = None
        best_score = -1.0
        for train_idx, val_idx in cv.split(X_scaled, dates.tolist()):
            if len(train_idx) < 10 or len(val_idx) < 5:
                continue
            X_tr, X_val = X_scaled[train_idx], X_scaled[val_idx]
            y_tr, y_val = y[train_idx], y[val_idx]
            if xgb is not None:
                m = xgb.XGBClassifier(objective="binary:logistic", n_estimators=100, max_depth=6, learning_rate=0.05)
                m.fit(X_tr, y_tr, eval_set=[(X_val, y_val)], verbose=False)
                score = float(roc_auc_score(y_val, m.predict_proba(X_val)[:, 1])) if HAS_SKLEARN else 0.0
            else:
                m = RandomForestClassifier(n_estimators=100, max_depth=6)
                m.fit(X_tr, y_tr)
                score = float(roc_auc_score(y_val, m.predict_proba(X_val)[:, 1])) if HAS_SKLEARN else 0.0
            if score > best_score:
                best_score = score
                best_model = m
        if best_model is not None:
            calibrated = CalibratedClassifierCV(best_model, method='isotonic', cv=3)
            calibrated.fit(X_scaled, y)
            return {"xgb_purged": calibrated}, scaler, mask
        return None, None, None


