# BAYESIAN POISSON MODEL (preserved)
# ======================================================================
class BayesianPoissonModel:
    def __init__(self):
        self.home_attack = None
        self.away_defense = None
        self.away_attack = None
        self.home_defense = None
        self.home_adv = None
        self.trained = False

    def fit(self, data):
        try:
            import pymc as pm
        except ImportError:
            log.warning("pymc not installed; Bayesian model fallback to MLE")
            try:
                import statsmodels.api as sm
                X = pd.DataFrame({'home': data['home_id'], 'away': data['away_id']})
                X = sm.add_constant(X)
                poisson_home = sm.GLM(data['home_goals'], X, family=sm.families.Poisson()).fit()
                poisson_away = sm.GLM(data['away_goals'], X, family=sm.families.Poisson()).fit()
                self.home_adv = poisson_home.params.get('const', 0.1)
                self.home_attack = {i: v for i, v in enumerate(poisson_home.params[1:])}
                self.away_defense = {i: v for i, v in enumerate(poisson_away.params[1:])}
                self.trained = True
                log.info("Bayesian model fallback fitted (GLM).")
            except Exception:
                pass
            return
        if data.empty or 'home_id' not in data.columns:
            return
        try:
            num_teams = max(data['home_id'].max(), data['away_id'].max()) + 1
            with pm.Model() as model:
                home_attack = pm.Normal('home_attack', mu=0, sigma=1, shape=num_teams)
                away_defense = pm.Normal('away_defense', mu=0, sigma=1, shape=num_teams)
                away_attack = pm.Normal('away_attack', mu=0, sigma=1, shape=num_teams)
                home_defense = pm.Normal('home_defense', mu=0, sigma=1, shape=num_teams)
                home_adv = pm.Normal('home_adv', mu=0.1, sigma=0.1)
                home_idx = data['home_id'].values
                away_idx = data['away_id'].values
                lambda_home = pm.math.exp(home_attack[home_idx] - away_defense[away_idx] + home_adv)
                lambda_away = pm.math.exp(away_attack[away_idx] - home_defense[home_idx])
                if CONFIG.enable_negative_binomial:
                    alpha_home = pm.HalfCauchy('alpha_home', beta=1)
                    alpha_away = pm.HalfCauchy('alpha_away', beta=1)
                    y_home = pm.NegativeBinomial('y_home', mu=lambda_home, alpha=alpha_home, observed=data['home_goals'].values)
                    y_away = pm.NegativeBinomial('y_away', mu=lambda_away, alpha=alpha_away, observed=data['away_goals'].values)
                else:
                    y_home = pm.Poisson('y_home', mu=lambda_home, observed=data['home_goals'].values)
                    y_away = pm.Poisson('y_away', mu=lambda_away, observed=data['away_goals'].values)
                trace = pm.sample(1000, tune=500, chains=2, cores=1, progressbar=False)
                rhat_home = pm.rhat(trace.posterior['home_attack']).max().values
                if rhat_home > 1.05:
                    log.warning(f"Bayesian model may not have converged (Rhat={rhat_home:.3f})")
                self.home_attack = trace.posterior['home_attack'].mean().values
                self.away_defense = trace.posterior['away_defense'].mean().values
                self.away_attack = trace.posterior['away_attack'].mean().values
                self.home_defense = trace.posterior['home_defense'].mean().values
                self.home_adv = trace.posterior['home_adv'].mean().values
                self.trained = True
                log.info("Bayesian model fitted.")
        except Exception as e:
            log.warning(f"Bayesian fit failed: {e}")

    def predict_lambdas(self, home_id, away_id):
        if self.trained and home_id >= 0 and away_id >= 0:
            if isinstance(self.home_attack, dict):
                lam_home = np.exp(self.home_attack.get(home_id, 0) - self.away_defense.get(away_id, 0) + self.home_adv)
                lam_away = np.exp(self.away_attack.get(away_id, 0) - self.home_defense.get(home_id, 0))
            else:
                lam_home = np.exp(self.home_attack[home_id] - self.away_defense[away_id] + self.home_adv)
                lam_away = np.exp(self.away_attack[away_id] - self.home_defense[home_id])
            return float(lam_home), float(lam_away)
        return 1.3, 1.3

    def predict_probs(self, lam_home, lam_away):
        max_goals = Constants.DEFAULT_MAX_GOALS
        joint = Calculator.match_probs(lam_home, lam_away)
        p_home = np.sum(joint[np.tril_indices_from(joint, k=-1)])
        p_draw = np.sum(np.diag(joint))
        p_away = 1 - p_home - p_draw
        return [p_home, p_draw, p_away]

# ======================================================================
# ASIAN HANDICAP, CORRECT SCORE, PARLAY (preserved)
# ======================================================================
class AsianHandicap:
    @staticmethod
    def derive_from_probs(prob_home, prob_draw, prob_away):
        expected_diff = (prob_home - prob_away) * 1.5
        lines = {
            "-1.0": {"home": max(1.01, 1/(0.3+0.5*(1-expected_diff))), "away": max(1.01, 1/(0.3+0.5*(1+expected_diff)))},
            "-0.75": {"home": max(1.01, 1/(0.35+0.4*(1-expected_diff))), "away": max(1.01, 1/(0.35+0.4*(1+expected_diff)))},
            "-0.5": {"home": max(1.01, 1/(0.4+0.3*(1-expected_diff))), "away": max(1.01, 1/(0.4+0.3*(1+expected_diff)))},
            "-0.25": {"home": max(1.01, 1/(0.45+0.2*(1-expected_diff))), "away": max(1.01, 1/(0.45+0.2*(1+expected_diff)))},
            "0.0": {"home": max(1.01, 1/0.5), "away": max(1.01, 1/0.5)},
            "+0.25": {"home": max(1.01, 1/(0.55-0.2*expected_diff)), "away": max(1.01, 1/(0.55+0.2*expected_diff))},
            "+0.5": {"home": max(1.01, 1/(0.6-0.3*expected_diff)), "away": max(1.01, 1/(0.6+0.3*expected_diff))},
            "+0.75": {"home": max(1.01, 1/(0.65-0.4*expected_diff)), "away": max(1.01, 1/(0.65+0.4*expected_diff))},
            "+1.0": {"home": max(1.01, 1/(0.7-0.5*expected_diff)), "away": max(1.01, 1/(0.7+0.5*expected_diff))},
        }
        return lines

    @staticmethod
    def settle(line, home_score, away_score):
        goal_diff = home_score - away_score
        if line < 0:
            adjusted_diff = goal_diff + abs(line)
        else:
            adjusted_diff = goal_diff - line
        if adjusted_diff > 0.25:
            return "home"
        elif adjusted_diff < -0.25:
            return "away"
        elif abs(adjusted_diff) < 0.01:
            return "push"
        elif adjusted_diff > 0:
            return "home_half"
        else:
            return "away_half"

class CorrectScoreEvaluator:
    @staticmethod
    def evaluate_all(lam_home, lam_away, odds_dict, min_edge=0.10, league_avg_goals=2.5):
        max_goals = Constants.DEFAULT_MAX_GOALS
        joint = Calculator.match_probs(lam_home, lam_away, max_goals)
        lg = float(max(1.2, min(4.5, league_avg_goals or 2.5)))
        low_goal_factor = max(0.0, min(1.0, (2.6 - lg) / 1.4))
        boost_00 = 0.02 + 0.03 * low_goal_factor
        boost_11 = 0.015 + 0.02 * low_goal_factor
        if joint.shape[0] > 0 and joint.shape[1] > 0:
            joint[0,0] += boost_00 * 0.7
            if joint.shape[0] > 1 and joint.shape[1] > 1:
                joint[1,1] += boost_11 * 0.3
            joint /= joint.sum()
        decisions = []
        for hg in range(min(6, joint.shape[0])):
            for ag in range(min(6, joint.shape[1])):
                prob = joint[hg, ag]
                score_str = f"{hg}-{ag}"
                if score_str in odds_dict:
                    odds = odds_dict[score_str]
                    if odds <= 0:
                        continue
                    edge = prob - (1.0 / odds) / overround
                    if edge > min_edge:
                        decisions.append({"outcome": score_str, "prob": prob, "odds": odds, "edge": edge})
        return decisions

class ParlayEngine:
    @staticmethod
    def build_parlay(decisions, max_legs=5, min_legs=3, min_parlay_edge=0.05):
        if len(decisions) < min_legs:
            return None
        candidates = [d for d in decisions if d.get('edge', 0) > min_parlay_edge]
        candidates = [d for d in candidates if float(d.get('odds', 0) or 0) > 1.0 and float(d.get('prob', 0) or 0) > 0.0]
        if len(candidates) < min_legs:
            return None
        candidates = sorted(candidates, key=lambda x: x['edge'], reverse=True)[:max_legs]
        if len(candidates) < min_legs:
            return None
        combined_odds = np.prod([d['odds'] for d in candidates])
        implied_prob = np.prod([1.0 / d['odds'] for d in candidates])
        penalty = 0.9 ** (len(candidates) - 1)
        est_prob = np.prod([d['prob'] for d in candidates]) * penalty
        edge = est_prob - implied_prob
        if edge < min_parlay_edge:
            return None
        return {
            "legs": candidates,
            "combined_odds": combined_odds,
            "est_prob": est_prob,
            "edge": edge,
            "stake": CONFIG.parlay_stake_fraction
        }

    @staticmethod
    def settle_parlay(legs, results):
        active_legs = []
        mult = 1.0
        for leg in legs:
            fixture_id = leg.get('fixture_id')
            if fixture_id not in results:
                return {"status": "pending"}
            data = results[fixture_id]
            market = leg.get('market')
            outcome = leg.get('outcome')
            line = leg.get('line')
            if market == "1X2":
                h, a = data.get('home_score', 0), data.get('away_score', 0)
                actual = "home" if h > a else "away" if h < a else "draw"
                leg_ok = (actual == outcome)
            elif market == "OverUnder":
                total = data.get('home_score', 0) + data.get('away_score', 0)
                actual = "over" if total > line else "under"
                leg_ok = (actual == outcome)
            elif market == "BTTS":
                h, a = data.get('home_score', 0), data.get('away_score', 0)
                actual = "yes" if (h > 0 and a > 0) else "no"
                leg_ok = (actual == outcome)
            elif market == "Corners":
                total = data.get('home_corners', 0) + data.get('away_corners', 0)
                actual = "over" if total > line else "under"
                leg_ok = (actual == outcome)
            elif market == "Cards":
                total = data.get('home_bookings', 0) + data.get('away_bookings', 0)
                actual = "over" if total > line else "under"
                leg_ok = (actual == outcome)
            elif market == "CorrectScore":
                actual = f"{data.get('home_score', 0)}-{data.get('away_score', 0)}"
                leg_ok = (actual == outcome)
            elif market.startswith("AsianHandicap"):
                h, a = data.get('home_score', 0), data.get('away_score', 0)
                res = AsianHandicap.settle(line, h, a)
                if res == "push":
                    continue
                elif res in ("home", "away"):
                    leg_ok = (res == outcome.split('_')[1])
                else:
                    mult *= 0.5
                    leg_ok = True
            else:
                leg_ok = False
            if not leg_ok:
                return {"status": "lost"}
            active_legs.append(leg)
        if not active_legs:
            return {"status": "push"}
        combined_odds = np.prod([l['odds'] for l in active_legs])
        return {"status": "won", "multiplier": mult, "combined_odds": combined_odds}

# ======================================================================
# MEMORY (context, calibration, patterns)
# ======================================================================
class Memory:
    def __init__(self, db_pool):
        self.db = db_pool
        self.forgetting_rate = 0.99
        self.decay = 0.99

    async def record_context(self, dept, market, ctx, correct):
        await self.db.execute(
            """INSERT INTO context_memory (department, market, ctx_hash, successes, failures, total, blacklist_until, last_seen)
               VALUES (?, ?, ?, ?, ?, 1, 0, ?)
               ON CONFLICT(department, market, ctx_hash) DO UPDATE SET
               successes = successes * ? + ?,
               failures = failures * ? + ?,
               total = total * ? + 1,
               last_seen = ?""",
            (dept, market, ctx, 1 if correct else 0, 0 if correct else 1, time.time(),
             self.forgetting_rate, 1 if correct else 0,
             self.forgetting_rate, 0 if correct else 1,
             self.forgetting_rate, time.time())
        )

    async def get_context(self, dept, market, ctx):
        row = await self.db.fetchone(
            "SELECT successes, failures, total, blacklist_until FROM context_memory WHERE department=? AND market=? AND ctx_hash=?",
            (dept, market, ctx)
        )
        if not row or row['total'] < 15:
            return ("yellow", 1.0)
        if row['blacklist_until'] > time.time():
            return ("red", 0.4)
        cr = row['successes'] / row['total'] if row['total'] else 0.5
        if cr >= 0.58:
            return ("green", 1.03)
        elif cr >= 0.51:
            return ("yellow", 1.0)
        else:
            if cr < 0.3 and row['total'] > 50:
                await self.db.execute(
                    "UPDATE context_memory SET blacklist_until = ? WHERE department=? AND market=? AND ctx_hash=?",
                    (time.time() + CONFIG.kyc_lock_hours*3600, dept, market, ctx)
                )
            return ("red", max(0.6, cr / 0.5))

    async def record_calibration(self, dept, market, outcome, conf, correct):
        bin_idx = min(9, int(conf * 10))
        await self.db.execute(
            """INSERT INTO calibration_memory (department, market, outcome, conf_bin, total, correct, empirical)
               VALUES (?, ?, ?, ?, 1, ?, ?)
               ON CONFLICT(department, market, outcome, conf_bin) DO UPDATE SET
               total = total + 1,
               correct = correct + ?,
               empirical = CAST(correct AS REAL) / total""",
            (dept, market, outcome, bin_idx, 1 if correct else 0, conf,
             1 if correct else 0)
        )

    async def get_calibration(self, dept, market, outcome, conf):
        bin_idx = min(9, int(conf * 10))
        row = await self.db.fetchone(
            "SELECT empirical, total FROM calibration_memory WHERE department=? AND market=? AND outcome=? AND conf_bin=?",
            (dept, market, outcome, bin_idx)
        )
        if row:
            return row['empirical'], row['total']
        return 0.5, 0

    async def record_rejection(self, dept, market, feats, loss):
        fhash = hashlib.md5(str([k for k in feats.keys()][:20] + [market]).encode()).hexdigest()
        await self.db.execute(
            """INSERT INTO rejection_memory (department, market, feature_hash, loss_count, total, loss_rate, last_seen)
               VALUES (?, ?, ?, 0, 0, 0.0, ?)
               ON CONFLICT(department, market, feature_hash) DO UPDATE SET
               loss_count = loss_count * ? + ?,
               total = total * ? + 1,
               loss_rate = CAST(loss_count AS REAL) / total,
               last_seen = ?""",
            (dept, market, fhash, time.time(),
             self.decay, 1 if loss else 0,
             self.decay, time.time())
        )

    async def get_rejection(self, dept, market, feats):
        fhash = hashlib.md5(str([k for k in feats.keys()][:20] + [market]).encode()).hexdigest()
        row = await self.db.fetchone(
            "SELECT loss_rate, total FROM rejection_memory WHERE department=? AND market=? AND feature_hash=?",
            (dept, market, fhash)
        )
        return (row['loss_rate'], row['total']) if row and row['total'] > 0 else (0.5, 0)

    async def record_pattern(self, dept, market, pattern, match, correct):
        league = match.get("competition", "unknown")
        weather = match.get("weather_condition", "unknown")
        await self.db.execute(
            """INSERT INTO pattern_memory (department, market, pattern, league, weather, total, correct, last_seen)
               VALUES (?, ?, ?, ?, ?, 1, ?, ?)
               ON CONFLICT(department, market, pattern, league, weather) DO UPDATE SET
               total = total + 1,
               correct = correct + ?,
               last_seen = ?""",
            (dept, market, pattern, league, weather, 1 if correct else 0, time.time(),
             1 if correct else 0, time.time())
        )

    async def get_pattern(self, dept, market, pattern, match):
        league = match.get("competition", "unknown")
        weather = match.get("weather_condition", "unknown")
        row = await self.db.fetchone(
            "SELECT correct, total FROM pattern_memory WHERE department=? AND market=? AND pattern=? AND league=? AND weather=?",
            (dept, market, pattern, league, weather)
        )
        return (row['correct'] / row['total'], row['total']) if row and row['total'] > 0 else (0.5, 0)

    async def record_bankroll(self, val, dd, roi=0.0):
        ts = int(time.time() * 1e6) + random.randint(0, 1000)
        await self.db.execute(
            "INSERT OR IGNORE INTO bankroll_history (timestamp, bankroll, drawdown, daily_roi) VALUES (?, ?, ?, ?)",
            (ts, val, dd, roi)
        )

    async def record_shadow_bet(self, bid, market, outcome, odds, stake, stake_multiplier, actual, settled, fid):
        await self.db.execute(
            "INSERT OR REPLACE INTO shadow_history (bet_id, timestamp, market, outcome, odds, stake, stake_multiplier, actual_outcome, won, settled, fixture_id) VALUES (?,?,?,?,?,?,?,?,?,?,?)",
            (bid, time.time(), market, outcome, odds, stake, stake_multiplier, actual, 0, settled, fid)
        )

    async def settle_shadow_bet(self, bid, actual, multiplier=1.0):
        await self.db.execute(
            "UPDATE shadow_history SET actual_outcome=?, won=(CASE WHEN outcome=? THEN 1 ELSE 0 END), settled=1, stake_multiplier=? WHERE bet_id=?",
            (actual, actual, multiplier, bid)
        )

    async def get_shadow_stats(self, days=14):
        cutoff = time.time() - days * 86400
        row = await self.db.fetchone(
            "SELECT COUNT(*), SUM(won), SUM(stake * stake_multiplier), SUM(CASE WHEN won=1 THEN stake*stake_multiplier*(odds-1) ELSE -stake*stake_multiplier END) FROM shadow_history WHERE timestamp > ? AND settled=1",
            (cutoff,)
        )
        if not row or row[0] == 0:
            return {"bets": 0, "wins": 0, "stake": 0, "profit": 0, "roi": 0}
        bets, wins, stake, profit = row
        stake = float(stake or 0.0)
        profit = float(profit or 0.0)
        return {
            "bets": bets,
            "wins": wins,
            "stake": stake,
            "profit": profit,
            "roi": profit / stake if stake else 0
        }

    async def prune_memory(self, days=90):
        cutoff = time.time() - days * 86400
        for table in ["context_memory", "calibration_memory", "rejection_memory", "pattern_memory"]:
            try:
                await self.db.execute(f"DELETE FROM {table} WHERE last_seen < ?", (cutoff,))
            except Exception:
                pass

# ======================================================================
# EDGE ENHANCER (with CLV, sharp moves, regime, calibration)
# ======================================================================
class EdgeEnhancer:
    """Adjusts raw model edges using CLV, sharp-money signals, regime state, and calibration."""
    def __init__(self, db_pool):
        self.db = db_pool
        self.clv_history = deque(maxlen=1000)
        self.odds_history = defaultdict(lambda: deque(maxlen=20))
        self.regime_switcher = RegimeSwitcher()
        self.calibrator = None
        self.scaler = StandardScaler()
        self.calibrator_fitted = False
        self.credibility = 0.55
        self.credibility_update_interval = 20
        self.credibility_counter = 0
        self.bias_detector = BiasDetector(db_pool)

    @staticmethod
    def _closing_odds_from_row(match_row: Dict[str, Any], market: str, outcome: str) -> Optional[float]:
        if not isinstance(match_row, dict):
            return None
        market = str(market or "")
        outcome = str(outcome or "")
        candidates = [
            f"closing_{market.lower()}_{outcome.lower()}",
            f"closing_{outcome.lower()}",
            f"odds_{market.lower()}_{outcome.lower()}",
            f"odds_{outcome.lower()}",
        ]
        if market == "OverUnder":
            side = "over" if outcome.lower().startswith("over") else "under"
            candidates = [f"closing_{side}", f"odds_{side}"] + candidates
        elif market == "BTTS":
            side = "yes" if outcome.lower().startswith("yes") else "no"
            candidates = [f"closing_btts_{side}", f"odds_btts_{side}"] + candidates
        for key in candidates:
            value = match_row.get(key)
            if isinstance(value, (int, float)) and float(value) > 1.0:
                return float(value)
        return None

    async def compute_clv(self, fixture_id, bet_odds, market, outcome, closing_odds: Optional[float] = None):
        if isinstance(closing_odds, (int, float)) and float(closing_odds) > 1.0 and float(bet_odds) > 0:
            clv = (float(closing_odds) - float(bet_odds)) / float(bet_odds)
            self.clv_history.append(clv)
            return float(clv)
        row = await self.db.fetchone(
            "SELECT closing_home, closing_draw, closing_away FROM matches WHERE fixture_id=?",
            (fixture_id,)
        )
        if not row:
            return 0.0
        closing = {"home": row['closing_home'], "draw": row['closing_draw'], "away": row['closing_away']}
        if market == "1X2" and outcome in closing:
            closing_odds = closing[outcome]
            if bet_odds > 0:
                clv = (closing_odds - bet_odds) / bet_odds
                self.clv_history.append(clv)
                return clv
        if isinstance(row, dict):
            market_key = str(market or "").lower()
            outcome_key = str(outcome or "").lower()
            for key in (f"closing_{market_key}_{outcome_key}", f"odds_{market_key}_{outcome_key}", f"odds_{outcome_key}"):
                val = row.get(key)
                if isinstance(val, (int, float)) and float(val) > 1.0 and float(bet_odds) > 0:
                    clv = (float(val) - float(bet_odds)) / float(bet_odds)
                    self.clv_history.append(clv)
                    return float(clv)
        return 0.0

    def get_avg_clv(self, window=100):
        if len(self.clv_history) < window:
            return 0.0
        return np.mean(list(self.clv_history)[-window:])

    def adjust_edge_clv(self, edge, clv):
        if abs(clv) > CONFIG.clv_deadzone_pct:
            return edge * (1 + 2*clv)
        return edge

    def detect_sharp_move(self, fixture_id, market, current_odds, lookback_seconds=300):
        history = self.odds_history.get((fixture_id, market), [])
        if len(history) < 2:
            return 0.0
        now = time.time()
        old_odds = None
        for ts, odds in history:
            if now - ts <= lookback_seconds:
                old_odds = odds
                break
        if old_odds is None:
            return 0.0
        movement = (old_odds - current_odds) / old_odds
        if abs(movement) > CONFIG.sharp_move_threshold:
            return movement
        return 0.0

    def adjust_edge_sharp(self, edge, sharp_movement):
        if sharp_movement < -CONFIG.sharp_adjustment_threshold:
            return edge * 1.05
        elif sharp_movement > CONFIG.sharp_adjustment_threshold:
            return edge * 0.9
        return edge

    def adjust_edge_market_credibility(self, edge, odds, closing_odds):
        self.credibility_counter += 1
        if self.credibility_counter % self.credibility_update_interval == 0:
            avg_clv = self.get_avg_clv(50)
            if avg_clv > 0.02:
                self.credibility = min(0.8, self.credibility + 0.01)
            elif avg_clv < -0.02:
                self.credibility = max(0.3, self.credibility - 0.01)
        if closing_odds and closing_odds > 0:
            market_prob = 1.0 / closing_odds
            adjusted_prob = (1 - self.credibility) * (1.0 / odds + edge) + self.credibility * market_prob
            return adjusted_prob - 1.0 / odds
        return edge

    async def enhance_decision(self, decision, match_row, state):
        """Apply CLV, sharp-move, Poisson pricing, market-credibility, and regime adjustments.

        Mutates decision in place.  Recomputes closing_odds via the market-aware
        _closing_odds_from_row for all market types (not just 1X2).
        """
        fixture_id = decision.get('fixture_id')
        market = decision.get('market')
        outcome = decision.get('outcome')
        odds = decision.get('odds')
        edge = decision.get('edge', 0.05)
        stake = decision.get('stake', 0.0)

        history_key = (fixture_id, market)
        self.odds_history[history_key].append((time.time(), float(odds or 0.0)))

        closing_odds = self._closing_odds_from_row(match_row, market, outcome)
        clv = await self.compute_clv(fixture_id, odds, market, outcome, closing_odds=closing_odds)
        edge = self.adjust_edge_clv(edge, clv)

        sharp = self.detect_sharp_move(fixture_id, market, odds)
        edge = self.adjust_edge_sharp(edge, sharp)

        home_xg = match_row.get('home_xg', 1.2)
        away_xg = match_row.get('away_xg', 1.0)
        lam_h, lam_a = home_xg * CONFIG.non_1x2_xg_discount, away_xg * CONFIG.non_1x2_xg_discount
        odds_dict = {k: v for k, v in match_row.items() if k.startswith('odds_') or k.startswith('cs_') or k.startswith('ah_')}
        best_line, best_edge, best_stake = Calculator.poisson_kelly_optimum(
            lam_h, lam_a, odds_dict, state.get('bankroll', 1000), match_row=match_row
        )
        if best_edge > edge:
            edge = best_edge
            stake = best_stake

        edge = self.adjust_edge_market_credibility(edge, odds, closing_odds)

        if self.calibrator_fitted:
            probs = np.array([decision.get('prob', 0.5)]).reshape(1, -1)
            cal_probs = self.calibrate(probs)
            if cal_probs is not None:
                decision['prob'] = float(cal_probs[0][1]) if cal_probs.shape[1] > 1 else float(cal_probs[0][0])
                edge = decision['prob'] - 1.0 / odds

        vol = np.std(state.get('edge_history', [0])) if state.get('edge_history') else 0.1
        self.regime_switcher.update(edge, vol)
        edge = self.regime_switcher.adjust_edge_regime(edge)

        bookmaker_margin = match_row.get('bookmaker_margin', 0.05)
        edge = Calculator.adjust_edge_for_margin(edge, bookmaker_margin)

        if CONFIG.shin_method_enabled and market == "1X2":
            oh = match_row.get('odds_home', decision.get('odds', 2.0))
            od = match_row.get('odds_draw', 3.5)
            oa = match_row.get('odds_away', 4.0)
            try:
                shin_probs = ShinMethodExtractor.shin_prob(oh, od, oa)
                outcome_map = {"home": shin_probs.get("home", 0.0), "draw": shin_probs.get("draw", 0.0), "away": shin_probs.get("away", 0.0)}
                true_prob = outcome_map.get(outcome, 0.0)
                if true_prob > 0:
                    model_prob = decision.get('prob', 1.0 / odds)
                    blended_prob = 0.7 * model_prob + 0.3 * true_prob
                    edge = blended_prob - 1.0 / odds
            except Exception:
                pass

        bias_factor = self.bias_detector.correction_factor(market, outcome)
        edge *= bias_factor

        decision['edge'] = edge
        decision['stake'] = stake
        decision['clv'] = clv
        decision['edge_adjustments'] = (decision.get('edge_adjustments') or []) + ['clv', 'sharp', 'market_credibility', 'bias_correction']
        
        # Cap final edge to prevent compounding runaway
        edge_cap = float(getattr(CONFIG, 'max_single_edge', 0.25))
        decision['edge'] = max(-edge_cap, min(edge_cap * 2.0, decision['edge']))
        
        return decision

    def calibrate_probabilities(self, X, y):
        X = np.array(X).reshape(-1, 1) if X.ndim == 1 else X
        self.scaler.fit(X)
        self.calibrator = LogisticRegression()
        self.calibrator.fit(self.scaler.transform(X), y)
        self.calibrator_fitted = True

    def calibrate(self, X):
        if not self.calibrator_fitted or self.calibrator is None:
            return X
        X = np.array(X).reshape(-1, 1) if X.ndim == 1 else X
        return self.calibrator.predict_proba(self.scaler.transform(X))

class RegimeSwitcher:
    def __init__(self, window=30):
        self.window = max(5, int(window or 30))
        self.edge_history = deque(maxlen=self.window)
        self.vol_history = deque(maxlen=self.window)
        self.regime = "normal"

    def update(self, edge: float, vol: float) -> str:
        try:
            self.edge_history.append(float(edge or 0.0))
        except Exception:
            self.edge_history.append(0.0)
        try:
            self.vol_history.append(float(vol or 0.0))
        except Exception:
            self.vol_history.append(0.0)
        self.regime = self.infer_regime()
        return self.regime

    def infer_regime(self) -> str:
        if len(self.vol_history) < 5:
            return "normal"
        vols = np.array(self.vol_history)
        edges = np.abs(np.array(self.edge_history)) if self.edge_history else np.array([0.0])
        base_vol = float(np.mean(vols)) if len(vols) else 0.0
        recent_vol = float(np.mean(vols[-min(5, len(vols)):])) if len(vols) else 0.0
        recent_edge = float(np.mean(edges[-min(5, len(edges)):])) if len(edges) else 0.0
        if base_vol > 0 and recent_vol > 1.5 * base_vol and recent_edge > 0.03:
            return "high"
        if base_vol > 0 and recent_vol < 0.7 * base_vol and recent_edge < 0.01:
            return "low"
        return "normal"

    def adjust_edge_regime(self, edge: float) -> float:
        reg = self.regime
        if reg == "high":
            return edge * 1.1
        elif reg == "low":
            return edge * 0.8
        return edge

#region Risk Manager
# ======================================================================
# RISK MANAGER (with exposure release, daily reset)
# ======================================================================
class RiskManager:
    """Stake-sizing, drawdown enforcement, and bet-placement risk gating."""
    def __init__(self, state):
        self.state = state
        self._lock = asyncio.Lock()
        self._placed_bets = []
        self._last_reset = time.time()

    def calculate_kelly_fraction(self, calculated_edge: float, fixture_id: Optional[str] = None, market: Optional[str] = None) -> float:
        try:
            edge = float(calculated_edge)
        except Exception:
            return 0.0
        if not math.isfinite(edge):
            return 0.0
        base = max(0.0, min(CONFIG.kelly_fraction, edge * CONFIG.fractional_kelly_factor))
        if not CONFIG.enable_correlation_adjusted_kelly:
            return base

        corr_penalty = 0.0
        for placed in self._placed_bets[-100:]:
            if fixture_id and placed.get("fixture_id") == fixture_id:
                corr_penalty += 0.22
                if market and placed.get("market") == market:
                    corr_penalty += 0.18
        multiplier = max(0.35, 1.0 - corr_penalty)
        return float(base * multiplier)

    async def _commit_exposure(self, fixture_id, market, stake, league, team_home, team_away, bookmaker, outcome=None):
        async with self._lock:
            exp = self.state.get("exposure_per_league", {})
            exp[league] = exp.get(league, 0) + stake
            self.state.set("exposure_per_league", exp)
            mkt = self.state.get("exposure_per_market", {})
            mkt[market] = mkt.get(market, 0) + stake
            self.state.set("exposure_per_market", mkt)
            if team_home:
                tm = self.state.get("exposure_per_team", {})
                tm[team_home] = tm.get(team_home, 0) + stake
                self.state.set("exposure_per_team", tm)
            if team_away:
                tm = self.state.get("exposure_per_team", {})
                tm[team_away] = tm.get(team_away, 0) + stake
                self.state.set("exposure_per_team", tm)
            if outcome:
                ok = f"{market}_{outcome}"
                om = self.state.get("exposure_per_outcome", {})
                om[ok] = om.get(ok, 0) + stake
                self.state.set("exposure_per_outcome", om)
            bm = self.state.get("exposure_per_bookmaker", {})
            bm[bookmaker] = bm.get(bookmaker, 0) + stake
            self.state.set("exposure_per_bookmaker", bm)
            self._placed_bets.append({
                'fixture_id': fixture_id,
                'market': market,
                'outcome': outcome,
                'stake': stake,
                'bookmaker': bookmaker,
                'league': league,
            })
            self.state.set('daily_bets', self.state.get('daily_bets', 0) + 1)

    async def execute_secure_order_placement(self, orchestrator, match_id: str, market_id: str, calculated_edge: float,
                                             match_payload: Optional[Dict[str, Any]] = None, stake: Optional[float] = None):
        """Validate payload, check exposure via check_and_deduct_exposure, then place order.

        Returns True if the order was accepted or the exposure gate passed with no
        exchange client configured.  Returns False if the exposure check blocked
        the bet or the exchange rejected the order.
        """
        try:
            payload = match_payload or {}
            quality_score = validate_match_payload({
                "historical_odds": payload.get("odds_home") or payload.get("odds_draw") or payload.get("odds_away"),
                "market_volume": payload.get("market_volume") or payload.get("volume"),
                "recent_form_home": payload.get("form_home"),
                "recent_form_away": payload.get("form_away"),
                "h2h_matrix": payload.get("h2h_home_win_rate") or payload.get("h2h_avg_goals"),
                "expected_goals_raw": payload.get("home_xg") or payload.get("away_xg"),
                "research_confidence": payload.get("research_confidence", 0.0),
                "source_reliability": payload.get("source_reliability", 0.0),
                "source_coverage_count": payload.get("source_coverage_count", 0),
                "source_coverage_total": payload.get("source_coverage_total", 12),
            })
        except Exception:
            quality_score = 0.0

        if float(payload.get("feature_gate_blocked", 0.0) or 0.0) >= 0.5 or float(payload.get("feature_audit_pass", 0.0) or 0.0) < 0.78:
            return False

        raw_fraction = self._upgraded_kelly_fraction(calculated_edge, fixture_id=match_id, market=market_id)
        quality_multiplier = max(0.0, min(1.0, quality_score))
        adjusted_fraction = raw_fraction * quality_multiplier
        effective_stake = float(stake if stake is not None else adjusted_fraction)
        effective_stake *= quality_multiplier
        if CONFIG.enable_rl_staking:
            weights = self.state.get("rl_policy_weights", {})
            if isinstance(weights, dict):
                market_w = float(weights.get(str(market_id), 1.0) or 1.0)
                effective_stake *= max(0.6, min(1.4, market_w))
        if effective_stake <= 0:
            return False

        ok, reason = await self.check_and_deduct_exposure(
            match_id, market_id, effective_stake,
            league=payload.get("competition", "Unknown"),
            team_home=payload.get("home"),
            team_away=payload.get("away"),
            bookmaker=payload.get("bookmaker", "unknown"),
            outcome=payload.get("outcome"),
        )
        if not ok:
            log.warning(f"Secure order blocked by exposure check: {reason} for {match_id}/{market_id}")
            return False

        exchange_client = getattr(orchestrator, "exchange_client", None)
        if exchange_client is None:
            return True

        order_success = await exchange_client.place_order(match_id, effective_stake)
        if order_success:
            return True
        await self.release_exposure(match_id, market_id, effective_stake,
                                     payload.get("competition", "Unknown"), payload.get("home"),
                                     payload.get("away"), payload.get("bookmaker", "unknown"),
                                     payload.get("outcome"))
        return False

    async def check_and_deduct_exposure(self, fixture_id, market, stake, league="Unknown", team_home=None, team_away=None,
                                         bookmaker="unknown", outcome=None) -> Tuple[bool, str]:
        async with self._lock:
            if float(stake or 0.0) < float(CONFIG.min_stake_per_bet):
                return False, "below_min_stake"
            now = time.time()
            if now - self._last_reset > 86400:
                self.reset_daily_exposure()
                self._last_reset = now

            daily_bets = self.state.get('daily_bets', 0)
            if daily_bets >= CONFIG.max_bets_per_day:
                return False, "daily_bet_limit"

            locks = self.state.get("bookmaker_locks", {})
            if bookmaker in locks and locks[bookmaker] > time.time():
                return False, "bookmaker_locked"

            for bet in self._placed_bets:
                if bet['fixture_id'] == fixture_id:
                    if bet['market'] == market and bet['outcome'] != outcome:
                        return False, "correlation_conflict"

            league_exp = self.state.get("exposure_per_league", {}).get(league, 0)
            if league_exp + stake > CONFIG.exposure_limit_per_league * self.state.get("bankroll", 1000):
                return False, "league_limit"

            market_exp = self.state.get("exposure_per_market", {}).get(market, 0)
            if market_exp + stake > CONFIG.exposure_limit_per_market * self.state.get("bankroll", 1000):
                return False, "market_limit"

            if team_home:
                team_exp = self.state.get("exposure_per_team", {}).get(team_home, 0)
                if team_exp + stake > CONFIG.exposure_limit_per_team * self.state.get("bankroll", 1000):
                    return False, "team_limit"
            if team_away:
                team_exp = self.state.get("exposure_per_team", {}).get(team_away, 0)
                if team_exp + stake > CONFIG.exposure_limit_per_team * self.state.get("bankroll", 1000):
                    return False, "team_limit"

            if outcome:
                outcome_key = f"{market}_{outcome}"
                outcome_exp = self.state.get("exposure_per_outcome", {}).get(outcome_key, 0)
                if outcome_exp + stake > CONFIG.exposure_limit_per_outcome * self.state.get("bankroll", 1000):
                    return False, "outcome_limit"

            bm_exp = self.state.get("exposure_per_bookmaker", {}).get(bookmaker, 0)
            if bm_exp + stake > CONFIG.exposure_limit_per_bookmaker * self.state.get("bankroll", 0):
                return False, "bookmaker_limit"

            await self._commit_exposure(fixture_id, market, stake, league, team_home, team_away, bookmaker, outcome)
            return True, "ok"

    async def release_exposure(self, fixture_id, market, stake, league, team_home, team_away, bookmaker, outcome=None):
        async with self._lock:
            exp = self.state.get("exposure_per_league", {})
            exp[league] = max(0, exp.get(league, 0) - stake)
            self.state.set("exposure_per_league", exp)

            mkt = self.state.get("exposure_per_market", {})
            mkt[market] = max(0, mkt.get(market, 0) - stake)
            self.state.set("exposure_per_market", mkt)

            if team_home:
                tm = self.state.get("exposure_per_team", {})
                tm[team_home] = max(0, tm.get(team_home, 0) - stake)
                self.state.set("exposure_per_team", tm)
            if team_away:
                tm = self.state.get("exposure_per_team", {})
                tm[team_away] = max(0, tm.get(team_away, 0) - stake)
                self.state.set("exposure_per_team", tm)

            if outcome:
                ok = f"{market}_{outcome}"
                om = self.state.get("exposure_per_outcome", {})
                om[ok] = max(0, om.get(ok, 0) - stake)
                self.state.set("exposure_per_outcome", om)

            bm = self.state.get("exposure_per_bookmaker", {})
            bm[bookmaker] = max(0, bm.get(bookmaker, 0) - stake)
            self.state.set("exposure_per_bookmaker", bm)

            self._placed_bets = [b for b in self._placed_bets if not (b['fixture_id']==fixture_id and b['market']==market and b['outcome']==outcome and b['bookmaker']==bookmaker)]

    def reset_daily_exposure(self):
        self.state.set("exposure_per_league", {})
        self.state.set("exposure_per_market", {})
        self.state.set("exposure_per_team", {})
        self.state.set("exposure_per_bookmaker", {})
        self.state.set("exposure_per_outcome", {})
        self._placed_bets = []
        self.state.set('daily_bets', 0)
        self.state.set('daily_loss', 0.0)

    def apply_seed_rules(self, fixture_id, market, stake, league, team_home, team_away, bookmaker, state):
        seed_rules = state.get("seed_risk_rules", [])
        current_stake = stake
        for rule_name in seed_rules:
            if rule_name in SAFE_RISK_LIBRARY:
                try:
                    new_stake, _ = SAFE_RISK_LIBRARY[rule_name](
                        fixture_id, market, current_stake, league, team_home, team_away, bookmaker, state
                    )
                    current_stake = new_stake
                except Exception as e:
                    log.warning(f"Risk rule {rule_name} failed: {e}")
        return current_stake

    def _upgrade_init(self):
        if getattr(self, "_upgrades_loaded", False):
            return
        self._upgrades_loaded = True
        self._cov_kelly = CovarianceKelly() if CONFIG.enable_covariance_kelly else None
        self._dd_kelly = DrawdownAwareKelly(max_drawdown=CONFIG.max_drawdown) if CONFIG.enable_dd_kelly else None
        self._tail_hedge = TailHedge() if CONFIG.enable_tail_hedge else None
        log.info("RiskManager upgrades initialized.")

    def _upgraded_kelly_fraction(self, calculated_edge: float, fixture_id: Optional[str] = None, market: Optional[str] = None) -> float:
        self._upgrade_init()
        base = self.calculate_kelly_fraction(calculated_edge, fixture_id=fixture_id, market=market)
        if base <= 0:
            return 0.0
        if self._dd_kelly is not None:
            try:
                current_dd = self.state.get("drawdown", 0.0)
                base = self._dd_kelly.scale(base, float(current_dd))
            except Exception:
                pass
        return float(np.clip(base, 0.0, CONFIG.max_stake_per_bet))

    def _upgraded_slippage(self, base_slippage: float, volatility: float, spread: float, order_depth: float) -> float:
        self._upgrade_init()
        if not CONFIG.enable_slippage_predictor:
            return base_slippage
        if not hasattr(self, '_slippage_predictor'):
            self._slippage_predictor = SlippagePredictor()
        try:
            return self._slippage_predictor.predict(volatility, spread, order_depth)
        except Exception:
            return base_slippage


# ======================================================================
# DRIFT DETECTOR
# ======================================================================
# DRIFT DETECTOR
# ======================================================================
class DriftDetector:
    def __init__(self, window=50):
        self.window = window
        self.history = {
            "edge": deque(maxlen=window),
            "log_loss": deque(maxlen=window),
            "roi": deque(maxlen=window),
            "calibration": deque(maxlen=window)
        }
        self._lock = asyncio.Lock()

    async def update(self, metric_name, value):
        async with self._lock:
            if metric_name in self.history:
                self.history[metric_name].append(value)

    async def detect(self, metric_name, threshold=1.2):
        async with self._lock:
            if len(self.history[metric_name]) < self.window:
                return False, 0.0
            recent = np.mean(list(self.history[metric_name])[-10:])
            overall = np.mean(list(self.history[metric_name]))
            recent_data = list(self.history[metric_name])[-10:]
            overall_data = list(self.history[metric_name])[:-10]
            if overall_data and len(recent_data) > 5:
                ks_stat, p_value = kstest(recent_data, overall_data)
                if p_value < 0.05:
                    return True, recent / overall
            return recent > overall * threshold, recent / overall

# ======================================================================
# SYSTEM MONITOR
# ======================================================================
class SystemMonitor:
    def __init__(self):
        self.cpu_history = deque(maxlen=100)
        self.mem_history = deque(maxlen=100)
        self.disk_history = deque(maxlen=100)
        self.network_history = deque(maxlen=100)
        self.fd_history = deque(maxlen=100)
        self._last_alert = {}
        self._lock = asyncio.Lock()

    def update(self):
        if psutil:
            self.cpu_history.append(psutil.cpu_percent())
            mem = psutil.virtual_memory()
            self.mem_history.append(mem.percent)
            disk = psutil.disk_usage('/')
            self.disk_history.append(disk.percent)
            net = psutil.net_io_counters()
            self.network_history.append(net.bytes_sent + net.bytes_recv)
            self.fd_history.append(len(psutil.Process().open_files()))

    def get_health(self):
        if psutil and self.cpu_history:
            return {
                "cpu": np.mean(self.cpu_history),
                "memory": np.mean(self.mem_history),
                "disk": np.mean(self.disk_history) if self.disk_history else 0,
                "network": np.mean(self.network_history) if self.network_history else 0,
                "fd": np.mean(self.fd_history) if self.fd_history else 0
            }
        return {"cpu": 0, "memory": 0, "disk": 0, "network": 0, "fd": 0}

    async def alert_if_high(self):
        health = self.get_health()
        now = time.time()
        async with self._lock:
            if health["cpu"] > 80 and now - self._last_alert.get("cpu", 0) > 3600:
                send_alert(f"CPU usage high: {health['cpu']:.1f}%", "warning")
                self._last_alert["cpu"] = now
            if health["memory"] > 80 and now - self._last_alert.get("memory", 0) > 3600:
                send_alert(f"Memory usage high: {health['memory']:.1f}%", "warning")
                self._last_alert["memory"] = now
            if health["disk"] > 85 and now - self._last_alert.get("disk", 0) > 3600:
                send_alert(f"Disk usage high: {health['disk']:.1f}%", "warning")
                self._last_alert["disk"] = now
            if health["fd"] > 500 and now - self._last_alert.get("fd", 0) > 3600:
                send_alert(f"High open file descriptors: {health['fd']:.0f}", "warning")
                self._last_alert["fd"] = now

# ======================================================================
# META-ENSEMBLE BLENDER (stacking + calibration)
# ======================================================================
class MetaEnsembleBlender:
    def __init__(self):
        self.meta_learner = Ridge(alpha=1.0, positive=True)
        self.calibration_layer = IsotonicRegression(out_of_bounds="clip")
        self.is_trained = False
        self.training_summary = {}

    def train_meta_layer(self, level0_predictions: NDArray, real_outcomes: NDArray):
        X = np.asarray(level0_predictions, dtype=float)
        y = np.asarray(real_outcomes, dtype=float)
        if X.ndim == 1:
            X = X.reshape(-1, 1)
        if X.shape[0] != y.shape[0]:
            raise ValueError("Prediction matrix and outcomes must have matching rows.")
        self.meta_learner.fit(X, y)
        blended_preds = self.meta_learner.predict(X)
        self.calibration_layer.fit(blended_preds, y)
        self.is_trained = True
        self.training_summary = {
            "train_rows": int(len(y)),
            "feature_count": int(X.shape[1]),
            "mean_outcome": float(np.mean(y)),
            "mean_blend": float(np.mean(blended_preds)),
        }

    def predict_calibrated_probability(self, level0_inputs: NDArray) -> NDArray:
        if not self.is_trained:
            raise RuntimeError("MetaEnsembleBlender layer must be trained first.")
        arr = np.asarray(level0_inputs, dtype=float)
        if arr.ndim == 1:
            arr = arr.reshape(1, -1)
        raw_blend = self.meta_learner.predict(arr)
        return self.calibration_layer.predict(raw_blend)

    def blend_from_context(self, context_predictions: List[float]) -> float:
        if not self.is_trained:
            return float(np.clip(np.mean(context_predictions), 0.02, 0.98))
        arr = np.asarray(context_predictions, dtype=float).reshape(1, -1)
        return float(np.clip(self.predict_calibrated_probability(arr)[0], 0.02, 0.98))

# ======================================================================
# BANDIT ENSEMBLE
# ======================================================================
class BanditEnsemble:
    def __init__(self, db_pool, market):
        self.db = db_pool
        self.market = market
        self.weights = {}
        self._lock = asyncio.Lock()
        self._learning_rate = 0.05
        self._recent_rewards = defaultdict(lambda: deque(maxlen=50))
        self._decay = 0.99
        self._exploration = 0.1

    async def load_weights(self):
        rows = await self.db.fetchall(
            "SELECT model_name, weight FROM bandit_weights WHERE market=?",
            (self.market,)
        )
        for row in rows:
            self.weights[row['model_name']] = float(row['weight'])
        total = sum(self.weights.values()) or 1
        self.weights = {k: v/total for k, v in self.weights.items()}

    async def update_weight(self, model_name, reward):
        async with self._lock:
            if model_name not in self.weights:
                self.weights[model_name] = 1.0
            self._recent_rewards[model_name].append(reward)
            if len(self._recent_rewards[model_name]) >= 10:
                reward_std = np.std(list(self._recent_rewards[model_name]))
                lr = 0.05 / (1 + reward_std)
            else:
                lr = self._learning_rate
            for name in list(self.weights.keys()):
                self.weights[name] *= self._decay
            new_w = self.weights.get(model_name, 1.0) * (1 + reward * lr)
            self.weights[model_name] = max(0.1, min(5.0, new_w))
            exp_w = np.exp([v for v in self.weights.values()])
            total = sum(exp_w)
            normalized = {name: exp_w[i]/total for i, name in enumerate(self.weights.keys())}
            self.weights = normalized
            await self.db.execute(
                "INSERT OR REPLACE INTO bandit_weights (market, model_name, weight, last_updated) VALUES (?, ?, ?, ?)",
                (self.market, model_name, self.weights[model_name], time.time())
            )

    def get_weighted_prediction(self, predictions):
        if random.random() < self._exploration:
            model_name = random.choice(list(predictions.keys()))
            return np.array(predictions[model_name])
        total_w = sum(self.weights.get(name, 1.0) for name in predictions.keys())
        if total_w == 0:
            return np.zeros_like(next(iter(predictions.values())))
        weighted = np.zeros_like(next(iter(predictions.values())))
        for name, pred in predictions.items():
            w = self.weights.get(name, 1.0)
            weighted += (w / total_w) * np.array(pred)
        return weighted

# ======================================================================
# GENETIC FEATURE EVOLUTION
# ======================================================================
class GeneticFeatureEvolution:
    def __init__(self, db_pool, state):
        self.db = db_pool
        self.state = state

    async def evolve(self, data, iterations=10):
        if not CONFIG.enable_genetic_features or data.empty or len(data) < 100:
            return
        features = [f for f in FeatureEngine.feature_order() if not f.startswith('gen_')]
        base_X = np.array([
            [FeatureEngine._cleanse((await FeatureEngine.build_features(row, self.state))[f]) for f in features]
            for _, row in data.iterrows()
        ])
        y = ((data["home_goals"] > data["away_goals"]).astype(int)).values
        split = int(0.8 * len(base_X))
        X_train, X_val = base_X[:split], base_X[split:]
        y_train, y_val = y[:split], y[split:]
        best_fitness = -1e9
        for _ in range(iterations):
            expr = f"np.log({random.choice(features)} + 0.01) * {random.uniform(0.5, 2.0)}"
            try:
                SafeExpressionEvaluator.evaluate(expr, {f: 1.0 for f in features})
                new_feat = []
                for _, row in data.iterrows():
                    feats = await FeatureEngine.build_features(row, self.state)
                    val = SafeExpressionEvaluator.evaluate(expr, feats)
                    new_feat.append(FeatureEngine._cleanse(val))
                if len(new_feat) < len(X_train):
                    continue
                X_train_new = np.column_stack([X_train, np.array(new_feat[:len(X_train)])])
                X_val_new = np.column_stack([X_val, np.array(new_feat[len(X_train):])])
                if xgb is None:
                    continue
                model = xgb.XGBClassifier(n_estimators=50, max_depth=3)
                model.fit(X_train_new, y_train)
                preds = model.predict_proba(X_val_new)
                score = -log_loss(y_val, preds)
                if score > best_fitness:
                    best_fitness = score
                    self.state.set("genetic_features",
                        self.state.get("genetic_features", []) + [
                            {"name": f"gen_{int(time.time())}", "expression": expr, "fitness": score}
                        ])
                    await self.state.flush()
                    log.info(f"Genetic feature added with fitness {score:.4f}: {expr}")
            except Exception as e:
                pass

# ======================================================================
# CORRELATION RISK
# ======================================================================
class CorrelationRisk:
    @staticmethod
    def compute_var(pending_bets, bankroll, confidence=0.95, n_sims=10000):
        if not pending_bets:
            return 0.0, 0.0
        losses = []
        for _ in range(n_sims):
            total_loss = 0.0
            for bet in pending_bets:
                odds = bet.get('odds', 2.0)
                stake = bet.get('stake', 0)
                edge = max(0.0, min(1.0, bet.get('edge', 0.05) + 0.01))
                win_prob = min(0.95, 1.0 / odds + edge)
                if random.random() < win_prob:
                    total_loss += -stake * (odds - 1)
                else:
                    total_loss += stake
            losses.append(total_loss)
        if not losses:
            return 0.0, 0.0
        var = np.percentile(losses, confidence * 100)
        cvar = np.mean([l for l in losses if l <= var])
        return abs(var) / bankroll, abs(cvar) / bankroll

