# ARBITRAGE EXECUTOR
# ======================================================================
class ArbitrageExecutor:
    @staticmethod
    async def find_and_execute(odds_data, bankroll, db, jitter_scheduler=None):
        if not CONFIG.enable_arbitrage:
            return
        for event in odds_data:
            bookmakers = event.get("bookmakers", [])
            best = {}
            for bm in bookmakers:
                for market in bm.get("markets", []):
                    market_type = market.get("key")
                    for outcome in market.get("outcomes", []):
                        name = outcome.get("name")
                        price = outcome.get("price", 0)
                        key = f"{market_type}_{name}"
                        if name and price > best.get(key, {}).get("price", 0):
                            best[key] = {"price": price, "bookmaker": bm.get("key"), "market": market_type}

            for market_type in ["h2h", "totals", "btts"]:
                items = {k: v for k, v in best.items() if v.get("market") == market_type}
                if len(items) >= 2:
                    implied = sum(1.0 / v["price"] for v in items.values() if v["price"] > 0)
                    if implied < 0.995:
                        log.info(f"Arbitrage found: implied {implied:.4f}")
                        home = event.get("home_team") or event.get("homeTeam") or event.get("home", {}).get("name", "Home")
                        away = event.get("away_team") or event.get("awayTeam") or event.get("away", {}).get("name", "Away")
                        leg_details = "\n".join(
                            f"  - {k.split(':', 1)[-1]} @ {data['price']:.2f} on {data['bookmaker']}"
                            for k, data in items.items()
                        )
                        profit_pct = (1.0 - implied) * 100
                        alert_msg = (
                            f"ARBITRAGE OPPORTUNITY\n"
                            f"Match: {home} vs {away}\n"
                            f"Market: {market_type}\n"
                            f"Profit: {profit_pct:.2f}%\n"
                            f"Legs:\n{leg_details}"
                        )
                        send_alert(alert_msg, level="warning", dedup_seconds=300, retry=3, priority=True)
                        if CONFIG.enable_health_server:
                            try:
                                _METRICS["arb_alerts"] += 1
                            except Exception:
                                pass
                        if CONFIG.exchange_type and CONFIG.exchange_key:
                            await EXCHANGE.login()
                            for key, data in items.items():
                                stake = bankroll * 0.01
                                await EXCHANGE.place_order(
                                    market_id=event.get("id"),
                                    selection_id=key,
                                    side="BACK",
                                    odds=data["price"],
                                    stake=stake
                                )

    @staticmethod
    def compute_arbitrage_stakes(back_odds, lay_odds, liability):
        try:
            b = float(back_odds)
            l = float(lay_odds)
            liab = float(liability)
        except Exception:
            return 0.0, 0.0
        if not (math.isfinite(b) and math.isfinite(l) and math.isfinite(liab)):
            return 0.0, 0.0
        if b <= 1.0 or l <= 1.0 or liab <= 0.0:
            return 0.0, 0.0
        stake_back = liab / (b - 1.0)
        stake_lay = liab
        return stake_back, stake_lay

    def _upgrade_init(self):
        if getattr(self, "_upgrades_loaded", False):
            return
        self._upgrades_loaded = True
        self._liquidity_executor = LiquidityAwareExecutor() if CONFIG.enable_liquidity_routing else None
        self._slippage_predictor = SlippagePredictor() if CONFIG.enable_slippage_predictor else None
        self._atomic_bet = AtomicBetUnit() if CONFIG.enable_atomic_bet_unit else None
        log.info("ExecutionEnhancer upgrades initialized.")

    def upgraded_stake(self, raw_stake: float, available_liquidity: float, odds: float, volatility: float = 0.1, spread: float = 0.01) -> float:
        self._upgrade_init()
        stake = self.mask_stake(raw_stake)
        if stake <= 0:
            return 0.0
        if self._liquidity_executor is not None:
            try:
                if self._liquidity_executor.should_split(stake, available_liquidity):
                    chunks = self._liquidity_executor.compute_chunks(stake, available_liquidity)
                    stake = sum(chunks) if chunks else stake
            except Exception:
                pass
        if self._slippage_predictor is not None:
            try:
                slippage = self._slippage_predictor.predict(volatility, spread, available_liquidity)
                stake = stake * (1.0 - slippage)
            except Exception:
                pass
        return self.mask_stake(stake)


class SteamChaser:
    def __init__(self, db_pool=None):
        self.db = db_pool
        self._line_history: Dict[str, deque] = defaultdict(lambda: deque(maxlen=200))
        self._lock = asyncio.Lock()

    async def record_tick(self, fixture_id: str, market: str, outcome: str, odds: float, bookmaker: str = "unknown"):
        key = f"{fixture_id}:{market}:{outcome}"
        async with self._lock:
            self._line_history[key].append((time.time(), float(odds), bookmaker))
            if self.db:
                try:
                    await self.db.execute(
                        "INSERT INTO tick_data (fixture_id, market, outcome, bookmaker, odds, volume, timestamp) VALUES (?, ?, ?, ?, ?, ?, ?)",
                        (fixture_id, market, outcome, bookmaker, float(odds), 0.0, time.time())
                    )
                except Exception:
                    pass

    def detect_steam_move(self, fixture_id: str, market: str, outcome: str, current_odds: float, lookback_seconds: int = 300) -> Dict[str, Any]:
        key = f"{fixture_id}:{market}:{outcome}"
        history = self._line_history.get(key, [])
        if len(history) < 2:
            return {"move": 0.0, "velocity": 0.0, "is_steam": False, "is_freeze": False}
        now = time.time()
        old_ts, old_odds, old_bm = history[0]
        recent_ts, recent_odds, recent_bm = history[-1]
        if now - old_ts > lookback_seconds:
            return {"move": 0.0, "velocity": 0.0, "is_steam": False, "is_freeze": False}
        move = (old_odds - current_odds) / old_odds if old_odds > 0 else 0.0
        dt = max(1e-6, recent_ts - old_ts)
        velocity = move / dt
        is_steam = move < -CONFIG.steam_chase_min_move and velocity < -CONFIG.steam_chase_min_move / 10.0
        is_freeze = abs(move) < 0.005 and (now - recent_ts) > CONFIG.line_freeze_threshold_seconds
        return {"move": move, "velocity": velocity, "is_steam": is_steam, "is_freeze": is_freeze, "old_odds": old_odds, "old_bm": old_bm}

    async def record_steam_move(self, fixture_id: str, market: str, outcome: str, old_odds: float, new_odds: float, velocity: float, source: str = "auto"):
        if self.db:
            try:
                await self.db.execute(
                    "INSERT INTO steam_moves (fixture_id, market, outcome, old_odds, new_odds, velocity, timestamp, source) VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
                    (fixture_id, market, outcome, float(old_odds), float(new_odds), float(velocity), time.time(), source)
                )
            except Exception:
                pass


class DynamicCLVTracker:
    def __init__(self, db_pool=None):
        self.db = db_pool
        self._tick_buffers: Dict[str, deque] = defaultdict(lambda: deque(maxlen=500))
        self._lock = asyncio.Lock()

    async def record_tick(self, fixture_id: str, market: str, outcome: str, odds: float, bookmaker: str, volume: float = 0.0):
        key = f"{fixture_id}:{market}:{outcome}:{bookmaker}"
        async with self._lock:
            self._tick_buffers[key].append((time.time(), float(odds), float(volume)))
            if self.db:
                try:
                    await self.db.execute(
                        "INSERT INTO tick_data (fixture_id, market, outcome, bookmaker, odds, volume, timestamp) VALUES (?, ?, ?, ?, ?, ?, ?)",
                        (fixture_id, market, outcome, bookmaker, float(odds), float(volume), time.time())
                    )
                except Exception:
                    pass

    def compute_vwap(self, fixture_id: str, market: str, outcome: str, bookmaker: str, window_seconds: int = 300) -> float:
        key = f"{fixture_id}:{market}:{outcome}:{bookmaker}"
        buf = self._tick_buffers.get(key, [])
        now = time.time()
        ticks = [(ts, o, v) for ts, o, v in buf if now - ts <= window_seconds and o > 1.0]
        if not ticks:
            return 0.0
        total_vol = sum(v for _, _, v in ticks)
        if total_vol <= 0:
            return sum(o for _, o, _ in ticks) / len(ticks)
        return sum(o * v for _, o, v in ticks) / total_vol

    def get_tick_count(self, fixture_id: str, market: str, outcome: str, bookmaker: str) -> int:
        key = f"{fixture_id}:{market}:{outcome}:{bookmaker}"
        return len(self._tick_buffers.get(key, []))


class LatencyArbDetector:
    def __init__(self, db_pool=None):
        self.db = db_pool
        self._pinnacle_ts: Dict[str, float] = {}
        self._soft_ts: Dict[str, float] = {}

    def record_pinnacle_update(self, fixture_id: str, market: str, outcome: str):
        key = f"{fixture_id}:{market}:{outcome}"
        self._pinnacle_ts[key] = time.time()

    def record_soft_update(self, fixture_id: str, market: str, outcome: str, bookmaker: str):
        key = f"{fixture_id}:{market}:{outcome}:{bookmaker}"
        self._soft_ts[key] = time.time()

    def detect_latency_arb(self, fixture_id: str, market: str, outcome: str, pinnacle_odds: float, soft_odds: float, soft_bookmaker: str) -> Optional[Dict[str, Any]]:
        key = f"{fixture_id}:{market}:{outcome}"
        soft_key = f"{fixture_id}:{market}:{outcome}:{soft_bookmaker}"
        p_ts = self._pinnacle_ts.get(key, 0.0)
        s_ts = self._soft_ts.get(soft_key, 0.0)
        latency = s_ts - p_ts if s_ts > 0 and p_ts > 0 else 0.0
        if latency < 0 or latency > CONFIG.latency_arb_max_staleness_seconds:
            return None
        if soft_odds <= 1.0 or pinnacle_odds <= 1.0:
            return None
        implied_soft = 1.0 / soft_odds
        implied_pinnacle = 1.0 / pinnacle_odds
        edge = implied_pinnacle - implied_soft
        if edge <= 0:
            return None
        return {
            "fixture_id": fixture_id,
            "market": market,
            "outcome": outcome,
            "soft_bookmaker": soft_bookmaker,
            "pinnacle_odds": pinnacle_odds,
            "soft_odds": soft_odds,
            "latency_seconds": latency,
            "edge": edge,
            "profit_pct": edge * 100,
        }

    async def log_latency_arb(self, fixture_id: str, market: str, pinnacle_ts: float, soft_ts: float, action: str):
        if self.db:
            try:
                await self.db.execute(
                    "INSERT INTO latency_arb_logs (log_id, fixture_id, market, pinnacle_ts, soft_ts, latency_seconds, action, timestamp) VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
                    (str(uuid.uuid4()), fixture_id, market, float(pinnacle_ts), float(soft_ts), float(soft_ts - pinnacle_ts), action, time.time())
                )
            except Exception:
                pass


class ExecutionEnhancer:
    @staticmethod
    def iceberg_stake(base_stake: float, max_chunk_pct: float = 0.15, min_chunk_pct: float = 0.02) -> List[float]:
        try:
            base = float(base_stake)
        except Exception:
            return []
        if base <= 0:
            return []
        max_chunk = max(min_chunk_pct, min(max_chunk_pct, 1.0))
        chunk_size = max(min_chunk_pct * base, max_chunk_pct * base)
        if chunk_size >= base:
            return [base]
        chunks = []
        remaining = base
        while remaining > 1e-9:
            this_chunk = min(chunk_size, remaining)
            chunks.append(this_chunk)
            remaining -= this_chunk
            if len(chunks) >= 20:
                chunks.append(remaining)
                break
        return chunks

    @staticmethod
    def mask_stake(raw_stake: float, round_to: float = 0.01) -> float:
        try:
            s = float(raw_stake)
        except Exception:
            return 0.0
        if s <= 0:
            return 0.0
        if CONFIG.stake_mask_enabled:
            s = round(s / round_to) * round_to
            s = max(round_to, s)
        return s

    @staticmethod
    def fok_stake(desired_stake: float, available_liquidity: float) -> float:
        if not CONFIG.fok_enabled:
            return desired_stake
        if available_liquidity <= 0:
            return 0.0
        return min(desired_stake, available_liquidity)

    @staticmethod
    def ioc_stake(desired_stake: float, available_liquidity: float) -> float:
        if not CONFIG.ioc_enabled:
            return desired_stake
        if available_liquidity <= 0:
            return 0.0
        return min(desired_stake, available_liquidity)

    @staticmethod
    def order_type(stake: float, available_liquidity: float, urgency: str = "normal") -> str:
        if urgency == "arb" and CONFIG.fok_enabled:
            return "FOK"
        if urgency == "live" and CONFIG.ioc_enabled:
            return "IOC"
        if available_liquidity < stake:
            return "IOC" if CONFIG.ioc_enabled else "LIMIT"
        return "LIMIT"


class BookmakerLimitStaking:
    @staticmethod
    async def adjust_for_limits(decision, state, db) -> float:
        try:
            raw_stake = float(getattr(decision, "stake", 0.0) or 0.0)
        except Exception:
            return 0.0
        if raw_stake <= 0:
            return 0.0
        bookmaker = str(getattr(decision, "bookmaker", "unknown") or "unknown")
        if db is None:
            return raw_stake
        try:
            row = await db.fetchone(
                "SELECT max_stake, is_limited, withdrawal_lock_until FROM bookmaker_limits WHERE bookmaker=?",
                (bookmaker,)
            )
            if row and row.get("is_limited"):
                lock_until = float(row.get("withdrawal_lock_until", 0.0) or 0.0)
                if time.time() < lock_until:
                    return 0.0
            max_stake = float(row.get("max_stake", raw_stake) or raw_stake) if row else raw_stake
            cushion = 1.0 - CONFIG.bookmaker_limit_cushion_pct
            capped = min(raw_stake, max_stake * cushion)
            return max(float(CONFIG.min_stake_per_bet), capped)
        except Exception:
            return raw_stake


class MultiBookArbScanner:
    @staticmethod
    async def scan(odds_data, bankroll: float, db=None, pinnacle_fetcher=None) -> List[Dict[str, Any]]:
        if not CONFIG.enable_arbitrage:
            return []
        opportunities = []
        for event in odds_data:
            event_id = event.get("id", str(uuid.uuid4()))
            bookmakers = event.get("bookmakers", [])
            best: Dict[str, Dict[str, Any]] = {}
            for bm in bookmakers:
                bm_key = str(bm.get("key", bm.get("title", "unknown")) or "unknown")
                for market in bm.get("markets", []):
                    m_type = str(market.get("key", ""))
                    for outcome in market.get("outcomes", []):
                        name = str(outcome.get("name", "")).strip().lower()
                        price = float(outcome.get("price", 0.0) or 0.0)
                        if not name or price <= 1.0:
                            continue
                        leg_key = f"{m_type}:{name}"
                        if leg_key not in best or price > best[leg_key]["price"]:
                            best[leg_key] = {"price": price, "bookmaker": bm_key, "market": m_type, "name": name}
            for market_type in ["h2h", "totals", "btts"]:
                items = {k: v for k, v in best.items() if v.get("market") == market_type}
                if len(items) < 2:
                    continue
                implied = sum(1.0 / v["price"] for v in items.values())
                profit = (1.0 - implied) * 100 if implied < 1.0 else 0.0
                if profit < CONFIG.arb_min_profit_pct:
                    continue
                legs = []
                total_stake = 0.0
                for leg_key, data in items.items():
                    leg_stake = bankroll * (1.0 / data["price"]) / implied * min(CONFIG.arb_max_stake_pct, 1.0 / len(items))
                    leg_stake = min(leg_stake, bankroll * CONFIG.arb_max_stake_pct)
                    legs.append({
                        "market": data["market"],
                        "outcome": data["name"],
                        "bookmaker": data["bookmaker"],
                        "odds": data["price"],
                        "stake": leg_stake,
                    })
                    total_stake += leg_stake
                if total_stake > bankroll * CONFIG.arb_max_stake_pct * len(items):
                    continue
                arb_id = str(uuid.uuid4())
                opp = {
                    "arb_id": arb_id,
                    "fixture_id": event.get("id", ""),
                    "market": market_type,
                    "legs": legs,
                    "total_implied": implied,
                    "profit_pct": profit,
                    "timestamp": time.time(),
                    "status": "detected",
                    "executed": 0.0,
                }
                opportunities.append(opp)
                if db:
                    try:
                        await db.execute(
                            "INSERT INTO arb_opportunities (arb_id, fixture_id, market, legs, total_implied, profit_pct, timestamp, status, executed) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
                            (arb_id, event.get("id", ""), market_type, json.dumps(legs), implied, profit, time.time(), "detected", 0.0)
                        )
                    except Exception:
                        pass
                log.info(f"MULTI-BOOK ARB: {market_type} profit={profit:.2f}% legs={len(legs)}")
                if profit >= getattr(CONFIG, "arb_alert_min_profit_pct", 5.0):
                    home = event.get("home_team") or event.get("homeTeam") or event.get("home", {}).get("name", "Home")
                    away = event.get("away_team") or event.get("awayTeam") or event.get("away", {}).get("name", "Away")
                    leg_details = "\n".join(
                        f"  - {leg['outcome']} @ {leg['odds']:.2f} on {leg['bookmaker']} | stake={leg['stake']:.2f}"
                        for leg in legs
                    )
                    alert_msg = (
                        f"ARBITRAGE OPPORTUNITY\n"
                        f"Match: {home} vs {away}\n"
                        f"Market: {market_type}\n"
                        f"Profit: {profit:.2f}%\n"
                        f"Legs:\n{leg_details}"
                    )
                    send_alert(alert_msg, level="warning", dedup_seconds=300, retry=3, priority=True)
                if CONFIG.enable_health_server:
                    try:
                        _METRICS["arb_alerts"] += 1
                    except Exception:
                        pass
        return opportunities

    @staticmethod
    def compute_arb_stakes(back_odds_list: List[float], target_profit_pct: float = 2.0) -> List[float]:
        try:
            odds = [max(1.01, float(o)) for o in back_odds_list]
            n = len(odds)
            if n < 2:
                return []
            implied = sum(1.0 / o for o in odds)
            if implied >= 1.0:
                return []
            stakes = [(1.0 / o) / implied for o in odds]
            return [max(0.0, s) for s in stakes]
        except Exception:
            return []


class PinnacleSharpLineFetcher:
    def __init__(self, api_key: str = "", base_url: str = ""):
        self.api_key = api_key or getattr(CONFIG, "pinnacle_api_key", "") or ""
        self.base_url = (base_url or getattr(CONFIG, "pinnacle_api_base_url", "https://api.pinnacle.com/v1") or "https://api.pinnacle.com/v1").rstrip("/")
        self.enabled = bool(self.api_key)
        self._cache: Dict[str, Tuple[float, Dict[str, Any]]] = {}
        self._cache_ttl = 30

    async def fetch_sharp_lines(self, sport: str = "soccer", market: str = "h2h") -> List[Dict[str, Any]]:
        if not self.enabled:
            return []
        cache_key = f"pinnacle_{sport}_{market}"
        cached = self._cache.get(cache_key)
        if cached and time.time() - cached[0] < self._cache_ttl:
            return cached[1]
        url = f"{self.base_url}/fixtures/odds"
        headers = {"Accept": "application/json", "Authorization": f"Bearer {self.api_key}"}
        params = {"sport": sport, "market": market, "oddsFormat": "decimal"}
        try:
            req = urllib.request.Request(url, data=None, headers=headers, method="GET")
            with urllib.request.urlopen(req, timeout=CONFIG.timeout) as resp:
                body = resp.read().decode("utf-8")
                data = json.loads(body) if body else []
        except Exception as exc:
            log.warning(f"Pinnacle fetch failed: {exc}")
            return []
        lines = []
        if isinstance(data, list):
            for event in data:
                lines.append({
                    "fixture_id": str(event.get("id", "")),
                    "home": event.get("homeTeam", {}).get("name", ""),
                    "away": event.get("awayTeam", {}).get("name", ""),
                    "market": market,
                    "odds": event.get("odds", {}),
                    "timestamp": time.time(),
                    "source": "pinnacle",
                })
        elif isinstance(data, dict) and "odds" in data:
            for event in data.get("odds", []):
                lines.append({
                    "fixture_id": str(event.get("id", "")),
                    "home": event.get("homeTeam", {}).get("name", ""),
                    "away": event.get("awayTeam", {}).get("name", ""),
                    "market": market,
                    "odds": event.get("odds", {}),
                    "timestamp": time.time(),
                    "source": "pinnacle",
                })
        self._cache[cache_key] = (time.time(), lines)
        return lines

    async def update_sharp_line_db(self, db):
        lines = await self.fetch_sharp_lines()
        if not db or not lines:
            return
        for line in lines:
            fixture_id = line.get("fixture_id", "")
            market = line.get("market", "h2h")
            odds = line.get("odds", {})
            if not isinstance(odds, dict):
                continue
            for outcome, sharp_odds in odds.items():
                try:
                    sharp_odds_f = float(sharp_odds)
                    if sharp_odds_f <= 1.0:
                        continue
                except Exception:
                    continue
                try:
                    await db.execute(
                        "INSERT OR REPLACE INTO sharp_lines (fixture_id, market, outcome, sharp_odds, soft_odds, timestamp, source) VALUES (?, ?, ?, ?, ?, ?, ?)",
                        (fixture_id, market, str(outcome), sharp_odds_f, 0.0, time.time(), "pinnacle")
                    )
                except Exception:
                    pass


class BetfairL2Parser:
    @staticmethod
    def parse_l2_snapshot(snapshot: Dict[str, Any]) -> Dict[str, Dict[str, List[Tuple[float, float]]]]:
        if not isinstance(snapshot, dict):
            return {}
        parsed: Dict[str, Dict[str, List[Tuple[float, float]]]] = {}
        for selection_id, levels in snapshot.items():
            if not isinstance(levels, dict):
                continue
            parsed[str(selection_id)] = {
                "back": [(float(p), float(v)) for p, v in levels.get("back", []) if float(p) > 1.0],
                "lay": [(float(p), float(v)) for p, v in levels.get("lay", []) if float(p) > 1.0],
            }
        return parsed

    @staticmethod
    def best_back_lay(parsed: Dict[str, Dict[str, List[Tuple[float, float]]]], selection_id: str) -> Dict[str, Optional[Tuple[float, float]]]:
        sel = parsed.get(str(selection_id), {})
        back = max(sel.get("back", []), key=lambda x: x[0], default=None)
        lay = min(sel.get("lay", []), key=lambda x: x[0], default=None)
        return {"best_back": back, "best_lay": lay}

    @staticmethod
    def mid_market_prob(parsed: Dict[str, Dict[str, List[Tuple[float, float]]]], selection_id: str) -> float:
        best = BetfairL2Parser.best_back_lay(parsed, selection_id)
        bb = best.get("best_back")
        bl = best.get("best_lay")
        if bb and bl and bb[0] > 0 and bl[0] > 0:
            mid = (bb[0] + bl[0]) / 2.0
            return 1.0 / mid if mid > 0 else 0.0
        if bb:
            return 1.0 / bb[0]
        return 0.0

    @staticmethod
    def depth_at_price(parsed: Dict[str, Dict[str, List[Tuple[float, float]]]], selection_id: str, side: str, price: float) -> float:
        sel = parsed.get(str(selection_id), {})
        levels = sel.get(side, [])
        total = 0.0
        for p, v in levels:
            if abs(p - price) < 1e-9:
                total += v
        return total


# ======================================================================
# JITTER SCHEDULER
# ======================================================================
class JitterScheduler:
    def __init__(self, db_pool):
        self.db = db_pool
        self.groups = {}
        self._sem = asyncio.Semaphore(max(1, int(CONFIG.max_concurrent_requests)))

    def generate_group_id(self):
        return str(uuid.uuid4())

    async def schedule_bet(self, bet_id, bookmaker, group_id=None):
        if group_id is None:
            group_id = self.generate_group_id()
        # Money Printing Fix: Near-zero jitter (0.2-0.5 seconds instead of 8-15 minutes)
        if CONFIG.enable_money_printing:
            jitter_seconds = random.uniform(0.2, 0.5)
        else:
            jitter_seconds = random.randint(CONFIG.jitter_min_minutes * 60, CONFIG.jitter_max_minutes * 60)
        scheduled_time = time.time() + jitter_seconds
        await self.db.execute(
            "INSERT INTO jitter_log (bet_group, bet_id, scheduled_time, jitter_seconds) VALUES (?, ?, ?, ?)",
            (group_id, bet_id, scheduled_time, jitter_seconds)
        )
        return group_id, scheduled_time

    async def execute_jittered_bets(self, decisions, execute_func, group_id: Optional[str] = None):
        if not decisions:
            return
        group_id = group_id or self.generate_group_id()
        tasks = []
        for idx, decision in enumerate(decisions):
            # Money Printing Fix: Near-zero jitter with iceberg immediate execution
            if CONFIG.enable_money_printing:
                jitter = random.uniform(0.2, 0.5)
            else:
                jitter = random.randint(CONFIG.jitter_min_minutes * 60, CONFIG.jitter_max_minutes * 60)
            if CONFIG.jitter_concurrent:
                tasks.append(asyncio.create_task(self._execute_one(decision, group_id, idx, jitter, execute_func)))
            else:
                if idx > 0:
                    await asyncio.sleep(jitter)
                await execute_func(decision, group_id, idx)
                await self.db.execute(
                    "UPDATE jitter_log SET executed_time = ? WHERE bet_group = ? AND bet_id = ?",
                    (time.time(), group_id, decision.get('bet_id'))
                )
        if tasks:
            await asyncio.gather(*tasks)
        cutoff = time.time() - 7 * 86400
        await self.db.execute("DELETE FROM jitter_log WHERE scheduled_time < ?", (cutoff,))

    async def _execute_one(self, decision, group_id, idx, jitter, execute_func):
        if idx > 0:
            await asyncio.sleep(jitter)
        async with self._sem:
            await execute_func(decision, group_id, idx)
        await self.db.execute(
            "UPDATE jitter_log SET executed_time = ? WHERE bet_group = ? AND bet_id = ?",
            (time.time(), group_id, decision.get('bet_id'))
        )

