    async def fetch_results(self):
        raw = None
        try:
            if CONFIG.football_api_key:
                url = "https://api.football-data.org/v4/matches"
                headers = {"X-Auth-Token": CONFIG.football_api_key}
                raw = await self._request_with_retry("GET", url, headers=headers, endpoint="football_api")
                if raw:
                    parsed = []
                    for match in raw.get("matches", []):
                        if match.get("status") not in ("FINISHED", "EXTRA_TIME"):
                            continue
                        fixture_id = str(match.get("id", ""))
                        home = match.get("homeTeam", {}).get("name", "")
                        away = match.get("awayTeam", {}).get("name", "")
                        score = match.get("score", {}).get("fullTime", {})
                        hg = score.get("home", 0) if score else 0
                        ag = score.get("away", 0) if score else 0
                        if CONFIG.enable_extra_time_handling and match.get("score", {}).get("extraTime"):
                            et = match["score"]["extraTime"]
                            if et.get("home") is not None and et.get("away") is not None:
                                hg = et["home"]
                                ag = et["away"]
                        home_corners = away_corners = home_bookings = away_bookings = 0
                        if CONFIG.stats_api_key:
                            stats_url = f"https://api.football-data.org/v4/matches/{fixture_id}/statistics"
                            stats_data = await self._request_with_retry("GET", stats_url, headers=headers, endpoint="stats_api")
                            if stats_data:
                                for stat in stats_data.get("statistics", []):
                                    for s in stat.get("statistics", []):
                                        if s.get("type") == "Corners":
                                            if stat.get("team", {}).get("name") == home:
                                                home_corners = int(self._cleanse_value(s.get("value", 0)))
                                            else:
                                                away_corners = int(self._cleanse_value(s.get("value", 0)))
                                        if s.get("type") == "Cards":
                                            if stat.get("team", {}).get("name") == home:
                                                home_bookings = int(self._cleanse_value(s.get("value", 0)))
                                            else:
                                                away_bookings = int(self._cleanse_value(s.get("value", 0)))
                        parsed.append({
                            "fixture_id": fixture_id,
                            "home": home,
                            "away": away,
                            "home_score": hg,
                            "away_score": ag,
                            "home_corners": home_corners,
                            "away_corners": away_corners,
                            "home_bookings": home_bookings,
                            "away_bookings": away_bookings
                        })
                    raw = parsed

            if not raw and CONFIG.use_free_scrapers and BeautifulSoup:
                url = "https://fbref.com/en/comps/9/schedule/Premier-League-Scores-and-Fixtures"
                headers = {"User-Agent": self._random_user_agent()}
                if self.use_aiohttp and self.session:
                    async with self.session.get(url, headers=headers, timeout=10) as resp:
                        if resp.status == 200:
                            text = await resp.text()
                            soup = BeautifulSoup(text, "html.parser")
                            rows = soup.select("table.stats_table tbody tr")
                            raw = []
                            for row in rows:
                                cols = row.find_all("td")
                                if len(cols) > 5:
                                    home = cols[1].text.strip()
                                    away = cols[2].text.strip()
                                    score_cell = cols[3].text.strip() if len(cols) > 3 else ""
                                    if score_cell and re.search(r'\d+[ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã…â€œ-]\d+', score_cell):
                                        parts = re.split(r'[-ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã…â€œÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â]', score_cell)
                                        if len(parts) == 2:
                                            hg = int(parts[0].strip())
                                            ag = int(parts[1].strip())
                                            fid = hashlib.md5(f"{home}{away}".encode()).hexdigest()[:8]
                                            raw.append({
                                                "fixture_id": fid,
                                                "home": home,
                                                "away": away,
                                                "home_score": hg,
                                                "away_score": ag,
                                                "home_corners": 0,
                                                "away_corners": 0,
                                                "home_bookings": 0,
                                                "away_bookings": 0
                                            })
        except Exception as e:
            log.error(f"Results fetch failed: {e}")

        valid, data = await self.schema_validator.validate_results(raw, "results_api")
        if valid and data:
            self._data_freeze_until = 0
            return data
        self._data_freeze_until = time.time() + CONFIG.data_freeze_timeout
        log.warning(f"No valid results. Betting frozen for {CONFIG.data_freeze_timeout}s.")
        return []

    async def is_data_frozen(self):
        return time.time() < self._data_freeze_until

    async def fetch_team_stats(self, team):
        key = f"team_stats_{team}"
        if key in self.cache and time.time() - self.cache_ts.get(key, 0) < self.cache_ttl:
            return self.cache[key]
        try:
            if CONFIG.stats_api_key:
                url = f"https://api.football-data.org/v4/teams/{team}/stats"
                headers = {"X-Auth-Token": CONFIG.stats_api_key}
                data = await self._request_with_retry("GET", url, headers=headers, endpoint="stats_api")
                if data:
                    res = {
                        "xg": self._cleanse_value(data.get("xg", 1.2)),
                        "shots": self._cleanse_value(data.get("shots", 10)),
                        "corners": self._cleanse_value(data.get("corners", 5)),
                        "cards": self._cleanse_value(data.get("cards", 2))
                    }
                    self.cache[key] = res
                    self.cache_ts[key] = time.time()
                    return res
            if BeautifulSoup:
                url = "https://fbref.com/en/comps/9/stats/"
                headers = {"User-Agent": self._random_user_agent()}
                if self.use_aiohttp and self.session:
                    async with self.session.get(url, headers=headers, timeout=10) as resp:
                        if resp.status == 200:
                            text = await resp.text()
                            soup = BeautifulSoup(text, "html.parser")
                            table = soup.select_one("table.stats_table")
                            if table:
                                rows = table.find_all("tr")
                                for row in rows:
                                    cells = row.find_all("td")
                                    if len(cells) > 15:
                                        team_name = cells[0].text.strip()
                                        if team_name.lower() == team.lower():
                                            res = {
                                                "xg": self._cleanse_value(cells[8].text if cells[8].text else 1.2),
                                                "shots": self._cleanse_value(cells[6].text if cells[6].text else 10),
                                                "corners": self._cleanse_value(cells[12].text if cells[12].text else 5),
                                                "cards": self._cleanse_value(cells[14].text if cells[14].text else 2) / 10
                                            }
                                            self.cache[key] = res
                                            self.cache_ts[key] = time.time()
                                            return res
        except Exception as e:
            log.warning(f"Team stats fetch failed: {e}")
        return {"xg": 1.2, "shots": 10, "corners": 5, "cards": 2}

    async def _geocode_query(self, query: str) -> Optional[Dict[str, Any]]:
        if not query:
            return None
        key = f"geo_{query.lower()}"
        if key in self.cache and time.time() - self.cache_ts.get(key, 0) < self.cache_ttl:
            return self.cache[key]
        url = "https://geocoding-api.open-meteo.com/v1/search"
        params = {"name": query, "count": 1, "language": "en", "format": "json"}
        data = await self._request_with_retry("GET", url, params=params, endpoint="open_meteo_geocode")
        if isinstance(data, dict) and data.get("results"):
            result = data["results"][0]
            self.cache[key] = result
            self.cache_ts[key] = time.time()
            return result
        return None

    async def fetch_h2h(self, home, away):
        key = f"h2h_{home}_{away}"
        if key in self.cache and time.time() - self.cache_ts.get(key, 0) < self.cache_ttl:
            return self.cache[key]
        reverse_key = f"h2h_{away}_{home}"
        if reverse_key in self.cache and time.time() - self.cache_ts.get(reverse_key, 0) < self.cache_ttl:
            reverse = self.cache[reverse_key]
            return {
                "home_win_rate": max(0.0, min(1.0, 1.0 - reverse.get("home_win_rate", 0.5))),
                "avg_goals": reverse.get("avg_goals", 2.5),
            }
        try:
            if BeautifulSoup:
                pairings = [(home, away, False), (away, home, True)]
                for left, right, reversed_pair in pairings:
                    home_slug = TeamMapper.slugify(left)
                    away_slug = TeamMapper.slugify(right)
                    url = f"https://fbref.com/en/head-to-head/{home_slug}-{away_slug}"
                    headers = {"User-Agent": self._random_user_agent()}
                    if self.use_aiohttp and self.session:
                        async with self.session.get(url, headers=headers, timeout=10) as resp:
                            if resp.status != 200:
                                continue
                            text = await resp.text()
                            soup = BeautifulSoup(text, "html.parser")
                            table = soup.select_one("table#match_results")
                            if table:
                                rows = table.find_all("tr")
                                total = home_wins = goals_sum = 0
                                for row in rows:
                                    cells = row.find_all("td")
                                    if len(cells) > 3:
                                        score_cell = cells[2].text.strip()
                                        if re.search(r'\d+[ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã…â€œ-]\d+', score_cell):
                                            parts = re.split(r'[-ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã…â€œÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â]', score_cell)
                                            if len(parts) == 2:
                                                hg = int(parts[0].strip())
                                                ag = int(parts[1].strip())
                                                total += 1
                                                goals_sum += hg + ag
                                                if hg > ag:
                                                    home_wins += 1
                                if total > 0:
                                    rate = home_wins / total
                                    if reversed_pair:
                                        rate = 1.0 - rate
                                    res = {"home_win_rate": rate, "avg_goals": goals_sum / total}
                                    self.cache[key] = res
                                    self.cache_ts[key] = time.time()
                                    return res
        except Exception as e:
            log.warning(f"H2H fetch failed: {e}")
        return {"home_win_rate": 0.5, "avg_goals": 2.5}

    async def fetch_injuries(self, team):
        key = f"injuries_{team}"
        if key in self.cache and time.time() - self.cache_ts.get(key, 0) < self.cache_ttl:
            return self.cache[key]
        impact = 0.0
        try:
            if BeautifulSoup:
                team_slug = team.lower().replace(' ', '-')
                url = f"https://www.premierinjuries.com/teams/{team_slug}"
                headers = {"User-Agent": self._random_user_agent()}
                if self.use_aiohttp and self.session:
                    async with self.session.get(url, headers=headers, timeout=10) as resp:
                        if resp.status == 200:
                            text = await resp.text()
                            soup = BeautifulSoup(text, "html.parser")
                            injury_table = soup.select_one("table.injury-list")
                            if injury_table:
                                rows = injury_table.find_all("tr")
                                count = 0
                                for row in rows:
                                    cells = row.find_all("td")
                                    if len(cells) > 2:
                                        return_date = cells[2].text.strip()
                                        if "Unknown" not in return_date:
                                            count += 1
                                impact = min(0.3, count * 0.05)
        except Exception as e:
            log.warning(f"Injury fetch failed: {e}")
        res = {"impact": impact, "injured": []}
        self.cache[key] = res
        self.cache_ts[key] = time.time()
        return res

