    async def fetch_closing_odds(self, fixture_id):
        key = f"closing_odds_{fixture_id}"
        async with self._lock:
            if key in self.cache and time.time() - self.cache_ts.get(key, 0) < self.cache_ttl:
                cached = self.cache.get(key)
                if isinstance(cached, dict):
                    return cached
        try:
            row = await self.schema_validator.db.fetchone(
                "SELECT closing_home, closing_draw, closing_away, odds_home, odds_draw, odds_away, odds_over, odds_under, odds_btts_yes, odds_btts_no FROM matches WHERE fixture_id=? ORDER BY timestamp DESC LIMIT 1",
                (fixture_id,)
            )
            if row:
                payload = {
                    "home": float(row.get("closing_home") or row.get("odds_home") or 0.0),
                    "draw": float(row.get("closing_draw") or row.get("odds_draw") or 0.0),
                    "away": float(row.get("closing_away") or row.get("odds_away") or 0.0),
                    "over": float(row.get("odds_over") or 0.0),
                    "under": float(row.get("odds_under") or 0.0),
                    "btts_yes": float(row.get("odds_btts_yes") or 0.0),
                    "btts_no": float(row.get("odds_btts_no") or 0.0),
                }
                payload = {k: v for k, v in payload.items() if v > 1.0}
                async with self._lock:
                    self.cache[key] = payload
                    self.cache_ts[key] = time.time()
                return payload
        except Exception as exc:
            log.warning(f"Closing odds fallback lookup failed for {fixture_id}: {exc}")
        return {}

    async def fetch_twitter_sentiment(self, query):
        if CONFIG.twitter_bearer_token:
            url = "https://api.twitter.com/2/tweets/search/recent"
            headers = {"Authorization": f"Bearer {CONFIG.twitter_bearer_token}"}
            params = {"query": query, "max_results": 10, "tweet.fields": "public_metrics"}
            try:
                if self.use_aiohttp and self.session:
                    async with self.session.get(url, headers=headers, params=params, timeout=10) as resp:
                        if resp.status == 200:
                            data = await resp.json()
                            retweets = sum(
                                t.get("public_metrics", {}).get("retweet_count", 0)
                                for t in data.get("data", [])
                            )
                            total = len(data.get("data", [])) or 1
                            return min(max(retweets / (total * 10), 0), 1)
            except Exception as e:
                log.warning(f"Twitter fetch failed: {e}")
        return 0.5

