    async def fetch_weather(self, lat, lon):
        if CONFIG.weather_api_key:
            key = f"weather_{lat}_{lon}"
            if key in self.cache and time.time() - self.cache_ts.get(key, 0) < self.cache_ttl:
                return self.cache[key]
            url = f"https://api.openweathermap.org/data/2.5/weather?lat={lat}&lon={lon}&appid={CONFIG.weather_api_key}&units=metric"
            data = await self._request_with_retry("GET", url, endpoint="weather_api")
            if data:
                res = {
                    "temp": self._cleanse_value(data["main"]["temp"]),
                    "humidity": self._cleanse_value(data["main"]["humidity"]),
                    "wind": self._cleanse_value(data["wind"]["speed"]),
                    "rain": self._cleanse_value(data.get("rain", {}).get("1h", 0))
                }
                self.cache[key] = res
                self.cache_ts[key] = time.time()
                return res
        return {"temp": 15, "humidity": 50, "wind": 5, "rain": 0}

    async def fetch_weather_for_match(self, home: str, away: str = "", competition: str = ""):
        query_candidates = [home, f"{home} {competition}".strip(), away]
        for query in query_candidates:
            geo = await self._geocode_query(query)
            if not geo:
                continue
            lat = geo.get("latitude")
            lon = geo.get("longitude")
            if lat is None or lon is None:
                continue
            weather = await self.fetch_weather(lat, lon)
            if weather:
                return weather
        return {"temp": 15, "humidity": 50, "wind": 5, "rain": 0}

