# CHECKPOINT MANAGER
# ======================================================================
class CheckpointManager:
    def __init__(self, db_pool):
        self.db = db_pool
        self._prune_days = CONFIG.checkpoint_prune_days

    async def create_batch(self, batch_id, decisions):
        decisions_serial = []
        for d in decisions:
            if isinstance(d, BetDecision):
                decisions_serial.append(d.dict())
            else:
                decisions_serial.append(d)
        await self.db.execute(
            "INSERT INTO batch_checkpoint (batch_id, decisions, status, created) VALUES (?, ?, ?, ?)",
            (batch_id, json.dumps(decisions_serial, default=str), "pending", time.time())
        )

    async def mark_executed(self, batch_id):
        await self.db.execute(
            "UPDATE batch_checkpoint SET status = 'executed' WHERE batch_id = ?",
            (batch_id,)
        )

    async def recover_pending(self):
        rows = await self.db.fetchall("SELECT * FROM batch_checkpoint WHERE status = 'pending'")
        recovered = []
        for row in rows:
            try:
                decisions_data = json.loads(row['decisions'])
                decisions = []
                for d in decisions_data:
                    decisions.append(BetDecision(**d))
                recovered.append((row['batch_id'], decisions))
            except Exception as e:
                log.error(f"Recover batch {row['batch_id']} failed: {e}")
                if CONFIG.batch_checkpoint_recovery:
                    await self.mark_executed(row['batch_id'])
        return recovered

