# BANKROLL MANAGER
# ======================================================================
class BankrollManager:
    def __init__(self, state, db_pool):
        self.state = state
        self.db = db_pool
        self._lock = asyncio.Lock()

    def get_balance(self, bookmaker):
        return self.state.get("bankroll_per_bookmaker", {}).get(
            bookmaker, self.state.get("bankroll", 1000.0)
        )

    async def deduct(self, bookmaker, amount):
        async with self._lock:
            balances = self.state.get("bankroll_per_bookmaker", {})
            current = balances.get(bookmaker, self.state.get("bankroll", 1000.0))
            if current < amount:
                raise ValueError("Insufficient balance")
            new_balance = current - amount
            balances[bookmaker] = new_balance
            self.state.set("bankroll_per_bookmaker", balances)
            total = sum(balances.values())
            self.state.set("bankroll", total)
            await self.db.execute(
                "INSERT OR REPLACE INTO bankroll_ledger (bookmaker, balance, updated) VALUES (?, ?, ?)",
                (bookmaker, new_balance, time.time())
            )
            await self.state.flush()
            return new_balance

    async def add(self, bookmaker, amount):
        async with self._lock:
            balances = self.state.get("bankroll_per_bookmaker", {})
            current = balances.get(bookmaker, self.state.get("bankroll", 1000.0))
            new_balance = current + amount
            balances[bookmaker] = new_balance
            self.state.set("bankroll_per_bookmaker", balances)
            total = sum(balances.values())
            self.state.set("bankroll", total)
            await self.db.execute(
                "INSERT OR REPLACE INTO bankroll_ledger (bookmaker, balance, updated) VALUES (?, ?, ?)",
                (bookmaker, new_balance, time.time())
            )
            await self.state.flush()
            return new_balance

