# BACKTEST ENGINE
# ======================================================================
class BacktestEngine:
    """Historical backtesting runner with walk-forward validation and performance reporting."""
    def __init__(self, dept, state, db):
        self.dept = dept
        self.state = state
        self.db = db
        self.results = []
        self.benchmark_profit = 0.0

    async def run(self, start_date: str = None, end_date: str = None) -> Dict:
        global LHM_BACKTEST_MODE
        LHM_BACKTEST_MODE = True
        try:
            return await self._run_impl(start_date, end_date)
        finally:
            LHM_BACKTEST_MODE = False

    async def _run_impl(self, start_date: str = None, end_date: str = None) -> Dict:
        start = datetime.fromisoformat(start_date or CONFIG.backtest_start).timestamp()
        end = datetime.fromisoformat(end_date or CONFIG.backtest_end or "2099-01-01").timestamp()
        log.info(f"Running backtest from {start_date} to {end_date}")

        # Wire in LHM institutional-grade upgrades (Groups D/E/F). These are
        # pulled from the OmniDepartment's upgrade registry so the same
        # production components run during backtesting.
        upg = getattr(self.dept, "_upgrade_components", {}) or {}
        _heartbeat = upg.get("heartbeat")
        _slippage = upg.get("slippage_predictor")
        _edge_decay = upg.get("edge_decay")
        _pnl_attrib = upg.get("pnl_attribution")
        _cov_kelly = upg.get("cov_kelly")
        _bookmaker_router = upg.get("bookmaker_router")
        _atomic_bet = upg.get("atomic_bet_unit")
        _order_book = upg.get("order_book")

        filepath = CONFIG.historical_data_path
        if not os.path.exists(filepath):
            log.warning("Historical data not found. Returning empty report.")
            return self._empty_report()

        hist = pd.read_csv(filepath)
        if 'timestamp' in hist.columns:
            hist = hist[(hist['timestamp'] >= start) & (hist['timestamp'] <= end)]
        if hist.empty:
            log.warning("No matches in backtest period.")
            return self._empty_report()

        initial_bankroll = 1000.0
        bankroll = initial_bankroll
        total_bets = 0
        total_wins = 0
        total_stake = 0.0
        total_profit = 0.0
        returns = []
        peak = initial_bankroll
        drawdowns = []
        benchmark_bankroll = initial_bankroll

        rows = list(hist.itertuples(index=False, name='HistRow'))
        batch_size = max(8, min(64, int(CONFIG.max_concurrent_requests) * 2))
        for start_idx in range(0, len(rows), batch_size):
            chunk = rows[start_idx:start_idx + batch_size]
            normalized = []
            for row in chunk:
                match_row = dict(row._asdict())
                for field in OddsRow.__fields__.keys():
                    if field not in match_row or match_row[field] is None:
                        if field in ['home_xg', 'away_xg']:
                            match_row[field] = 1.2 if field == 'home_xg' else 1.0
                        elif field in ['home_shots', 'away_shots']:
                            match_row[field] = 10.0 if field == 'home_shots' else 8.0
                        elif field in ['home_corners', 'away_corners']:
                            match_row[field] = 5.0 if field == 'home_corners' else 4.0
                        elif field in ['home_cards', 'away_cards']:
                            match_row[field] = 2.0
                        elif field in ['form_home', 'form_away']:
                            match_row[field] = 0.5
                        elif field in ['lineup_strength_home', 'lineup_strength_away']:
                            match_row[field] = 0.8
                        elif field in ['h2h_home_win_rate', 'h2h_avg_goals']:
                            match_row[field] = 0.5 if field == 'h2h_home_win_rate' else 2.5
                        elif field in ['market_volume', 'research_confidence', 'source_reliability']:
                            match_row[field] = 0.5
                        elif field in ['source_coverage_count']:
                            match_row[field] = 6
                        elif field in ['source_coverage_total']:
                            match_row[field] = 12
                        elif field in ['odds_home', 'odds_draw', 'odds_away']:
                            match_row[field] = 2.0 if field == 'odds_home' else (3.5 if field == 'odds_draw' else 4.0)
                        elif field in ['fixture_id', 'home', 'away', 'competition', 'match_date', 'bookmaker', 'xg_source']:
                            match_row[field] = ''
                        else:
                            match_row[field] = 0.0
                normalized.append(match_row)

            decisions_batch = await asyncio.gather(*[self.dept.predict_all_markets(m, backtest_mode=True) for m in normalized], return_exceptions=True)

            for row, match_row, decisions in zip(chunk, normalized, decisions_batch):
                if isinstance(decisions, Exception) or not decisions:
                    continue
                # Normalize BetDecision objects to dicts for backtest consumption
                if decisions and hasattr(decisions[0], 'model_dump'):
                    decisions = [d.model_dump() for d in decisions]
                elif decisions and hasattr(decisions[0], 'dict'):
                    decisions = [d.dict() for d in decisions]
                # (Upgrade #3) Data-lag circuit breaker: if the feed heartbeat is
                # unhealthy, skip this fixture entirely (no stale-data bets).
                if _heartbeat is not None:
                    _heartbeat.ping()
                    if not _heartbeat.is_healthy():
                        continue
                best = max(decisions, key=lambda d: d.get('edge', -1))
                stake = best['stake']
                odds = best['odds']
                # (Upgrade #26) Adaptive edge-decay monitor: once realized edge
                # falls below 50% of expected over the window, halt this market.
                if _edge_decay is not None and _edge_decay.check_decay():
                    stake = 0.0
                if stake <= 0 or odds <= 1:
                    continue
                actual = 'home' if getattr(row, 'home_goals', 0) > getattr(row, 'away_goals', 0) else 'away' if getattr(row, 'away_goals', 0) > getattr(row, 'home_goals', 0) else 'draw'
                won = (best['outcome'] == actual)
                # (Upgrade #15) Execution slippage modelling: degrade the
                # effective odds so results reflect real-world fills.
                exec_odds = odds
                if _slippage is not None:
                    slip = _slippage.predict(
                        float(match_row.get('volatility', 0.0) or 0.0),
                        float(match_row.get('bid_ask_spread', 0.02) or 0.02),
                        float(match_row.get('market_volume', 1.0) or 1.0),
                    )
                    exec_odds = max(1.001, odds * (1.0 - slip))
                profit = stake * (exec_odds - 1) if won else -stake
                bankroll += profit
                total_bets += 1
                total_wins += 1 if won else 0
                total_stake += stake
                total_profit += profit
                returns.append(profit / initial_bankroll)
                # (Upgrade #21) PnL attribution + (#26) edge-decay + (#18) covariance-Kelly
                # tracking, recorded after each settled bet.
                if _edge_decay is not None:
                    _edge_decay.record(
                        expected_edge=float(best.get('edge', 0.0)),
                        realized_edge=float(profit / stake) if stake > 0 else 0.0,
                    )
                if _pnl_attrib is not None:
                    _pnl_attrib.record(
                        bet_id=f"bt_{total_bets}",
                        feature_group="backtest",
                        pnl=float(profit),
                        shap_values={"edge": float(best.get('edge', 0.0))},
                    )
                if _cov_kelly is not None:
                    _cov_kelly.update_return(
                        bet_id=str(best.get('market', '1x2')),
                        ret=float(profit / initial_bankroll),
                    )
                if bankroll > peak:
                    peak = bankroll
                drawdown = (peak - bankroll) / peak if peak > 0 else 0
                drawdowns.append(drawdown)

                if CONFIG.enable_benchmark:
                    fav_odds = min(getattr(row, 'odds_home', 2.0), getattr(row, 'odds_away', 4.0))
                    if fav_odds > 0:
                        fav_outcome = 'home' if getattr(row, 'odds_home', 2.0) < getattr(row, 'odds_away', 4.0) else 'away'
                        bench_stake = CONFIG.flat_stake_pct * initial_bankroll
                        bench_won = (fav_outcome == actual)
                        bench_profit = bench_stake * (fav_odds - 1) if bench_won else -bench_stake
                        benchmark_bankroll += bench_profit
                        self.benchmark_profit += bench_profit

        if total_bets == 0:
            return self._empty_report()

        roi = total_profit / total_stake if total_stake > 0 else 0
        win_rate = total_wins / total_bets
        sharpe = np.mean(returns) / (np.std(returns) + 1e-9)
        max_drawdown = max(drawdowns) if drawdowns else 0
        profit_factor = (total_profit + total_stake) / (total_stake - total_profit) if (total_stake - total_profit) > 0 else 0

        report = {
            "total_bets": total_bets,
            "total_wins": total_wins,
            "total_stake": total_stake,
            "total_profit": total_profit,
            "roi": roi,
            "sharpe": sharpe,
            "max_drawdown": max_drawdown,
            "win_rate": win_rate,
            "profit_factor": profit_factor,
            "final_bankroll": bankroll,
            "benchmark_profit": self.benchmark_profit,
            "benchmark_roi": self.benchmark_profit / (total_stake or 1),
            # LHM institutional-grade observability summaries (Groups E/F).
            "edge_decay_summary": _edge_decay.summary() if _edge_decay is not None else {},
            "pnl_attribution_report": _pnl_attrib.group_summary() if _pnl_attrib is not None else {},
        }
        try:
            await self.db.execute(
                "INSERT INTO baseline_results (bet_id, strategy, stake, profit, timestamp) VALUES (?,?,?,?,?)",
                (f"backtest_{int(time.time())}", "favorite_flat_stake", float(total_stake or 0.0), float(self.benchmark_profit or 0.0), time.time())
            )
        except Exception as exc:
            log.warning(f"baseline_results write failed: {exc}")
        return report

    def _empty_report(self):
        return {
            "total_bets": 0,
            "total_wins": 0,
            "total_stake": 0,
            "total_profit": 0,
            "roi": 0,
            "sharpe": 0,
            "max_drawdown": 0,
            "win_rate": 0,
            "profit_factor": 0,
            "final_bankroll": 1000.0,
            "benchmark_profit": 0.0,
            "benchmark_roi": 0.0
        }

    async def run_with_report(self, start_date: str = None, end_date: str = None) -> Dict:
        return await self.run(start_date, end_date)


class SelfRepairBacktestLoop:
    def __init__(self, dept, state, db):
        self.dept = dept
        self.state = state
        self.db = db
        self.history = []
        self._config_view = self._snapshot_config()
        self.repair_profile = self._default_repair_profile()
        self.repair_profile.update(self._load_repair_profile())
        # Realistic account-limit model (you get limited after a few bets).
        self._limit_model = AccountLimitModel()

    @staticmethod
    def _snapshot_config() -> Dict[str, Any]:
        keys = [
            "historical_data_path", "football_api_key", "min_stake_per_bet", "max_stake_per_bet",
            "min_single_edge", "fractional_kelly_factor", "min_data_quality_for_market_expansion",
            "public_hype_penalty_factor",
        ]
        snap: Dict[str, Any] = {}
        for key in keys:
            snap[key] = getattr(CONFIG, key, None)
        return snap

    def _cfg(self, key: str, default: Any = None) -> Any:
        return self._config_view.get(key, default)

    def _default_repair_profile(self) -> Dict[str, float]:
        return {
            "home_boost": 0.025,
            "away_boost": 0.025,
            "draw_boost": 0.004,
            "edge_buffer": 0.032,
            "stake_boost": 0.008,
            "confidence_boost": 0.045,
            "market_filter": 0.55,
            "xg_weight": 0.055,
            "shots_weight": 0.032,
            "corners_weight": 0.018,
            "form_weight": 0.024,
            "cards_weight": 0.012,
            "odds_weight": 0.02,
            "draw_suppression": 0.01,
        }

    def _load_repair_profile(self) -> Dict[str, float]:
        data = self.state.get("self_repair_profile", {}) or {}
        profile = self._default_repair_profile()
        for key, value in data.items():
            if key in profile:
                try:
                    profile[key] = float(value)
                except Exception:
                    pass
        return profile

    async def _persist_repair_profile(self) -> None:
        self.state.set("self_repair_profile", self.repair_profile)
        await self.state.flush()

    async def run(self, start_year: int = 2001, end_year: int = 2025) -> Dict[str, Any]:
        history = []
        self.state.set("self_repair_backtest_history", [])
        for year in range(start_year, end_year + 1):
            matches = await self._load_matches_for_year(year)
            if not matches:
                print(f"[{year}] no usable matches found, skipping")
                continue

            report = await self._run_year_matches(matches, year)
            history.append(report)
            self.history.append(report)
            self.state.set("self_repair_backtest_history", history)
            await self.state.flush()

            print(
                f"[SELF-REPAIR {year}] total={report['total']} won={report['won']} lost={report['lost']} "
                f"win_rate={report['win_rate']:.2%} profit={report['profit']:.2f} roi={report['roi']:.2%}"
            )

            weakness = self._classify_weakness(report)
            await self._apply_repair(weakness, report)
            await self._persist_repair_profile()
            print(f"[SELF-REPAIR {year}] weakness={weakness} repair_applied")

        summary = {
            "start_year": start_year,
            "end_year": end_year,
            "years": len(history),
            "total_bets": sum(item["total"] for item in history),
            "total_wins": sum(item["won"] for item in history),
            "total_losses": sum(item["lost"] for item in history),
            "final_profit": sum(item["profit"] for item in history),
            "final_roi": sum(item["profit"] for item in history) / max(1.0, sum(item["stake"] for item in history)),
            "history": history,
        }
        self.state.set("self_repair_backtest_summary", summary)
        await self.state.flush()
        return summary

    async def _load_matches_for_year(self, year: int) -> List[Dict[str, Any]]:
        csv_path = self._cfg("historical_data_path", CONFIG.historical_data_path)
        if os.path.exists(csv_path):
            try:
                df = pd.read_csv(csv_path)
                if df.empty:
                    return []
                year_candidates = []
                for col in ["timestamp", "date", "match_date", "kickoff"]:
                    if col in df.columns:
                        year_candidates.append(col)
                if year_candidates:
                    source_col = year_candidates[0]
                    try:
                        if pd.api.types.is_numeric_dtype(df[source_col]):
                            mask = (df[source_col] >= datetime(year, 1, 1).timestamp()) & (df[source_col] <= datetime(year, 12, 31, 23, 59, 59).timestamp())
                            subset = df.loc[mask]
                        else:
                            subset = df[df[source_col].astype(str).str.startswith(str(year))]
                        if not subset.empty:
                            return self._rows_to_matches(subset.to_dict(orient="records"))
                    except Exception:
                        pass
                return []
            except Exception:
                pass

        if requests is not None:
            try:
                url = f"https://api.football-data.org/v4/matches?dateFrom={year}-01-01&dateTo={year}-12-31"
                football_api_key = self._cfg("football_api_key", CONFIG.football_api_key)
                headers = {"X-Auth-Token": football_api_key} if football_api_key else {}
                resp = requests.get(url, headers=headers, timeout=10)
                if resp.ok:
                    payload = resp.json()
                    matches = []
                    for item in payload.get("matches", []):
                        score = item.get("score", {}).get("fullTime", {})
                        matches.append({
                            "fixture_id": str(item.get("id", "")),
                            "home": item.get("homeTeam", {}).get("name", "Home"),
                            "away": item.get("awayTeam", {}).get("name", "Away"),
                            "home_goals": score.get("home", 0),
                            "away_goals": score.get("away", 0),
                            "home_xg": 1.2,
                            "away_xg": 1.0,
                            "odds_home": 2.0,
                            "odds_draw": 3.5,
                            "odds_away": 4.0,
                            "competition": item.get("competition", {}).get("name", "Unknown"),
                            "timestamp": time.mktime(datetime(year, 1, 1).timetuple()),
                        })
                    if matches:
                        return matches
            except Exception:
                pass

        return self._generate_synthetic_matches(year)

    def _generate_synthetic_matches(self, year: int) -> List[Dict[str, Any]]:
        rng = random.Random(1000 + year)
        matches = []
        for idx in range(80):
            home_xg = max(0.3, min(3.5, 1.1 + rng.uniform(-0.3, 0.5) + (year % 10) * 0.01))
            away_xg = max(0.3, min(3.5, 0.95 + rng.uniform(-0.3, 0.45) + (year % 7) * 0.005))
            home_goals = int(np.random.poisson(home_xg)) if HAS_NUMPY else int(rng.uniform(0, 3))
            away_goals = int(np.random.poisson(away_xg)) if HAS_NUMPY else int(rng.uniform(0, 3))
            matches.append({
                "fixture_id": f"synthetic_{year}_{idx}",
                "home": f"Home{idx}",
                "away": f"Away{idx}",
                "home_goals": home_goals,
                "away_goals": away_goals,
                "home_xg": home_xg,
                "away_xg": away_xg,
                "odds_home": round(max(1.5, 1.8 + rng.uniform(-0.2, 0.25)), 2),
                "odds_draw": round(max(2.8, 3.0 + rng.uniform(-0.2, 0.4)), 2),
                "odds_away": round(max(1.8, 2.0 + rng.uniform(-0.2, 0.3)), 2),
                "competition": "SyntheticLeague",
                "timestamp": time.mktime(datetime(year, 1, 1).timetuple()) + idx * 86400,
            })
            # Inject real-world data messiness so the self-repair backtest
            # tests robustness, not memorisation of the clean generator.
            matches.append(_DATA_INJECTOR.inject(match))
        return matches

    def _rows_to_matches(self, rows: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        matches = []
        for row in rows:
            try:
                match = {
                    "fixture_id": row.get("fixture_id") or row.get("id") or str(uuid.uuid4()),
                    "home": row.get("home") or row.get("home_team") or "Home",
                    "away": row.get("away") or row.get("away_team") or "Away",
                    "home_goals": int(row.get("home_goals", row.get("home_score", 0) or 0)),
                    "away_goals": int(row.get("away_goals", row.get("away_score", 0) or 0)),
                    "home_xg": float(row.get("home_xg", 1.2) or 1.2),
                    "away_xg": float(row.get("away_xg", 1.0) or 1.0),
                    "odds_home": float(row.get("odds_home", 2.0) or 2.0),
                    "odds_draw": float(row.get("odds_draw", 3.5) or 3.5),
                    "odds_away": float(row.get("odds_away", 4.0) or 4.0),
                    "competition": row.get("competition") or row.get("league") or "Unknown",
                    "timestamp": row.get("timestamp", time.time()),
                }
                matches.append(match)
            except Exception:
                continue
        return matches

    async def _run_year_matches(self, matches: List[Dict[str, Any]], year: int) -> Dict[str, Any]:
        bankroll = 1000.0
        total = 0
        won = 0
        stake = 0.0
        profit = 0.0
        # Fresh account each year: realistic limit re-applies (you get limited
        # after a few bets, so only the first handful of stakes are accepted).
        try:
            self._limit_model.reset_day()
        except Exception:
            pass
        for match in matches[:60]:
            match_row = dict(match)
            match_row["match_date"] = datetime.fromtimestamp(match_row.get("timestamp", time.time())).date().isoformat()
            decisions = self._fast_decisions(match_row)
            if not decisions:
                continue
            best = max(decisions, key=lambda d: (getattr(d, "quality", d.edge), getattr(d, "confidence_score", 0.0)))
            if not getattr(best, "odds", None) or best.odds <= 1:
                continue
            if getattr(best, "confidence_score", 0.0) < 0.58 or getattr(best, "edge", 0.0) < self.repair_profile["edge_buffer"] - 0.002:
                continue
            actual = "home" if match_row.get("home_goals", 0) > match_row.get("away_goals", 0) else "away" if match_row.get("away_goals", 0) > match_row.get("home_goals", 0) else "draw"
            won_flag = best.outcome == actual
            min_stake = float(self._cfg("min_stake_per_bet", CONFIG.min_stake_per_bet) or CONFIG.min_stake_per_bet)
            max_stake = float(self._cfg("max_stake_per_bet", CONFIG.max_stake_per_bet) or CONFIG.max_stake_per_bet)
            stake_amount = max(min_stake * bankroll, min(getattr(best, "stake", 0.01), max_stake * bankroll))
            # ---- real-world friction (no longer a fairy-tale backtest) ----
            edge = getattr(best, "edge", 0.0)
            # market-efficiency guard: cap phantom edges, kill suspicious ones
            if _EFF_GUARD.is_suspicious(edge):
                continue
            pnl, accepted = backtest_settle(
                stake_amount, best.odds, won_flag,
                commission=CONFIG.backtest_commission,
                slippage=CONFIG.execution_slippage,
                account=self._limit_model, edge=edge,
            )
            if accepted <= 0:
                continue
            gain = pnl
            bankroll += gain
            total += 1
            won += int(won_flag)
            stake += accepted
            profit += gain

        lost = total - won
        win_rate = won / total if total else 0.0
        roi = profit / stake if stake else 0.0
        return {
            "year": year,
            "total": total,
            "won": won,
            "lost": lost,
            "win_rate": win_rate,
            "profit": profit,
            "stake": stake,
            "roi": roi,
            "bankroll": bankroll,
        }

    def _manual_probabilities(self, match_row: Dict[str, Any]) -> Dict[str, float]:
        profile = self.repair_profile
        try:
            home_xg = max(0.2, float(match_row.get("home_xg", 1.2)))
            away_xg = max(0.2, float(match_row.get("away_xg", 1.0)))
            home_shots = max(1.0, float(match_row.get("home_shots", 10.0)))
            away_shots = max(1.0, float(match_row.get("away_shots", 8.0)))
            home_corners = max(0.0, float(match_row.get("home_corners", 5.0)))
            away_corners = max(0.0, float(match_row.get("away_corners", 4.0)))
            home_cards = max(0.0, float(match_row.get("home_cards", 2.0)))
            away_cards = max(0.0, float(match_row.get("away_cards", 2.0)))
            form_home = max(0.0, min(1.0, float(match_row.get("form_home", 0.5))))
            form_away = max(0.0, min(1.0, float(match_row.get("form_away", 0.5))))
            is_derby = float(match_row.get("is_derby", 0) or 0)
            xg_gap = home_xg - away_xg
            shot_gap = home_shots - away_shots
            corner_gap = home_corners - away_corners
            card_gap = away_cards - home_cards
            form_gap = form_home - form_away

            home_signal = (
                profile["xg_weight"] * xg_gap
                + profile["shots_weight"] * (shot_gap / 10.0)
                + profile["corners_weight"] * (corner_gap / 6.0)
                + profile["form_weight"] * form_gap
                + 0.02 * is_derby
                + profile["home_boost"]
            )
            away_signal = (
                profile["xg_weight"] * (-xg_gap)
                + profile["shots_weight"] * (-shot_gap / 10.0)
                + profile["corners_weight"] * (-corner_gap / 6.0)
                + profile["form_weight"] * (-form_gap)
                + 0.02 * is_derby
                + profile["away_boost"]
            )
            draw_signal = (
                0.08 * max(0.0, 1.0 - abs(xg_gap) / 2.0)
                + 0.04 * max(0.0, 1.0 - abs(shot_gap) / 16.0)
                + 0.03 * (1.0 if abs(form_gap) < 0.15 else 0.0)
                + profile["draw_boost"]
                - profile["draw_suppression"] * max(0.0, card_gap / 4.0)
            )

            home_prob = max(0.08, min(0.86, 0.34 + home_signal))
            away_prob = max(0.08, min(0.86, 0.34 + away_signal))
            draw_prob = max(0.08, min(0.48, 0.28 + draw_signal))
            total = home_prob + away_prob + draw_prob
            home_prob /= total
            away_prob /= total
            draw_prob /= total

            odds_home = max(1.01, float(match_row.get("odds_home", 2.0)))
            odds_draw = max(1.01, float(match_row.get("odds_draw", 3.5)))
            odds_away = max(1.01, float(match_row.get("odds_away", 4.0)))
            implied_home = 1.0 / odds_home
            implied_draw = 1.0 / odds_draw
            implied_away = 1.0 / odds_away
            home_prob = max(0.08, min(0.86, home_prob + profile["odds_weight"] * (implied_home - 0.35)))
            away_prob = max(0.08, min(0.86, away_prob + profile["odds_weight"] * (implied_away - 0.35)))
            draw_prob = max(0.08, min(0.48, draw_prob + profile["odds_weight"] * (implied_draw - 0.28)))
            total = home_prob + away_prob + draw_prob
            home_prob /= total
            away_prob /= total
            draw_prob /= total
            return {"home": home_prob, "draw": draw_prob, "away": away_prob}
        except Exception:
            return {"home": 0.33, "draw": 0.34, "away": 0.33}

    def _fast_decisions(self, match_row: Dict[str, Any]) -> List[SimpleNamespace]:
        profile = self.repair_profile
        probs = self._manual_probabilities(match_row)
        odds_home = max(1.01, float(match_row.get("odds_home", 2.0)))
        odds_draw = max(1.01, float(match_row.get("odds_draw", 3.5)))
        odds_away = max(1.01, float(match_row.get("odds_away", 4.0)))
        implied_home = 1.0 / odds_home
        implied_draw = 1.0 / odds_draw
        implied_away = 1.0 / odds_away

        try:
            home_xg = max(0.2, float(match_row.get("home_xg", 1.2)))
            away_xg = max(0.2, float(match_row.get("away_xg", 1.0)))
            home_shots = max(1.0, float(match_row.get("home_shots", 10.0)))
            away_shots = max(1.0, float(match_row.get("away_shots", 8.0)))
            home_corners = max(0.0, float(match_row.get("home_corners", 5.0)))
            away_corners = max(0.0, float(match_row.get("away_corners", 4.0)))
            form_home = max(0.0, min(1.0, float(match_row.get("form_home", 0.5))))
            form_away = max(0.0, min(1.0, float(match_row.get("form_away", 0.5))))
            signal_strength = (
                abs(home_xg - away_xg) * 0.65
                + abs(home_shots - away_shots) / 12.0
                + abs(home_corners - away_corners) / 8.0
                + abs(form_home - form_away) * 0.6
            )
            if signal_strength < 0.32 + profile["market_filter"] * 0.18:
                return []
        except Exception:
            pass

        decisions = []
        for outcome, prob, odds, implied in (("home", probs["home"], odds_home, implied_home), ("draw", probs["draw"], odds_draw, implied_draw), ("away", probs["away"], odds_away, implied_away)):
            edge = prob - implied
            confidence = min(0.99, max(0.2, 0.12 + abs(edge) + profile["confidence_boost"]))
            min_edge = profile["edge_buffer"] - 0.003
            if outcome == "draw":
                min_edge += 0.008
            if confidence < 0.54 or edge < min_edge:
                continue
            quality = edge * (0.9 + confidence * 0.7) - (0.005 if odds >= 4.0 else 0.0)
            if quality <= 0.0:
                continue
            decisions.append(SimpleNamespace(
                outcome=outcome,
                edge=edge,
                confidence_score=confidence,
                odds=odds,
                quality=quality,
                stake=min(0.05, max(0.006, 0.008 + edge * 0.06 + profile["stake_boost"])),
            ))
        if not decisions:
            return []
        return sorted(decisions, key=lambda d: d.quality, reverse=True)[:2]

    def _classify_weakness(self, report: Dict[str, Any]) -> str:
        if report["win_rate"] < 0.45:
            return "low_edge_quality"
        if report["roi"] < 0.0:
            return "stake_sizing"
        return "market_regime"

    async def _apply_repair(self, weakness: str, report: Dict[str, Any]) -> None:
        profile = self.repair_profile
        recommended_overrides = dict(self.state.get("self_repair_recommended_overrides", {}) or {})
        min_single_edge = float(self._cfg("min_single_edge", CONFIG.min_single_edge) or CONFIG.min_single_edge)
        fractional_kelly = float(self._cfg("fractional_kelly_factor", CONFIG.fractional_kelly_factor) or CONFIG.fractional_kelly_factor)
        max_stake_per_bet = float(self._cfg("max_stake_per_bet", CONFIG.max_stake_per_bet) or CONFIG.max_stake_per_bet)
        min_data_quality_for_market_expansion = float(self._cfg("min_data_quality_for_market_expansion", CONFIG.min_data_quality_for_market_expansion) or CONFIG.min_data_quality_for_market_expansion)
        public_hype_penalty_factor = float(self._cfg("public_hype_penalty_factor", CONFIG.public_hype_penalty_factor) or CONFIG.public_hype_penalty_factor)
        if weakness == "low_edge_quality":
            profile["edge_buffer"] = min(0.09, max(0.02, profile["edge_buffer"] + 0.004))
            profile["confidence_boost"] = min(0.12, max(0.03, profile["confidence_boost"] + 0.004))
            profile["market_filter"] = min(0.7, max(0.45, profile["market_filter"] + 0.008))
            profile["xg_weight"] = min(0.08, max(0.03, profile["xg_weight"] + 0.002))
            profile["shots_weight"] = min(0.05, max(0.01, profile["shots_weight"] + 0.001))
            recommended_overrides["min_single_edge"] = min(0.11, max(0.04, min_single_edge + 0.003))
            recommended_overrides["fractional_kelly_factor"] = min(0.26, max(0.08, fractional_kelly + 0.004))
        elif weakness == "stake_sizing":
            profile["stake_boost"] = min(0.04, max(0.01, profile["stake_boost"] + 0.004))
            profile["edge_buffer"] = min(0.07, max(0.02, profile["edge_buffer"] + 0.002))
            profile["odds_weight"] = min(0.04, max(0.01, profile["odds_weight"] + 0.002))
            recommended_overrides["fractional_kelly_factor"] = min(0.28, max(0.1, fractional_kelly + 0.006))
            recommended_overrides["max_stake_per_bet"] = min(0.06, max(0.01, max_stake_per_bet + 0.002))
        else:
            profile["draw_boost"] = min(0.05, max(-0.03, profile["draw_boost"] + 0.003))
            profile["home_boost"] = min(0.06, max(0.01, profile["home_boost"] + 0.002))
            profile["away_boost"] = min(0.06, max(0.01, profile["away_boost"] + 0.002))
            profile["form_weight"] = min(0.04, max(0.01, profile["form_weight"] + 0.002))
            profile["corners_weight"] = min(0.03, max(0.01, profile["corners_weight"] + 0.001))
            recommended_overrides["min_data_quality_for_market_expansion"] = min(0.75, max(0.55, min_data_quality_for_market_expansion + 0.004))
            recommended_overrides["public_hype_penalty_factor"] = min(0.1, max(0.04, public_hype_penalty_factor + 0.003))

        if report.get("win_rate", 0.0) >= 0.35 and report.get("roi", 0.0) > 0.05:
            profile["edge_buffer"] = max(0.02, profile["edge_buffer"] - 0.002)
            profile["stake_boost"] = min(0.04, profile["stake_boost"] + 0.001)
            recommended_overrides["fractional_kelly_factor"] = min(0.28, max(0.08, fractional_kelly + 0.002))
        elif report.get("win_rate", 0.0) < 0.25:
            profile["edge_buffer"] = min(0.1, profile["edge_buffer"] + 0.003)
            profile["confidence_boost"] = min(0.13, profile["confidence_boost"] + 0.002)
            profile["cards_weight"] = min(0.03, max(0.01, profile["cards_weight"] + 0.001))
            recommended_overrides["max_stake_per_bet"] = max(0.01, max_stake_per_bet - 0.001)

        self.state.set("self_repair_recommended_overrides", recommended_overrides)

# ======================================================================
# AI SIMULATION SANDBOX
# ======================================================================
class AISimulationSandbox:
    def __init__(self, state_manager):
        self.sm = state_manager
        self.surrogate = state_manager.get("surrogate_model", None)
        if not isinstance(self.surrogate, SurrogateModel):
            self.surrogate = SurrogateModel(model=None)
            try:
                self.sm.set("surrogate_model_ready", True)
            except Exception:
                pass
        self.bias_detector = BiasDetector()

    async def run_monte_carlo_epoch(self, matches_data: List[Dict[str, Any]], scenarios: int = 5000) -> Dict[str, Any]:
        log.info(f"Initiating AI Simulation across {scenarios} vectors.")
        bankroll = self.sm.get("bankroll", 1000.0)
        returns = []
        drawdowns = []

        n_surrogate = int(scenarios * CONFIG.hybrid_surrogate_fraction)
        n_tail = scenarios - n_surrogate

        surrogate_returns = []
        for _ in range(n_surrogate):
            profit = 0.0
            for match in matches_data:
                features = {
                    "home_xg": match.get("home_xg", 1.2),
                    "away_xg": match.get("away_xg", 1.0),
                    "regime_volatility": match.get("regime_volatility", 0.05)
                }
                if self.surrogate:
                    probs = await self.surrogate.predict_probs(features)
                else:
                    h = match.get("home_xg", 1.2)
                    a = match.get("away_xg", 1.0)
                    probs = Calculator.match_probs(h, a).sum(axis=0)
                    probs = probs / (probs.sum() + 1e-9)

                outcomes = ["home", "draw", "away"]
                for idx, outcome in enumerate(outcomes):
                    prob = probs[idx]
                    odds = match.get(f"odds_{outcome}", 2.9)
                    edge = prob * odds - 1.0
                    if edge > CONFIG.min_single_edge:
                        frac = (edge / (odds - 1.0)) * CONFIG.fractional_kelly_factor
                        frac = min(frac, CONFIG.max_stake_per_bet)
                        stake = bankroll * frac
                        if np.random.random() < prob:
                            profit += stake * (odds - 1.0)
                        else:
                            profit -= stake
            surrogate_returns.append(profit)

        tail_returns = []
        tail_weights = []
        for _ in range(n_tail):
            profit = 0.0
            weights = []
            for match in matches_data:
                l1 = match.get("home_xg", 1.2)
                l2 = match.get("away_xg", 1.0)
                if CONFIG.enable_advanced_math:
                    hg, ag, w = ImportanceSampler.sample_goals(l1, l2, CONFIG.importance_bias_factor)
                    weights.append(w)
                    if hg > ag:
                        outcome = "home"
                    elif hg == ag:
                        outcome = "draw"
                    else:
                        outcome = "away"
                    prob = match.get(f"prob_{outcome}", 0.34)
                    odds = match.get(f"odds_{outcome}", 2.9)
                    edge = prob * odds - 1.0
                    if edge > CONFIG.min_single_edge:
                        frac = (edge / (odds - 1.0)) * CONFIG.fractional_kelly_factor
                        frac = min(frac, CONFIG.max_stake_per_bet)
                        stake = bankroll * frac
                        if np.random.random() < prob:
                            profit += stake * (odds - 1.0)
                        else:
                            profit -= stake
            tail_returns.append(profit * np.mean(weights) if weights else profit)
            tail_weights.append(np.mean(weights) if weights else 1.0)

        all_returns = surrogate_returns + tail_returns
        if tail_weights:
            all_weights = [1.0] * len(surrogate_returns) + tail_weights
            weighted_mean = np.average(all_returns, weights=all_weights)
        else:
            weighted_mean = np.mean(all_returns)

        ret_arr = np.array(all_returns)
        ess = TailGuard.effective_sample_size(all_weights) if len(all_weights) > 1 else len(all_returns)

        return {
            "timestamp": time.time(),
            "mean_simulated_profit": float(weighted_mean),
            "value_at_risk_95": float(np.percentile(ret_arr, 5)),
            "max_simulated_drawdown": float(np.max(drawdowns)) if drawdowns else 0.0,
            "expected_sharpe_ratio": float(np.mean(ret_arr) / (np.std(ret_arr) + 1e-9)),
            "effective_sample_size": float(ess),
            "simulation_status": "SUCCESS"
        }

    async def diagnostic_report_hook(self) -> str:
        hist = self.sm.get("daily_returns", [])
        if not hist:
            return "No historical returns available."

        mean_r = np.mean(hist)
        std_r = np.std(hist) if np.std(hist) > 0 else 1.0
        neg = [x for x in hist if x < 0]
        sortino = mean_r / (np.std(neg) if neg and np.std(neg) > 0 else std_r)
        bias_report = self.bias_detector.get_bias_report()

        return (
            "==================================================\n"
            "        AI MODEL ENGINE SIMULATION RUNTIME        \n"
            "==================================================\n"
            f" Current Regime    : {self.sm.get('regime', 'normal')}\n"
            f" Horizon Size      : {len(hist)} frames\n"
            f" Sortino Ratio     : {sortino:.4f}\n"
            f" VaR (95%)         : {mean_r - 1.645 * std_r:.4f}\n"
            f" Active Biases     : {len(bias_report)}\n"
            "==================================================\n"
            f" Bias Report       : {json.dumps(bias_report, indent=2)[:500]}"
        )


class SimulationStateProxy:
    """Minimal state adapter for simulation-only workflows."""
    def __init__(self, seed: Optional[Dict[str, Any]] = None):
        self._cache = dict(seed or {})

    def get(self, key: str, default: Any = None) -> Any:
        return self._cache.get(key, default)

    def set(self, key: str, value: Any) -> None:
        self._cache[key] = value

    async def save(self, key: str, value: Any) -> None:
        self._cache[key] = value

    async def flush(self) -> None:
        return None


def _to_float(data: Dict[str, Any], key: str, default: float) -> float:
    try:
        value = float(data.get(key, default))
    except Exception:
        value = default
    if not math.isfinite(value):
        return default
    return value


def _to_int(data: Dict[str, Any], key: str, default: int, min_value: int, max_value: int) -> int:
    try:
        value = int(data.get(key, default))
    except Exception:
        value = default
    return max(min_value, min(max_value, value))


async def execute_simulation_scenario(request_data: Dict[str, Any], state_manager: Optional[Any] = None) -> Dict[str, Any]:
    """Execute an exact scenario through the production math and simulation engines."""
    try:
        payload = request_data or {}
        home_xg = _to_float(payload, "home_xg", 1.2)
        away_xg = _to_float(payload, "away_xg", 1.0)
        home_form = _to_float(payload, "form_home", 0.5)
        away_form = _to_float(payload, "form_away", 0.5)
        bankroll = _to_float(payload, "bankroll", 1000.0)
        simulations = _to_int(payload, "simulations", 1000, 10, 50000)
        odds_home = _to_float(payload, "odds_home", 2.0)
        odds_draw = _to_float(payload, "odds_draw", 3.2)
        odds_away = _to_float(payload, "odds_away", 3.4)

        if bankroll <= 0:
            return {"status": "error", "message": "bankroll must be greater than 0"}
        if home_xg < 0 or away_xg < 0 or home_xg > 8 or away_xg > 8:
            return {"status": "error", "message": "home_xg/away_xg must be in [0, 8]"}
        if not (1.01 <= odds_home <= 100 and 1.01 <= odds_draw <= 100 and 1.01 <= odds_away <= 100):
            return {"status": "error", "message": "odds must be within [1.01, 100]"}

        sim_state = state_manager or SimulationStateProxy({"bankroll": bankroll})
        scenario_row = {
            "home_xg": home_xg,
            "away_xg": away_xg,
            "form_home": home_form,
            "form_away": away_form,
            "odds_home": odds_home,
            "odds_draw": odds_draw,
            "odds_away": odds_away,
            "market_depth": payload.get("market_depth", 150.0),
            "proposed_stake": payload.get("proposed_stake", bankroll * 0.01),
            "latency_ms": payload.get("latency_ms", 0.0),
            "best_bid": payload.get("best_bid", odds_home),
            "best_ask": payload.get("best_ask", odds_home),
            "best_bid_volume": payload.get("best_bid_volume", 100.0),
            "best_ask_volume": payload.get("best_ask_volume", 100.0),
            "history_form_home": payload.get("history_form_home", [home_form]),
            "history_form_away": payload.get("history_form_away", [away_form]),
            "history_home_xg": payload.get("history_home_xg", [home_xg]),
            "history_away_xg": payload.get("history_away_xg", [away_xg]),
            "history_total_goals": payload.get("history_total_goals", [home_xg + away_xg]),
            "history_goal_diff": payload.get("history_goal_diff", [home_xg - away_xg]),
            "history_odds_home": payload.get("history_odds_home", [odds_home]),
            "history_returns": payload.get("history_returns", []),
        }
        upgrade_features = await FeatureEngine.build_features(scenario_row, sim_state)

        adj_home_xg = home_xg * (0.9 + 0.2 * max(0.0, min(1.0, upgrade_features.get("adaptive_form_home", home_form))))
        adj_away_xg = away_xg * (0.9 + 0.2 * max(0.0, min(1.0, upgrade_features.get("adaptive_form_away", away_form))))
        if upgrade_features.get("open_regime_flag", 0.0) > 0.5:
            adj_home_xg *= 1.1
            adj_away_xg *= 1.1

        match_row_for_probs = {
            "league_volatility": upgrade_features.get("regime_volatility", 0.5),
            "copula_cov_factor": upgrade_features.get("copula_cov_factor_dynamic", CONFIG.bivariate_cov_factor),
            "form_age_days_home": payload.get("form_age_days_home", 7),
            "days_since_last_home": payload.get("days_since_last_home", 7),
        }
        joint = Calculator.match_probs(adj_home_xg, adj_away_xg, match_row=match_row_for_probs)
        if joint is None:
            return {"status": "error", "message": "match_probs returned no data"}

        p_home = 0.0
        p_draw = 0.0
        p_away = 0.0
        rows, cols = joint.shape
        for away_goals in range(rows):
            for home_goals in range(cols):
                prob = float(joint[away_goals, home_goals])
                if home_goals > away_goals:
                    p_home += prob
                elif home_goals == away_goals:
                    p_draw += prob
                else:
                    p_away += prob

        total = p_home + p_draw + p_away
        if total > 0:
            p_home /= total
            p_draw /= total
            p_away /= total

        sandbox = AISimulationSandbox(sim_state)

        scenario_match = {
            "home_xg": adj_home_xg,
            "away_xg": adj_away_xg,
            "form_home": home_form,
            "form_away": away_form,
            "prob_home": p_home,
            "prob_draw": p_draw,
            "prob_away": p_away,
            "odds_home": odds_home,
            "odds_draw": odds_draw,
            "odds_away": odds_away,
        }
        simulation_timeout = max(5.0, min(90.0, float(payload.get("simulation_timeout_seconds", 25.0) or 25.0)))
        simulation_metrics = await asyncio.wait_for(
            sandbox.run_monte_carlo_epoch([scenario_match], scenarios=simulations),
            timeout=simulation_timeout,
        )

        return {
            "status": "ok",
            "inputs": {
                "home_xg": home_xg,
                "away_xg": away_xg,
                "adjusted_home_xg": float(adj_home_xg),
                "adjusted_away_xg": float(adj_away_xg),
                "form_home": home_form,
                "form_away": away_form,
                "bankroll": bankroll,
                "simulations": simulations,
                "odds_home": odds_home,
                "odds_draw": odds_draw,
                "odds_away": odds_away,
            },
            "probabilities": {
                "home": float(p_home),
                "draw": float(p_draw),
                "away": float(p_away),
            },
            "simulation_metrics": simulation_metrics,
            "kelly": {
                "home": float(Calculator.kelly_fraction(p_home, odds_home)),
                "draw": float(Calculator.kelly_fraction(p_draw, odds_draw)),
                "away": float(Calculator.kelly_fraction(p_away, odds_away)),
            },
            "upgrade_signals": {
                "open_regime_flag": float(upgrade_features.get("open_regime_flag", 0.0)),
                "copula_cov_factor_dynamic": float(upgrade_features.get("copula_cov_factor_dynamic", CONFIG.bivariate_cov_factor)),
                "anomaly_mahalanobis_flag": float(upgrade_features.get("anomaly_mahalanobis_flag", 0.0)),
                "predicted_slippage": float(upgrade_features.get("predicted_slippage", 0.0)),
                "latency_stale_flag": float(upgrade_features.get("latency_stale_flag", 0.0)),
                "cornish_fisher_var_95": float(upgrade_features.get("cornish_fisher_var_95", 0.0)),
                "kelly_conservative_home": float(upgrade_features.get("kelly_conservative_home", 0.0)),
            },
        }
    except Exception as exc:
        log.exception("Simulation scenario execution failed", error=str(exc))
        return {"status": "error", "message": str(exc)}

