# ======================================================================
def execute_walk_forward_backtest(dataframe: DataFrameType, window_months: int = 3, tuning_overrides: Optional[Dict[str, Any]] = None):
    if dataframe is None or dataframe.empty:
        return []
    df = dataframe.copy()
    if "match_timestamp" in df.columns:
        df["match_timestamp"] = pd.to_datetime(df["match_timestamp"], errors="coerce")
        df = df.dropna(subset=["match_timestamp"]).sort_values(by="match_timestamp").reset_index(drop=True)
    elif "match_date" in df.columns:
        df["match_timestamp"] = pd.to_datetime(df["match_date"], errors="coerce")
        df = df.dropna(subset=["match_timestamp"]).sort_values(by="match_timestamp").reset_index(drop=True)
    else:
        return []

    if df.empty:
        return []

    unique_dates = sorted(pd.Series(df["match_timestamp"].dt.date).unique())
    results = []
    tuning_overrides = tuning_overrides or {}
    override_cov = float(tuning_overrides.get("bivariate_cov_factor", CONFIG.bivariate_cov_factor) or CONFIG.bivariate_cov_factor)
    for i in range(window_months, len(unique_dates)):
        train_cutoff = unique_dates[i - window_months]
        test_date = unique_dates[i]
        train_set = df[df["match_timestamp"].dt.date < train_cutoff]
        test_set = df[df["match_timestamp"].dt.date == test_date]
        if train_set.empty or test_set.empty:
            continue

        correct = 0
        total = 0
        log_loss_total = 0.0
        brier_total = 0.0
        for _, row in test_set.iterrows():
            home_xg = float(row.get("home_xg", 1.2) or 1.2)
            away_xg = float(row.get("away_xg", 1.0) or 1.0)
            joint = Calculator.match_probs(home_xg, away_xg, match_row={"copula_cov_factor": override_cov})
            p_home = float(np.sum(joint[np.tril_indices_from(joint, k=-1)]))
            p_draw = float(np.sum(np.diag(joint)))
            p_away = max(0.0, 1.0 - p_home - p_draw)
            probs = {"home": p_home, "draw": p_draw, "away": p_away}
            predicted = max(probs, key=probs.get)
            actual = "home" if float(row.get("home_goals", 0)) > float(row.get("away_goals", 0)) else "away" if float(row.get("away_goals", 0)) > float(row.get("home_goals", 0)) else "draw"
            outcomes = ["home", "draw", "away"]
            y_true = np.eye(3)[outcomes.index(actual)]
            y_prob = np.array([probs[o] for o in outcomes], dtype=float)
            y_prob = y_prob / (y_prob.sum() + 1e-9)
            log_loss_total += -np.log(max(y_prob[outcomes.index(actual)], 1e-9))
            brier_total += np.sum((y_true - y_prob) ** 2)
            total += 1
            correct += int(predicted == actual)

        results.append({
            "train_size": len(train_set),
            "test_size": len(test_set),
            "test_date": str(test_date),
            "accuracy": correct / max(1, total),
            "avg_log_loss": log_loss_total / max(1, total),
            "avg_brier_score": brier_total / max(1, total),
            "calendar_window": f"{train_cutoff} -> {test_date}",
        })
    return results

class HyperTuner:
    def __init__(self, state, db_pool):
        self.state = state
        self.db = db_pool

    async def tune(self, historical_data):
        if optuna is None:
            log.warning("Optuna not installed; skipping tuning.")
            return

        df = historical_data if HAS_PANDAS and historical_data is not None else None
        if df is None or getattr(df, "empty", True):
            log.warning("HyperTuner skipped: historical_data missing or empty.")
            return

        def objective(trial):
            min_single_edge = trial.suggest_float("min_single_edge", 0.01, 0.10)
            fraction_kelly = trial.suggest_float("fractional_kelly_factor", 0.1, 0.5)
            swan_threshold = trial.suggest_float("swan_threshold", 0.05, 0.20)
            bivariate_cov = trial.suggest_float("bivariate_cov_factor", 0.05, 0.5)
            max_depth = trial.suggest_int("max_depth", 3, 10)
            learning_rate = trial.suggest_float("learning_rate", 0.01, 0.2)
            subsample = trial.suggest_float("subsample", 0.6, 1.0)
            sample = df.tail(min(2000, len(df)))
            wf = execute_walk_forward_backtest(
                sample,
                window_months=3,
                tuning_overrides={
                    "bivariate_cov_factor": bivariate_cov,
                    "min_single_edge": min_single_edge,
                    "fractional_kelly_factor": fraction_kelly,
                    "swan_threshold": swan_threshold,
                    "max_depth": max_depth,
                    "learning_rate": learning_rate,
                    "subsample": subsample,
                },
            )
            if not wf:
                return 1.0
            acc = float(np.mean([row.get("accuracy", 0.0) for row in wf]))
            ll = float(np.mean([row.get("avg_log_loss", 1.5) for row in wf]))
            brier = float(np.mean([row.get("avg_brier_score", 1.0) for row in wf]))
            aggressiveness_penalty = max(0.0, min_single_edge - 0.06) * 0.4 + max(0.0, fraction_kelly - 0.3) * 0.3
            instability_penalty = max(0.0, bivariate_cov - 0.3) * 0.2 + max(0.0, 0.75 - subsample) * 0.1
            # Minimize loss while rewarding predictive accuracy, without mutating live config during search.
            return (0.7 * ll + 0.3 * brier) - (0.4 * acc) + aggressiveness_penalty + instability_penalty

        study = optuna.create_study(direction="minimize")
        study.optimize(objective, n_trials=CONFIG.tuning_trials)

        best = study.best_params
        log.info(f"Tuning finished. Parameters: {best}")
        # Store tuned params in state, not on CONFIG directly
        await self.state.save("tuned_params", best)

