class X:
    def __init__(self, state=None, dept=None):
        self.state = state
        self.dept = dept
        self.tactic_names = self._build_names()
        self.tactics = {}
        for name in self.tactic_names:
            self.tactics[name] = self._make_tactic(name)
        self.categories = self._assign_categories()
        self._active = set(self.tactic_names)

    def _build_names(self):
        return [
            "home_form_advantage", "away_form_advantage", "xg_differential", "shot_differential",
            "corner_differential", "card_differential", "possession_dominance", "pressing_intensity",
            "defensive_solidity", "attacking_potential", "h2h_momentum", "injury_sensitivity",
            "lineup_strength_impact", "fatigue_factor", "weather_effect", "referee_bias",
            "travel_strain", "congestion_penalty", "derby_intensity", "relegation_battle",
            "international_break_effect", "transfer_window_distraction", "media_sentiment",
            "public_money_flow", "sharp_money_flow", "bookmaker_margin_adjust", "regime_volatility"
        ]

    def _make_tactic(self, name: str) -> Callable:
        def tactic(features: Dict[str, float]) -> Dict[str, Any]:
            if "home_form_advantage" in name:
                value = features.get('form_home', 0.5) - features.get('form_away', 0.5) + 0.1
            elif "xg_differential" in name:
                value = features.get('home_xg', 1.2) - features.get('away_xg', 1.0)
            elif "shot_differential" in name:
                value = features.get('home_shots', 10) - features.get('away_shots', 8)
            elif "possession_dominance" in name:
                value = features.get('possession_home', 0.5) - features.get('possession_away', 0.5)
            elif "pressing_intensity" in name:
                value = (features.get('home_shots', 10) + features.get('away_shots', 8)) / 18
            elif "defensive_solidity" in name:
                value = 1 - features.get('away_xg', 1.0) / 2.0
            elif "attacking_potential" in name:
                value = features.get('home_xg', 1.2) / 1.5
            elif "injury_sensitivity" in name:
                value = features.get('injury_impact_home', 0) + features.get('injury_impact_away', 0)
            elif "fatigue_factor" in name:
                value = features.get('congestion_home', 0.4) + features.get('congestion_away', 0.4)
            elif "weather_effect" in name:
                value = (features.get('weather_temp', 15) - 15) / 15 * 0.1 + features.get('weather_rain', 0) * 0.05
            elif "regime_volatility" in name:
                value = features.get('regime_volatility', 0.05)
            else:
                value = 0.0
            return {
                "tactic": name,
                "value": float(np.clip(value, -1.0, 1.0)),
                "description": f"Tactical feature: {name}",
                "params": features
            }
        return tactic

    def _assign_categories(self) -> Dict[str, str]:
        categories = {}
        for name in self.tactic_names:
            if "form" in name: cat = "Form"
            elif "xg" in name or "shot" in name: cat = "Performance"
            elif "possession" in name: cat = "Possession"
            elif "injury" in name: cat = "Injury"
            elif "fatigue" in name or "congestion" in name: cat = "Fatigue"
            elif "weather" in name: cat = "Weather"
            elif "regime" in name: cat = "Regime"
            else: cat = "General"
            categories[name] = cat
        return categories

    def get_tactic(self, name: str) -> Optional[Callable]:
        return self.tactics.get(name)

    def list_tactics(self, category: str = None, limit: int = 20) -> List[str]:
        if category:
            return [n for n, c in self.categories.items() if c == category][:limit]
        return list(self._active)[:limit]

    def register_with_engine(self, engine: 'UnifiedMathEngine'):
        if hasattr(engine, '_METHOD_WEIGHTS'):
            sorted_names = sorted(self.tactics.keys(),
                                  key=lambda n: engine._METHOD_WEIGHTS.get(n, 0.0), reverse=True)
            active = set(sorted_names[:CONFIG.active_tactics_limit])
        else:
            active = set(self.tactics.keys())
        self._active = active
        for name, func in self.tactics.items():
            if name in self._active:
                engine._all_methods[name] = func
                engine._method_tags[name] = "tactical"
                engine._METHOD_PURPOSE[name] = "prediction"
                if name not in engine._METHOD_WEIGHTS:
                    engine._METHOD_WEIGHTS[name] = 0.5
        log.info(f"Registered {len(self._active)} active tactics to UnifiedMathEngine.")

