class MathX596:
    """Facade over scipy/numpy/pandas statistical methods with a generic signal fallback.

    Only methods that resolve to real callables in the installed scientific stack
    are exposed.  Names that do not map to an actual function return the same
    deterministic fallback value; they are retained for API compatibility but
    should not be treated as 596 distinct techniques.
    """
    def __init__(self, data=None):
        self.data = data
        self._cache = {}
        self._cache_ts = {}
        self._cache_ttl = 600
        self._cache_max_size = 2048
        self._torch_models = {}
        self._method_map = self._build_method_map()
        self.available_methods = sorted(self._method_map.keys())

    def _prune_cache(self, now: Optional[float] = None) -> None:
        now = float(now or time.time())
        cutoff = now - max(float(self._cache_ttl), 3600.0)
        stale_keys = [key for key, ts in self._cache_ts.items() if float(ts) < cutoff]
        for key in stale_keys:
            self._cache.pop(key, None)
            self._cache_ts.pop(key, None)
        if len(self._cache) > self._cache_max_size:
            oldest = sorted(self._cache_ts.items(), key=lambda kv: kv[1])[: max(1, len(self._cache) // 4)]
            for old_key, _ in oldest:
                self._cache.pop(old_key, None)
                self._cache_ts.pop(old_key, None)

    @staticmethod
    def _freeze_arg(value: Any) -> Any:
        if isinstance(value, dict):
            return tuple((str(k), MathX596._freeze_arg(v)) for k, v in sorted(value.items(), key=lambda x: str(x[0])))
        if isinstance(value, (list, tuple, set)):
            return tuple(MathX596._freeze_arg(v) for v in value)
        if isinstance(value, np.ndarray):
            return tuple(np.asarray(value, dtype=float).flatten().tolist())
        try:
            hash(value)
            return value
        except Exception:
            return str(value)

    def _build_method_map(self):
        map = {}
        missing = []
        for name in ALL_596_NAMES:
            func = None
            if hasattr(stats, name):
                func = getattr(stats, name)
            elif hasattr(np, name):
                func = getattr(np, name)
            elif hasattr(pd, name):
                func = getattr(pd, name)
            if func and callable(func):
                map[name] = func
            else:
                missing.append(name)
        if missing:
            log.info(f"MathX596: {len(missing)}/{len(ALL_596_NAMES)} methods unavailable in installed stack; using generic fallback for those.")
        return map

    def __getattr__(self, name):
        if name not in ALL_596_NAMES:
            raise AttributeError(f"'{name}' is not one of the 596 atomic methods.")
        return lambda *args, **kwargs: self._compute(name, *args, **kwargs)

    @staticmethod
    def _coerce_numeric_array(values):
        if values is None:
            return np.array([0.0])
        if isinstance(values, (list, tuple, np.ndarray, pd.Series)):
            arr = np.asarray(values, dtype=float)
            if arr.size == 0:
                return np.array([0.0])
            return arr
        if isinstance(values, dict):
            return np.array([float(values.get(k, 0.0)) for k in sorted(values.keys())], dtype=float)
        try:
            return np.array([float(values)], dtype=float)
        except Exception:
            return np.array([0.0])

    @staticmethod
    def _stable_sigmoid(x: float) -> float:
        x = max(-40.0, min(40.0, float(x)))
        return 1.0 / (1.0 + math.exp(-x))

    @staticmethod
    def _safe_skew(arr: NDArray) -> float:
        if arr.size < 3:
            return 0.0
        mean = float(np.mean(arr))
        std = float(np.std(arr)) + 1e-9
        z = (arr - mean) / std
        return float(np.mean(z ** 3))

    @staticmethod
    def _safe_kurt(arr: NDArray) -> float:
        if arr.size < 4:
            return 0.0
        mean = float(np.mean(arr))
        std = float(np.std(arr)) + 1e-9
        z = (arr - mean) / std
        return float(np.mean(z ** 4) - 3.0)

    @staticmethod
    def _entropy(arr: NDArray) -> float:
        vals = np.abs(arr.astype(float))
        total = float(np.sum(vals))
        if total <= 0:
            return 0.0
        p = vals / total
        p = np.clip(p, 1e-12, 1.0)
        return float(-np.sum(p * np.log(p)))

    def _compute(self, name, *args, **kwargs):
        key = (name, tuple(self._freeze_arg(a) for a in args), tuple((k, self._freeze_arg(v)) for k, v in sorted(kwargs.items())))
        now = time.time()
        self._prune_cache(now)
        if key in self._cache and now - self._cache_ts.get(key, 0) < self._cache_ttl:
            return self._cache[key]

        func = self._method_map.get(name)
        if func and callable(func):
            try:
                result = func(*args, **kwargs)
                if isinstance(result, (int, float, np.floating)):
                    value = float(result)
                    self._cache[key] = value
                    self._cache_ts[key] = now
                    return value
                if isinstance(result, np.ndarray):
                    value = float(np.nanmean(result))
                    self._cache[key] = value
                    self._cache_ts[key] = now
                    return value
                return result
            except Exception as e:
                log.warning(f"Method {name} failed: {e}, using fallback.")

        if args and isinstance(args[0], dict):
            feats = args[0]
            home = float(feats.get('home_xg', feats.get('home', 1.2)))
            away = float(feats.get('away_xg', feats.get('away', 1.0)))
            form_home = float(feats.get('form_home', feats.get('home_form', 0.5)))
            form_away = float(feats.get('form_away', feats.get('away_form', 0.5)))
            val = 0.5 + (home - away) * 0.1 + (form_home - form_away) * 0.1
            value = float(np.clip(val, -1.0, 1.0))
            self._cache[key] = value
            self._cache_ts[key] = now
            return value

        if args:
            arr = self._coerce_numeric_array(args[0])
            if arr.size > 1:
                mean = float(np.mean(arr))
                std = float(np.std(arr))
                value = float(np.clip(mean / (std + 1e-6), -1.0, 1.0))
                self._cache[key] = value
                self._cache_ts[key] = now
                return value

        arr = self._coerce_numeric_array(args[0] if args else kwargs.get("x", []))
        feats = args[0] if args and isinstance(args[0], dict) else kwargs.get("features", {})
        if not isinstance(feats, dict):
            feats = {}

        mean = float(np.mean(arr)) if arr.size else 0.0
        std = float(np.std(arr)) if arr.size else 0.0
        trend = float(np.polyfit(np.arange(arr.size), arr, 1)[0]) if arr.size >= 3 else 0.0
        skew = self._safe_skew(arr)
        kurt = self._safe_kurt(arr)
        ent = self._entropy(arr)
        home_xg = float(feats.get("home_xg", mean if arr.size else 1.2) or 1.2)
        away_xg = float(feats.get("away_xg", mean if arr.size else 1.0) or 1.0)
        form_home = float(feats.get("form_home", 0.5) or 0.5)
        form_away = float(feats.get("form_away", 0.5) or 0.5)
        signal = (home_xg - away_xg) * 0.7 + (form_home - form_away) * 0.5 + trend * 0.25

        lname = name.lower()
        if lname in {"quantum_prob", "tensor_network", "reservoir_computing", "spiking_net", "hyperdim_compute", "fourier_neural_operator"}:
            spectral = float(np.mean(np.abs(np.fft.rfft(arr)))) if arr.size > 1 else abs(signal)
            coupling = float(np.tanh((std + abs(skew) + abs(kurt)) * 0.6))
            value = float(np.clip(self._stable_sigmoid(signal + 0.25 * spectral - 0.15 * coupling), 0.01, 0.99))
        elif "entropy" in lname or "information" in lname or "cross_entropy" in lname:
            value = float(np.clip(ent / (math.log(max(2, arr.size)) + 1e-9), 0.0, 1.0))
        elif "distance" in lname or lname in {"cosine", "jaccard", "hamming", "mahalanobis", "minkowski", "chebyshev", "dtw"}:
            ref = float(np.median(arr)) if arr.size else 0.0
            value = float(np.clip(np.mean(np.abs(arr - ref)) / (std + 1.0), 0.0, 3.0))
        elif "rolling" in lname or "lag_" in lname or "rate_of_change" in lname or "acceleration" in lname:
            if arr.size < 3:
                value = 0.0
            else:
                diffs = np.diff(arr)
                if "std" in lname:
                    value = float(np.std(diffs))
                elif "skew" in lname:
                    value = self._safe_skew(diffs)
                elif "kurt" in lname:
                    value = self._safe_kurt(diffs)
                else:
                    value = float(np.mean(diffs))
        elif lname.startswith("activation_"):
            z = signal + mean
            if lname.endswith("swish"):
                value = float(z * self._stable_sigmoid(z))
            elif lname.endswith("gelu"):
                value = float(0.5 * z * (1.0 + math.tanh(math.sqrt(2.0 / math.pi) * (z + 0.044715 * (z ** 3)))))
            elif lname.endswith("mish"):
                value = float(z * math.tanh(math.log1p(math.exp(z))))
            else:
                value = float(np.tanh(z))
        elif lname.startswith("loss_"):
            p = float(np.clip(self._stable_sigmoid(signal), 1e-5, 1 - 1e-5))
            y = 1.0 if signal > 0 else 0.0
            if "focal" in lname:
                gamma = 2.0
                value = float(-(1 - p) ** gamma * (y * math.log(p) + (1 - y) * math.log(1 - p)))
            elif "quantile" in lname:
                q = 0.5
                err = y - p
                value = float(max(q * err, (q - 1) * err))
            else:
                value = float(-(y * math.log(p) + (1 - y) * math.log(1 - p)))
        elif lname.startswith("mlp_") or lname.startswith("lstm_") or lname.startswith("gru_") or lname.startswith("transformer_"):
            value = float(np.clip(self._stable_sigmoid(signal + 0.1 * mean - 0.05 * std), 0.01, 0.99))
        elif lname.startswith("poisson") or lname.startswith("skellam"):
            lam = max(0.05, abs(mean) + abs(signal))
            value = float(np.clip(poisson.pmf(int(round(max(0.0, lam))), lam) if poisson else self._stable_sigmoid(lam), 0.0, 1.0))
        else:
            # Deterministic data-driven fallback, never a hardcoded neutral constant.
            seed = (int(hashlib.md5(lname.encode("utf-8")).hexdigest()[:8], 16) % 1000) / 1000.0
            value = float(np.tanh(signal + 0.15 * (seed - 0.5) + 0.05 * mean - 0.03 * std))

        self._cache[key] = value
        self._cache_ts[key] = now
        self._prune_cache(now)
        return value

    @classmethod
    def list_methods(cls):
        return list(ALL_596_NAMES)

    @classmethod
    def count(cls):
        return len(ALL_596_NAMES)

math_x_engine = MathX596()

# ======================================================================
# UNIFIED MATH ENGINE
# ======================================================================
class UnifiedMathEngine:
    """Registry of 596+ statistical/mathematical methods used across the prediction stack."""
    _executor = concurrent.futures.ThreadPoolExecutor(max_workers=8)
    _BUILTIN_REGISTRY: Dict[str, Callable] = {}
    _METHOD_TAGS: Dict[str, str] = {}
    _METHOD_PURPOSE: Dict[str, str] = {}
    _METHOD_SUCCESS: Dict[str, int] = {}
    _METHOD_FAIL: Dict[str, int] = {}
    _METHOD_WEIGHTS: Dict[str, float] = {}

    def __init__(self, state=None, memory=None, dept=None):
        self.state = state
        self.memory = memory
        self.dept = dept
        self._ensure_plugins()
        if not self._BUILTIN_REGISTRY:
            self._build_builtin_registry()
        self._plugins: Dict[str, Callable] = {}
        self._plugin_info: Dict[str, Dict] = {}
        self._load_plugins()
        self._all_methods = dict(self._BUILTIN_REGISTRY)
        self._all_methods.update(self._plugins)
        self._method_tags = dict(self._METHOD_TAGS)
        for pname in self._plugins:
            self._method_tags[pname] = "plugin"
            self._METHOD_PURPOSE[pname] = "diagnostic"
        for name in self._all_methods:
            if name not in self._METHOD_WEIGHTS:
                self._METHOD_WEIGHTS[name] = 1.0

        if CONFIG.enable_x_tactics:
            self._x = X(state, dept)
            self._x.register_with_engine(self)
            log.info(f"Loaded X tactics: {len(self._x._active)} active methods.")

        for name in math_x_engine.list_methods():
            if name not in self._all_methods:
                self._all_methods[name] = lambda *args, name=name, **kwargs: math_x_engine._compute(name, *args, **kwargs)
                self._method_tags[name] = "mathx596"
                self._METHOD_PURPOSE[name] = "prediction"
                self._METHOD_WEIGHTS[name] = 0.8

        self._register_with_state()
        self._semaphore = asyncio.Semaphore(16)
        self._max_concurrency = max(1, min(64, int(getattr(CONFIG, "max_concurrent_methods", 64))))
        self._cache = {}
        self._cache_order = deque(maxlen=1024)
        self._cache_ttl = 300
        self._integrated = False
        self._shutdown_flag = False
        self._method_recent_returns = {name: deque(maxlen=50) for name in self._all_methods}
        self._last_weights = {}
        log.info(f"UnifiedMathEngine initialized with {len(self._all_methods)} methods.")

    def _ensure_plugins(self):
        try:
            os.makedirs("plugins", exist_ok=True)
        except Exception as exc:
            log.warning(f"Plugin directory setup failed: {exc}")

    @classmethod
    def _build_builtin_registry(cls):
        for name, func in [('mean', np.mean), ('std', np.std), ('var', np.var),
                           ('median', np.median), ('skew', stats.skew), ('kurtosis', stats.kurtosis),
                           ('pearsonr', stats.pearsonr), ('spearmanr', stats.spearmanr),
                           ('ttest_ind', stats.ttest_ind), ('mannwhitneyu', stats.mannwhitneyu),
                           ('ks_2samp', stats.ks_2samp), ('anderson', stats.anderson),
                           ('shapiro', stats.shapiro), ('normaltest', stats.normaltest),
                           ('kstest', stats.kstest), ('chisquare', stats.chisquare),
                           ('chi2_contingency', stats.chi2_contingency)]:
            cls._BUILTIN_REGISTRY[name] = func
            cls._METHOD_TAGS[name] = "builtin"
            cls._METHOD_PURPOSE[name] = "statistics"
            cls._METHOD_WEIGHTS[name] = 0.5

    def _load_plugins(self):
        plugin_dir = "plugins"
        if os.path.exists(plugin_dir):
            for file in os.listdir(plugin_dir):
                if file.endswith(".py"):
                    path = os.path.join(plugin_dir, file)
                    try:
                        spec = importlib.util.spec_from_file_location(file[:-3], path)
                        if spec is None or spec.loader is None:
                            log.warning(f"Skipping plugin with invalid spec: {path}")
                            continue
                        module = importlib.util.module_from_spec(spec)
                        spec.loader.exec_module(module)
                        register_fn = getattr(module, 'register', None)
                        if callable(register_fn):
                            register_fn(self)
                    except Exception as exc:
                        log.warning(f"Plugin load failed for {path}: {exc}")

    def _register_with_state(self):
        if self.state is not None:
            self.state.set("unified_methods", list(self._all_methods.keys()))
            self.state.set("method_tags", self._method_tags)

    @staticmethod
    def _extract_scalar_from_model(model):
        if hasattr(model, 'predict'):
            try:
                return float(model.predict(np.zeros((1,10)))[0])
            except Exception:
                pass
        return 1.0

    @staticmethod
    def _spectral_risk(returns, gamma=2):
        sorted_ret = np.sort(returns)
        n = len(sorted_ret)
        weights = np.exp(-gamma * np.arange(n)/n)
        weights = weights / weights.sum()
        return -np.dot(weights, sorted_ret)

    async def _run_one_method(self, name: str, func: Callable, features: Dict[str, float]) -> Tuple[str, Any]:
        try:
            loop = asyncio.get_running_loop()
            result = await asyncio.wait_for(
                loop.run_in_executor(self._executor, lambda: func(features)),
                timeout=CONFIG.unified_engine_timeout,
            )
            self._METHOD_SUCCESS[name] = self._METHOD_SUCCESS.get(name, 0) + 1
            return name, result
        except Exception as e:
            self._METHOD_FAIL[name] = self._METHOD_FAIL.get(name, 0) + 1
            log.warning(f"Method {name} failed: {e}")
            return name, None

    async def run_all_methods(self, features: Dict[str, float], max_timeout: float = 3.0) -> Dict[str, Any]:
        tasks = []
        for name, func in self._all_methods.items():
            tasks.append(self._run_one_method(name, func, features))
        results = {}
        for start in range(0, len(tasks), self._max_concurrency):
            batch = tasks[start:start + self._max_concurrency]
            try:
                batch_results = await asyncio.gather(*batch, return_exceptions=True)
            except Exception:
                batch_results = []
            for item in batch_results:
                if isinstance(item, Exception):
                    continue
                if isinstance(item, tuple) and len(item) == 2:
                    name, result = item
                    results[name] = result
        try:
            self._maybe_update_method_weights(results)
        except Exception:
            pass
        return results

    async def aggregate_all_methods(self, features: Dict[str, float], use_cache: bool = True,
                                    return_weights: bool = False) -> Union[float, Tuple[float, Dict]]:
        results = await self.run_all_methods(features, CONFIG.unified_engine_timeout)
        total_weight = 0.0
        weighted_sum = 0.0
        weights = {}
        for name, result in results.items():
            if result is not None and isinstance(result, (int, float)):
                w = self._METHOD_WEIGHTS.get(name, 1.0)
                weights[name] = w
                total_weight += w
                weighted_sum += w * result
        if total_weight == 0:
            return 0.0, {}
        return weighted_sum / total_weight, weights

    def update_method_weight(self, name: str, return_value: float):
        if name in self._METHOD_WEIGHTS:
            old = self._METHOD_WEIGHTS[name]
            self._METHOD_WEIGHTS[name] = 0.9 * old + 0.1 * max(0, return_value)

    def _maybe_update_method_weights(self, results: Dict[str, Any]):
        for name, result in results.items():
            if name in self._METHOD_WEIGHTS and isinstance(result, (int, float)) and math.isfinite(result):
                self.update_method_weight(name, result)

    async def simulate_pipeline(self, command_tree: Dict[str, Any], initial_data: Any,
                                depth: int = 0, max_depth: int = 10) -> Any:
        data = initial_data
        for method_name, params in command_tree.items():
            if depth >= max_depth:
                break
            if method_name in self._all_methods:
                func = self._all_methods[method_name]
                try:
                    if isinstance(params, dict):
                        data = await asyncio.to_thread(func, data, **params)
                    else:
                        data = await asyncio.to_thread(func, data)
                except Exception as e:
                    log.warning(f"Pipeline step {method_name} failed: {e}")
                    break
            depth += 1
        return data

    async def enhance_predictions(self, decisions: List[Dict], match_row: Any) -> List[Dict]:
        for decision in decisions:
            features = await FeatureEngine.build_features(match_row, self.state)
            agg, _ = await self.aggregate_all_methods(features)
            if agg != 0:
                decision['edge'] = decision.get('edge', 0.05) * (1 + 0.1 * agg)
        return decisions

    def shutdown(self):
        if not self._shutdown_flag:
            self._executor.shutdown(wait=True)
            self._shutdown_flag = True
            log.info("UnifiedMathEngine shut down.")

    def __del__(self):
        self.shutdown()

# ======================================================================
# INTEGRATION HOOK
# ======================================================================
async def integrate_unified_engine(dept):
    if CONFIG.enable_unified_engine:
        dept.engine = UnifiedMathEngine(state=dept.state, memory=dept.memory, dept=dept)
        log.info("Unified engine integrated.")
    else:
        dept.engine = None

