    @app.post("/predict/batch", response_model=None)
    async def predict_match_batch(payload: dict):
        try:
            req = BatchPredictionRequest(**(payload or {}))
            requests = req.requests or []
            if not requests:
                return {"results": []}
            integrator = ctx_holder.get('orchestrator').external_integrator if ctx_holder and ctx_holder.get('orchestrator') else ExternalModelIntegrator()
            concurrency = min(max(1, CONFIG.max_concurrent_requests), len(requests))
            semaphore = asyncio.Semaphore(concurrency)

            async def _predict_one(item):
                async with semaphore:
                    fixture_id = item.fixture_id
                    home = item.home
                    away = item.away
                    probs = await integrator.get_public_predictions(fixture_id, home, away)
                    return {
                        "fixture_id": fixture_id,
                        "home": home,
                        "away": away,
                        "probabilities": probs,
                    }

            results = await asyncio.gather(*[_predict_one(item) for item in requests], return_exceptions=True)
            return {"results": [res for res in results if not isinstance(res, Exception)]}
        except Exception as exc:
            log.warning("Batch prediction endpoint failed", exc_info=True)
            return _safe_error_payload(str(exc), status_code=500)

    @app.post("/simulate", response_model=None)
    async def simulate_scenario(payload: dict):
        try:
            active_state = ctx_holder.get("state") if ctx_holder else None
            req = SimulationRequest(**(payload or {}))
            payload_dict = req.dict(exclude_none=True)
            result = await asyncio.wait_for(
                execute_simulation_scenario(payload_dict, state_manager=active_state),
                timeout=max(5.0, min(120.0, float(payload_dict.get("request_timeout_seconds", 35.0) or 35.0))),
            )
            if result.get("status") != "ok":
                return _safe_error_payload(result.get("message", "simulation failed"), status_code=400)
            return result
        except Exception as exc:
            log.warning("Simulation endpoint failed", exc_info=True)
            return _safe_error_payload(str(exc), status_code=500)

