    @app.get("/debug/state")
    async def debug_state(limit: int = 100, offset: int = 0, key: Optional[str] = None, token: HTTPAuthorizationCredentials = Depends(verify_token)):
        if limit < 1:
            limit = 1
        limit = min(500, limit)
        offset = max(0, int(offset or 0))
        caller = "unknown"
        try:
            caller = token.credentials[:8]
        except Exception:
            pass
        now = time.time()
        cache_key = f"debug_state:{caller}"
        _rate_limit_cache[cache_key] = [t for t in _rate_limit_cache.get(cache_key, []) if now - t < 60]
        if len(_rate_limit_cache[cache_key]) >= max(10, CONFIG.rate_limit // 5):
            raise HTTPException(429, "Debug state rate limit exceeded")
        _rate_limit_cache[cache_key].append(now)
        if ctx_holder and 'state' in ctx_holder:
            s = ctx_holder['state'].cache
            sensitive_fields = ['secret_key', 'encryption_key', 'token', 'password']
            redacted = {}

            def _summarize(v: Any) -> Any:
                if isinstance(v, (str, int, float, bool)) or v is None:
                    return v
                if isinstance(v, dict):
                    keys = list(v.keys())
                    sample = {str(k): v[k] for k in keys[:10]}
                    return {"type": "dict", "size": len(v), "sample": sample}
                if isinstance(v, (list, tuple, set)):
                    seq = list(v)
                    return {"type": type(v).__name__, "size": len(seq), "sample": seq[:10]}
                return str(v)

            items = list(s.items())[offset:offset + limit]
            for k, v in items:
                lowered_key = str(k).lower()
                if any(tag in lowered_key for tag in sensitive_fields):
                    redacted[k] = "***REDACTED***"
                else:
                    redacted[k] = _summarize(v)
            if key:
                return {key: redacted.get(key)}
            return {
                "offset": offset,
                "limit": limit,
                "total": len(s),
                "items": redacted,
            }
        return {}

    @app.post("/bet")
    async def place_bet(
        fixture_id: str, market: str, outcome: str, odds: float, stake: float,
        request: Request,
        token: HTTPAuthorizationCredentials = Depends(verify_token)
    ):
        if not ctx_holder or 'orchestrator' not in ctx_holder:
            raise HTTPException(500, "System not initialized")
        client_ip = request.client.host
        now = time.time()
        _rate_limit_cache[client_ip] = [t for t in _rate_limit_cache.get(client_ip, []) if now - t < 60]
        if len(_rate_limit_cache[client_ip]) >= CONFIG.rate_limit:
            raise HTTPException(429, "Rate limit exceeded")
        _rate_limit_cache[client_ip].append(now)

        if odds <= 1.01 or odds > 1000:
            raise HTTPException(400, "Invalid odds")
        if stake <= 0:
            raise HTTPException(400, "Invalid stake")

        if not ctx_holder['orchestrator'].fetcher:
            ctx_holder['orchestrator'].fetcher = await RealDataFetcher(ctx_holder['orchestrator'].schema_validator).__aenter__()
        matches = await DataSource.fetch_upcoming(ctx_holder['orchestrator'].fetcher, ctx_holder['orchestrator'].state)
        match = None
        for m in matches:
            row = m.dict() if hasattr(m, "dict") else dict(m)
            if str(row.get("fixture_id", "")) == str(fixture_id):
                match = row
                break
        if not match:
            raise HTTPException(404, "Unknown fixture_id")

        market_outcomes = {
            "1X2": {"home", "draw", "away"},
            "OverUnder": {"over", "under"},
            "BTTS": {"yes", "no"},
            "CorrectScore": {f"{h}-{a}" for h in range(0, 6) for a in range(0, 6)},
            "AsianHandicap": {"home", "away"},
            "DoubleChance": {"1X", "X2", "12"},
            "DrawNoBet": {"home", "away"},
            "FirstHalfOverUnder": {"over", "under"},
            "TeamTotals": {"home_over", "home_under", "away_over", "away_under"},
            "WinToNil": {"home", "away"},
            "ResultBTTS": {"home_yes", "home_no", "draw_yes", "draw_no", "away_yes", "away_no"},
            "ResultTotals": {"home_over", "home_under", "draw_over", "draw_under", "away_over", "away_under"},
            "HalfTimeFullTime": {
                "home_home", "home_draw", "home_away",
                "draw_home", "draw_draw", "draw_away",
                "away_home", "away_draw", "away_away",
            },
            "HalfTimeFullTimeGoals": {"over_over", "over_under", "under_over", "under_under"},
            "ExactTeamGoals": {
                "home_0", "home_1", "home_2", "home_3plus",
                "away_0", "away_1", "away_2", "away_3plus",
            },
        }
        if market not in market_outcomes or outcome not in market_outcomes[market]:
            raise HTTPException(400, "Invalid market/outcome")

        decision = BetDecision(
            bet_id=str(uuid.uuid4()),
            fixture_id=fixture_id,
            market=market,
            outcome=outcome,
            prob=1.0/odds + 0.05,
            odds=odds,
            edge=0.05,
            stake=stake,
            bookmaker="api"
        )
        await ctx_holder['orchestrator']._place_bet(decision)
        return {"status": "ok", "bet": decision.dict()}

