    @app.get("/steam/moves")
    async def steam_moves(token: HTTPAuthorizationCredentials = Depends(verify_token)):
        orch = ctx_holder.get('orchestrator') if ctx_holder else None
        if not orch:
            raise HTTPException(500, "System not initialized")
        moves = []
        for key, buf in orch.steam_chaser._line_history.items():
            if len(buf) >= 2:
                old_ts, old_odds, _ = buf[0]
                new_ts, new_odds, _ = buf[-1]
                move = (old_odds - new_odds) / old_odds if old_odds > 0 else 0.0
                if abs(move) >= CONFIG.steam_chase_min_move:
                    moves.append({
                        "key": key,
                        "old_odds": old_odds,
                        "new_odds": new_odds,
                        "move": move,
                        "timestamp": new_ts,
                    })
        return {"steam_moves": moves[-50:]}

