    @app.post("/admin/rollback")
    async def admin_rollback(request: Request, token: HTTPAuthorizationCredentials = Depends(verify_token)):
        if not ctx_holder or 'state' not in ctx_holder:
            raise HTTPException(500, "System not initialized")
        state = ctx_holder['state']
        snapshot_a = CONFIG.snapshot_path_a
        snapshot_b = CONFIG.snapshot_path_b
        for path in [snapshot_a, snapshot_b]:
            if os.path.exists(path):
                try:
                    if os.path.getsize(path) > 200 * 1024 * 1024:
                        log.warning(f"Skipping oversized snapshot for rollback: {path}")
                        continue
                    data = joblib.load(path)
                    if data and data.get("timestamp", 0) > time.time() - 86400:
                        state.cache = data.get("state", {})
                        state.dirty.clear()
                        await state.flush()
                        if ctx_holder and 'db' in ctx_holder:
                            await ctx_holder['db'].execute(
                                "INSERT INTO audit_trail (timestamp, event, actor) VALUES (?, ?, ?)",
                                (time.time(), f"rollback:{path}", request.client.host if request.client else "unknown")
                            )
                        return {"status": "rollback successful", "from": path}
                except Exception:
                    pass
        return {"status": "no valid snapshot found"}

