def run_unit_tests():
    log.info("Running unit tests...")
    passed = failed = 0
    try:
        assert AsianHandicap.settle(-0.5, 2, 1) == "home"
        passed += 1
    except Exception as e:
        log.error(f"AH test failed: {e}")
        failed += 1
    try:
        legs = [{"fixture_id": "1", "market": "1X2", "outcome": "home", "odds": 2.0}]
        results = {"1": {"home_score": 2, "away_score": 1}}
        result = ParlayEngine.settle_parlay(legs, results)
        assert result["status"] == "won"
        passed += 1
    except Exception as e:
        log.error(f"Parlay test failed: {e}")
        failed += 1
    try:
        hg, ag, w = ImportanceSampler.sample_goals(1.5, 1.0, 1.3)
        assert w > 0
        passed += 1
    except Exception as e:
        log.error(f"Importance sampler test failed: {e}")
        failed += 1
    try:
        ess = TailGuard.effective_sample_size([0.5, 0.5, 0.5, 0.5])
        assert abs(float(ess) - 4.0) < 1e-6
        passed += 1
    except Exception as e:
        log.error(f"TailGuard test failed: {e}")
        failed += 1
    try:
        k = Calculator.kelly_fraction(0.6, 2.0)
        assert abs(float(k) - 0.2) < 1e-6
        passed += 1
    except Exception as e:
        log.error(f"Kelly test failed: {e}")
        failed += 1
    try:
        p = AdvancedMathEngine.bivariate_poisson_pmf(1, 1, 1.2, 1.0, 0.2)
        assert float(p) > 0
        passed += 1
    except Exception as e:
        log.error(f"Bivariate Poisson test failed: {e}")
        failed += 1
    log.info(f"Unit tests: {passed} passed, {failed} failed.")

