def check_dependencies():
    missing = []
    if not HAS_STATSMODELS:
        missing.append("statsmodels")
    if not HAS_SKLEARN:
        missing.append("sklearn")
    if not TORCH_AVAILABLE:
        missing.append("torch")
    if missing:
        log.warning(f"Optional dependencies missing: {', '.join(missing)}. Some features will be degraded.")
        if CONFIG.strict_dependencies:
            log.critical("Strict mode enabled. Exiting due to missing dependencies.")
            sys.exit(1)


def _polyglot_sector_map_path() -> str:
    base = os.path.dirname(os.path.abspath(__file__))
    return os.path.join(base, "polyglot", "sector_map.json")


def load_polyglot_sector_map() -> Dict[str, Dict[str, Any]]:
    path = _polyglot_sector_map_path()
    if not os.path.exists(path):
        return {}
    try:
        with open(path, "r", encoding="utf-8") as f:
            data = json.load(f)
        if isinstance(data, dict):
            return data
    except Exception as e:
        log.warning(f"Failed to load polyglot sector map: {e}")
    return {}


def _normalize_polyglot_languages(entry: Any) -> Tuple[str, List[str]]:
    languages: List[str] = ["Python"]
    if isinstance(entry, dict):
        raw_languages = entry.get("languages", entry.get("language", "Python"))
    else:
        raw_languages = "Python"

    if isinstance(raw_languages, str):
        candidate_languages = [raw_languages]
    elif isinstance(raw_languages, (list, tuple, set)):
        candidate_languages = [str(language) for language in raw_languages if str(language).strip()]
    else:
        candidate_languages = [str(raw_languages)] if raw_languages is not None else []

    if candidate_languages:
        languages = candidate_languages

    return languages[0], languages


def build_polyglot_sector_plan() -> Dict[str, Dict[str, Any]]:
    sector_map = load_polyglot_sector_map()
    plan: Dict[str, Dict[str, Any]] = {}
    for sector, entry in sector_map.items():
        backend, languages = _normalize_polyglot_languages(entry)
        plan[sector] = {"backend": backend, "languages": languages}
    return plan


def route_polyglot_sector(sector: str, payload: Dict[str, Any]) -> Dict[str, Any]:
    sector_map = load_polyglot_sector_map()
    entry = sector_map.get(sector, {})
    backend, languages = _normalize_polyglot_languages(entry)
    return {
        "sector": sector,
        "backend": backend,
        "languages": languages,
        "ok": True,
        "result": payload,
    }

