    if FastAPI is not None:
        def _ensure_tls_material() -> Tuple[Optional[str], Optional[str]]:
            if not CONFIG.tls_enabled:
                return None, None
            certfile = str(CONFIG.tls_certfile or "").strip()
            keyfile = str(CONFIG.tls_keyfile or "").strip()
            if certfile and keyfile and os.path.exists(certfile) and os.path.exists(keyfile):
                return certfile, keyfile
            if not CONFIG.tls_generate_self_signed:
                log.warning("TLS enabled but cert/key files are missing; set tls_generate_self_signed=true or provide files.")
                return None, None
            try:
                from cryptography import x509  # type: ignore
                from cryptography.hazmat.primitives import hashes, serialization  # type: ignore
                from cryptography.hazmat.primitives.asymmetric import rsa  # type: ignore
                from cryptography.x509.oid import NameOID  # type: ignore

                os.makedirs(os.path.dirname(certfile) or ".", exist_ok=True)
                key = rsa.generate_private_key(public_exponent=65537, key_size=2048)
                subject = issuer = x509.Name([
                    x509.NameAttribute(NameOID.COUNTRY_NAME, "US"),
                    x509.NameAttribute(NameOID.ORGANIZATION_NAME, "LHM"),
                    x509.NameAttribute(NameOID.COMMON_NAME, str(CONFIG.tls_common_name or "localhost")),
                ])
                cert = (
                    x509.CertificateBuilder()
                    .subject_name(subject)
                    .issuer_name(issuer)
                    .public_key(key.public_key())
                    .serial_number(x509.random_serial_number())
                    .not_valid_before(datetime.utcnow() - timedelta(minutes=1))
                    .not_valid_after(datetime.utcnow() + timedelta(days=365))
                    .add_extension(
                        x509.SubjectAlternativeName([x509.DNSName("localhost"), x509.DNSName(str(CONFIG.tls_common_name or "localhost"))]),
                        critical=False,
                    )
                    .sign(key, hashes.SHA256())
                )
                with open(keyfile, "wb") as f:
                    f.write(
                        key.private_bytes(
                            encoding=serialization.Encoding.PEM,
                            format=serialization.PrivateFormat.TraditionalOpenSSL,
                            encryption_algorithm=serialization.NoEncryption(),
                        )
                    )
                with open(certfile, "wb") as f:
                    f.write(cert.public_bytes(serialization.Encoding.PEM))
                log.warning(f"Generated self-signed TLS certificate at {certfile}. Use only for internal/dev scenarios.")
                return certfile, keyfile
            except Exception as exc:
                log.warning(f"TLS material generation failed: {exc}")
                return None, None

        def run_api():
            certfile, keyfile = _ensure_tls_material()
            if CONFIG.host not in {"127.0.0.1", "localhost"}:
                log.warning("API is running without built-in TLS. Use HTTPS termination in front of uvicorn.")
            uvicorn_kwargs = {
                "host": CONFIG.host,
                "port": CONFIG.port,
                "log_level": "info",
            }
            if certfile and keyfile:
                uvicorn_kwargs["ssl_certfile"] = certfile
                uvicorn_kwargs["ssl_keyfile"] = keyfile
                log.info(f"Built-in TLS enabled using cert={certfile}")
            uvicorn.run(app, **uvicorn_kwargs)
        if args.api_only:
            threading.Thread(target=run_api, daemon=True).start()
            log.info(f"API server running on {CONFIG.host}:{CONFIG.port}")

    if CONFIG.enable_health_server:
        _METRICS = {"cycles": 0, "arb_alerts": 0, "errors": 0, "last_cycle_ts": time.time()}

        def _run_health_server():
            from http.server import HTTPServer, BaseHTTPRequestHandler

            class HealthHandler(BaseHTTPRequestHandler):
                def do_GET(self):
                    try:
                        state = orchestrator.state
                        bankroll = float(state.get("bankroll", 1000.0) or 1000.0)
                        exposure = float(state.get("exposure", 0.0) or 0.0)
                        pending = 0
                        try:
                            loop = asyncio.get_event_loop()
                            pending = loop.run_until_complete(
                                orchestrator.db.fetchall("SELECT COUNT(*) as cnt FROM pending_bets")
                            )
                            pending = pending[0]["cnt"] if pending else 0
                        except Exception:
                            pending = -1
                        payload = json.dumps({
                            "status": "ok",
                            "bankroll": bankroll,
                            "exposure": exposure,
                            "pending_bets": pending,
                            "dry_run": CONFIG.dry_run,
                            "metrics": _METRICS,
                        }).encode()
                        self.send_response(200)
                        self.send_header("Content-Type", "application/json")
                        self.end_headers()
                        self.wfile.write(payload)
                    except Exception as e:
                        self.send_response(500)
                        self.end_headers()
                        self.wfile.write(str(e).encode())
                def log_message(self, fmt, *args):
                    pass

            server = HTTPServer(("127.0.0.1", 9090), HealthHandler)
            server.serve_forever()

        threading.Thread(target=_run_health_server, daemon=True).start()
        log.info("Health server listening on http://127.0.0.1:9090/health")

    if getattr(CONFIG, "enable_file_watcher", False):
        _ENGINE_PATH = os.path.abspath(__file__)
        _file_watcher_mtime = os.path.getmtime(_ENGINE_PATH)

        def _watch_engine_file():
            nonlocal _file_watcher_mtime
            while True:
                try:
                    time.sleep(10)
                    current_mtime = os.path.getmtime(_ENGINE_PATH)
                    if current_mtime != _file_watcher_mtime:
                        _file_watcher_mtime = current_mtime
                        log.info("Engine file changed; restarting process.")
                        try:
                            os.execv(sys.executable, [sys.executable] + sys.argv)
                        except Exception as exc:
                            log.error(f"Auto-update restart failed: {exc}")
                            break
                except Exception:
                    pass

        threading.Thread(target=_watch_engine_file, daemon=True).start()
        log.info("File watcher enabled for auto-update.")

    cycle = 0
    while True:
        try:
            start = time.time()
            success = await orchestrator.run_once()
            cycle += 1
            if CONFIG.enable_health_server:
                try:
                    _METRICS["cycles"] = cycle
                    _METRICS["last_cycle_ts"] = time.time()
                except Exception:
                    pass
            if cycle % Constants.DEFAULT_HEARTBEAT_INTERVAL_CYCLES == 0:
                try:
                    await orchestrator._send_heartbeat()
                except Exception as exc:
                    log.warning(f"Heartbeat send failed: {exc}")
            if orchestrator._kill_switch:
                log.info("Main loop exiting after kill switch.")
                break
            elapsed = time.time() - start
            sleep_dur = max(3, CONFIG.loop_interval - elapsed)
            await asyncio.sleep(sleep_dur)
        except Exception as e:
            log.critical(f"Fatal: {traceback.format_exc()}")
            if CONFIG.enable_health_server:
                try:
                    _METRICS["errors"] += 1
                except Exception:
                    pass
            await send_alert_async(f"CRASH: {e}. Restart in 120s.")
            await asyncio.sleep(120)

