class OfficialFeedGateway:
    """Primary odds/events gateway: Sportmonks, Betfair, and free-scraper fallbacks."""
    def __init__(self, primary_source: str = "sportmonks", fallback_fetcher=None):
        self.primary_source = primary_source
        self.fallback_fetcher = fallback_fetcher
        self._client = None
        self._connected = False
        self._last_packet_ts: Optional[float] = None

    def connect(self) -> bool:
        try:
            self._client = self._init_client(self.primary_source)
            self._connected = True
            log.info(f"OfficialFeedGateway connected to {self.primary_source}")
            return True
        except Exception as e:
            log.warning(f"Official feed connection failed: {e}. Using fallback.")
            self._connected = False
            return False

    def _init_client(self, source: str):
        if source == "sportmonks":
            try:
                from sportmonks import Sportmonks
                return Sportmonks()
            except ImportError:
                raise RuntimeError("sportmonks SDK not installed")
        elif source == "betfair":
            try:
                from betfairlightweight import BetfairClient
                return BetfairClient("", "")
            except ImportError:
                raise RuntimeError("betfairlightweight not installed")
        raise ValueError(f"Unknown source: {source}")

    def get_live_odds(self, fixture_id: str) -> Optional[Dict[str, Any]]:
        if self._connected and self._client:
            try:
                data = self._client.get_odds(fixture_id)
                self._last_packet_ts = time.time()
                return data
            except Exception as e:
                log.error(f"Official feed error: {e}")
                self._connected = False
        if self.fallback_fetcher:
            return self.fallback_fetcher(fixture_id)
        return None

    def is_stale(self, max_age_seconds: float = 1.5) -> bool:
        if self._last_packet_ts is None:
            return True
        return (time.time() - self._last_packet_ts) > max_age_seconds


class OrderBookProcessor:
    def __init__(self, max_depth: int = 10):
        self.max_depth = max_depth
        self._books: Dict[str, Dict[str, Any]] = {}
        self._lock = threading.Lock()
        self._spread_velocity: Dict[str, float] = {}

    def update(self, fixture_id: str, bids: List[tuple], asks: List[tuple]):
        with self._lock:
            self._books[fixture_id] = {
                "bids": bids[: self.max_depth],
                "asks": asks[: self.max_depth],
                "timestamp": time.time(),
            }

    def get_features(self, fixture_id: str) -> Dict[str, float]:
        with self._lock:
            book = self._books.get(fixture_id)
            if not book:
                return {"spread": 0.0, "imbalance": 0.0, "vwap": 0.0, "spread_velocity": 0.0}
            bids = book["bids"]
            asks = book["asks"]
            if not bids or not asks:
                return {"spread": 0.0, "imbalance": 0.0, "vwap": 0.0, "spread_velocity": 0.0}
            spread = float(asks[0][0] - bids[0][0])
            total_bid = sum(float(x[1]) for x in bids)
            total_ask = sum(float(x[1]) for x in asks)
            imbalance = (total_bid - total_ask) / max(total_bid + total_ask, 1e-9)
            bid_vwap = (
                sum(float(x[0]) * float(x[1]) for x in bids) / max(total_bid, 1e-9)
            )
            ask_vwap = (
                sum(float(x[0]) * float(x[1]) for x in asks) / max(total_ask, 1e-9)
            )
            vwap = (bid_vwap + ask_vwap) / 2.0
            return {
                "spread": spread,
                "imbalance": imbalance,
                "vwap": vwap,
                "spread_velocity": self._spread_velocity.get(fixture_id, 0.0),
            }

    def liquidity_at_price(self, fixture_id: str, side: str, price: float) -> float:
        with self._lock:
            book = self._books.get(fixture_id)
            if not book:
                return 0.0
            levels = book["bids"] if side == "bid" else book["asks"]
            for lvl in levels:
                if abs(float(lvl[0]) - price) < 1e-6:
                    return float(lvl[1])
            return 0.0


class HeartbeatMonitor:
    def __init__(self, max_staleness_seconds: float = 1.5):
        self.max_staleness = max_staleness_seconds
        self._last_heartbeat: Optional[float] = None
        self._halted = False
        self._lock = threading.Lock()

    def ping(self):
        with self._lock:
            self._last_heartbeat = time.time()
            if self._halted:
                log.info("Heartbeat restored. Resuming operations.")
                self._halted = False

    def is_healthy(self) -> bool:
        with self._lock:
            if self._last_heartbeat is None:
                return False
            age = time.time() - self._last_heartbeat
            if age > self.max_staleness and not self._halted:
                log.warning(
                    f"Data lag circuit breaker TRIPPED: {age:.2f}s > {self.max_staleness}s. Halting bets."
                )
                self._halted = True
            return not self._halted

    def force_halt(self):
        with self._lock:
            self._halted = True
            log.warning("HeartbeatMonitor: FORCED HALT.")


class TimescaleDBWrapper:
    def __init__(self, dsn: str = "", sqlite_path: str = "lhm_prod.db"):
        self.dsn = dsn or os.environ.get("TIMESCALEDB_DSN", "")
        self.sqlite_path = sqlite_path
        self._use_timescaledb = (
            bool(self.dsn) and os.environ.get("LHM_USE_TIMESCALEDB", "0") == "1"
        )
        self._conn = None
        self._init_backend()

    def _init_backend(self):
        if self._use_timescaledb:
            try:
                import psycopg2

                self._conn = psycopg2.connect(self.dsn)
                self._ensure_hypertables()
                log.info("TimescaleDBWrapper: connected to TimescaleDB")
            except Exception as e:
                log.warning(
                    f"TimescaleDB connection failed: {e}. Falling back to SQLite."
                )
                self._use_timescaledb = False
                self._init_sqlite()
        else:
            self._init_sqlite()

    def _init_sqlite(self):
        import sqlite3

        self._conn = sqlite3.connect(self.sqlite_path, check_same_thread=False)
        self._conn.execute("PRAGMA journal_mode=WAL")
        log.info("TimescaleDBWrapper: using SQLite fallback")

    def _ensure_hypertables(self):
        if not self._use_timescaledb:
            return
        cur = self._conn.cursor()
        cur.execute(
            """
            CREATE TABLE IF NOT EXISTS matches (
                fixture_id TEXT, league TEXT, home TEXT, away TEXT,
                kickoff TIMESTAMPTZ, odds JSONB, features JSONB,
                outcome JSONB, created_at TIMESTAMPTZ DEFAULT NOW()
            );
            SELECT create_hypertable('matches', 'kickoff', if_not_exists => TRUE);
        """
        )
        cur.execute(
            """
            CREATE TABLE IF NOT EXISTS bets (
                bet_id TEXT, fixture_id TEXT, market TEXT, selection TEXT,
                odds NUMERIC, stake NUMERIC, edge NUMERIC, placed_at TIMESTAMPTZ DEFAULT NOW()
            );
            SELECT create_hypertable('bets', 'placed_at', if_not_exists => TRUE);
        """
        )
        self._conn.commit()

    def execute(self, query: str, params: tuple = ()):
        cur = self._conn.cursor()
        cur.execute(query, params)
        self._conn.commit()
        return cur

    def close(self):
        if self._conn:
            self._conn.close()


class OrderIdempotencyManager:
    def __init__(self, redis_client=None, ttl_seconds: int = 86400):
        self._redis = redis_client
        self._ttl = ttl_seconds
        self._memory_vault: Dict[str, Dict[str, Any]] = {}

    def _key(self, client_ref: str) -> str:
        return f"lhm:idempotency:{hashlib.sha256(client_ref.encode()).hexdigest()}"

    def exists(self, client_ref: str) -> bool:
        k = self._key(client_ref)
        if self._redis:
            return bool(self._redis.exists(k))
        return k in self._memory_vault

    def record(self, client_ref: str, order_status: Dict[str, Any]):
        k = self._key(client_ref)
        if self._redis:
            self._redis.setex(k, self._ttl, json.dumps(order_status))
        else:
            self._memory_vault[k] = order_status

    def get(self, client_ref: str) -> Optional[Dict[str, Any]]:
        k = self._key(client_ref)
        if self._redis:
            raw = self._redis.get(k)
            return json.loads(raw) if raw else None
        return self._memory_vault.get(k)


