@dataclass
class MarketImpliedFeatures:
    fair_prob_home: float = 0.0
    fair_prob_draw: float = 0.0
    fair_prob_away: float = 0.0
    overround: float = 0.0
    clv_open: float = 0.0
    clv_close: float = 0.0
    divergence: float = 0.0
    sharpness_score: float = 0.0


class MarketImpliedEngine:
    def __init__(self):
        self._history: Dict[str, List[Dict[str, float]]] = {}

    def derive(
        self,
        fixture_id: str,
        opening_odds: Dict[str, float],
        closing_odds: Dict[str, float],
    ) -> MarketImpliedFeatures:
        implied = self._remove_overround(closing_odds)
        fair_home = implied.get("home", 0.33)
        fair_draw = implied.get("draw", 0.33)
        fair_away = implied.get("away", 0.34)
        overround = (
            sum(
                1.0 / max(v, 1e-6)
                for v in closing_odds.values()
                if isinstance(v, (int, float))
            )
            - 1.0
        )
        open_implied = self._remove_overround(opening_odds)
        clv_open = fair_home - open_implied.get("home", 0.0)
        clv_close = fair_home - closing_odds.get("home", 0.0) if "home" in closing_odds else 0.0
        divergence = abs(clv_open - clv_close)
        sharpness = self._compute_sharpness(fixture_id, closing_odds)
        feat = MarketImpliedFeatures(
            fair_prob_home=fair_home,
            fair_prob_draw=fair_draw,
            fair_prob_away=fair_away,
            overround=overround,
            clv_open=clv_open,
            clv_close=clv_close,
            divergence=divergence,
            sharpness_score=sharpness,
        )
        self._history.setdefault(fixture_id, []).append(
            {
                "ts": time.time(),
                "fair_home": fair_home,
                "fair_draw": fair_draw,
                "fair_away": fair_away,
                "overround": overround,
            }
        )
        return feat

    @staticmethod
    def _remove_overround(odds: Dict[str, float]) -> Dict[str, float]:
        inv = {
            k: 1.0 / max(v, 1e-6)
            for k, v in odds.items()
            if isinstance(v, (int, float)) and v > 0
        }
        total = sum(inv.values())
        if total <= 0:
            return {"home": 0.33, "draw": 0.33, "away": 0.34}
        return {k: v / total for k, v in inv.items()}

    def _compute_sharpness(self, fixture_id: str, current_odds: Dict[str, float]) -> float:
        hist = self._history.get(fixture_id, [])
        if len(hist) < 2:
            return 0.0
        recent = hist[-5:]
        spreads = []
        for entry in recent:
            p = [
                entry.get("fair_home", 0),
                entry.get("fair_draw", 0),
                entry.get("fair_away", 0),
            ]
            spreads.append(max(p) - min(p))
        return float(np.mean(spreads)) if spreads else 0.0

    def to_dict(self, f: MarketImpliedFeatures) -> Dict[str, float]:
        return {
            "fair_prob_home": f.fair_prob_home,
            "fair_prob_draw": f.fair_prob_draw,
            "fair_prob_away": f.fair_prob_away,
            "overround": f.overround,
            "clv_open": f.clv_open,
            "clv_close": f.clv_close,
            "divergence": f.divergence,
            "sharpness_score": f.sharpness_score,
        }


class LeagueRegimeScaler:
    def __init__(self, window: int = 20, base_edge: float = 0.04):
        self.window = window
        self.base_edge = base_edge
        self._league_goals: Dict[str, List[float]] = {}
        self._lock = threading.Lock()

    def update(self, league_key: str, total_goals: float):
        with self._lock:
            self._league_goals.setdefault(league_key, []).append(total_goals)
            if len(self._league_goals[league_key]) > self.window:
                self._league_goals[league_key] = self._league_goals[league_key][-self.window :]

    def scaled_edge(self, league_key: str) -> float:
        with self._lock:
            goals = self._league_goals.get(league_key, [])
            if not goals:
                return self.base_edge
            avg = float(np.mean(goals))
            return self.base_edge * (avg / 2.5)

    def variance(self, league_key: str) -> float:
        with self._lock:
            goals = self._league_goals.get(league_key, [])
            return float(np.var(goals)) if len(goals) > 1 else 0.0


class ExogenousEncoder:
    def __init__(self, input_dim: int = 6, hidden_dim: int = 16):
        self.input_dim = input_dim
        self._model = None
        self._fallback_mode = True
        try:
            import torch
            import torch.nn as nn

            self._model = nn.Sequential(
                nn.Linear(input_dim, hidden_dim),
                nn.ReLU(),
                nn.Linear(hidden_dim, 4),
                nn.Sigmoid(),
            )
            self._fallback_mode = False
        except Exception:
            log.warning(
                "PyTorch not available. Using exogenous fallback heuristics."
            )

    def encode(
        self,
        weather_temp: float,
        wind: float,
        referee_id: str,
        injury_count: int,
        days_rest_home: float,
        days_rest_away: float,
    ) -> Dict[str, float]:
        if self._fallback_mode or self._model is None:
            return self._heuristic_encode(
                weather_temp,
                wind,
                referee_id,
                injury_count,
                days_rest_home,
                days_rest_away,
            )
        import torch

        x = torch.tensor(
            [
                [
                    weather_temp,
                    wind,
                    hash(referee_id) % 100,
                    injury_count,
                    days_rest_home,
                    days_rest_away,
                ]
            ],
            dtype=torch.float32,
        )
        with torch.no_grad():
            y = self._model(x).numpy()[0]
        return {
            "home_attack_mult": float(y[0]),
            "home_defense_mult": float(y[1]),
            "away_attack_mult": float(y[2]),
            "away_defense_mult": float(y[3]),
        }

    @staticmethod
    def _heuristic_encode(
        weather_temp,
        wind,
        referee_id,
        injury_count,
        days_rest_home,
        days_rest_away,
    ) -> Dict[str, float]:
        weather_factor = max(0.8, min(1.2, 1.0 - abs(weather_temp - 20) / 100.0))
        wind_factor = max(0.9, min(1.1, 1.0 - wind / 50.0))
        rest_home = max(0.8, min(1.2, days_rest_home / 7.0))
        rest_away = max(0.8, min(1.2, days_rest_away / 7.0))
        injury_penalty = max(0.7, 1.0 - injury_count * 0.05)
        return {
            "home_attack_mult": weather_factor * rest_home * injury_penalty,
            "home_defense_mult": weather_factor * rest_home,
            "away_attack_mult": wind_factor * rest_away * injury_penalty,
            "away_defense_mult": wind_factor * rest_away,
        }


class FeatureStore:
    def __init__(self, redis_client=None):
        self._redis = redis_client
        self._local_store: Dict[str, Dict[str, float]] = {}

    def _key(self, fixture_id: str) -> str:
        return f"lhm:features:{fixture_id}"

    def get(self, fixture_id: str) -> Optional[Dict[str, float]]:
        k = self._key(fixture_id)
        if self._redis:
            raw = self._redis.get(k)
            return json.loads(raw) if raw else None
        return self._local_store.get(fixture_id)

    def put(self, fixture_id: str, features: Dict[str, float]):
        k = self._key(fixture_id)
        if self._redis:
            self._redis.setex(k, 3600, json.dumps(features))
        else:
            self._local_store[k] = features

    def delta_update(self, fixture_id: str, new_features: Dict[str, float]) -> Dict[str, float]:
        existing = self.get(fixture_id) or {}
        merged = dict(existing)
        merged.update(new_features)
        self.put(fixture_id, merged)
        return merged


