# GROUP C: MODELING & ONLINE LEARNING
# ======================================================================
class PurgedGroupTimeSeriesSplit:
    def __init__(self, n_splits: int = 5, purge_gap_days: int = 7):
        self.n_splits = n_splits
        self.purge_gap_days = purge_gap_days

    def split(self, X, dates: List[float]):
        sorted_indices = sorted(range(len(dates)), key=lambda i: dates[i])
        sorted_dates = [dates[i] for i in sorted_indices]
        n = len(sorted_indices)
        fold_size = n // self.n_splits
        for i in range(self.n_splits):
            train_end = (i + 1) * fold_size
            val_start = train_end
            val_end = (i + 2) * fold_size if i < self.n_splits - 1 else n
            purge_cutoff = (
                sorted_dates[train_end - 1] if train_end > 0 else sorted_dates[0]
            )
            purge_limit = purge_cutoff + self.purge_gap_days * 86400
            train_idx = [
                idx
                for idx in sorted_indices[:train_end]
                if dates[idx] <= purge_limit
            ]
            val_idx = sorted_indices[val_start:val_end]
            yield train_idx, val_idx


@dataclass
class TeamStrengthPriors:
    attack: float = 0.0
    defense: float = 0.0
    attack_var: float = 0.25
    defense_var: float = 0.25


class RecursiveBayesianUpdater:
    def __init__(self, process_variance: float = 0.01, measurement_variance: float = 0.5):
        self.process_variance = process_variance
        self.measurement_variance = measurement_variance
        self._team_priors: Dict[str, TeamStrengthPriors] = {}
        self._lock = threading.Lock()

    def update(self, team: str, goals_for: int, goals_against: int, is_home: bool):
        with self._lock:
            if team not in self._team_priors:
                self._team_priors[team] = TeamStrengthPriors()
            p = self._team_priors[team]
            home_advantage = 0.3 if is_home else 0.0
            expected_goals = math.exp(p.attack - p.defense + home_advantage)
            innovation = goals_for - expected_goals
            kalman_gain = p.attack_var / (p.attack_var + self.measurement_variance)
            p.attack = p.attack + kalman_gain * innovation
            p.attack_var = (1.0 - kalman_gain) * p.attack_var + self.process_variance
            p.defense = p.defense - kalman_gain * innovation
            p.defense_var = (1.0 - kalman_gain) * p.defense_var + self.process_variance

    def get_team_strength(self, team: str) -> Tuple[float, float]:
        with self._lock:
            if team not in self._team_priors:
                self._team_priors[team] = TeamStrengthPriors()
            p = self._team_priors[team]
            return p.attack, p.defense


class EnsembleWeightOptimizer:
    def __init__(self, model_names: List[str], window: int = 50):
        self.model_names = model_names
        self.window = window
        self._loss_history: Dict[str, List[float]] = {m: [] for m in model_names}
        self._weights: Dict[str, float] = {m: 1.0 / len(model_names) for m in model_names}
        self._last_recalc = time.time()
        self._lock = threading.Lock()

    def record_loss(self, model_name: str, loss: float):
        with self._lock:
            self._loss_history[model_name].append(loss)
            if len(self._loss_history[model_name]) > self.window:
                self._loss_history[model_name] = self._loss_history[model_name][-self.window :]

    def get_weights(self) -> Dict[str, float]:
        with self._lock:
            now = time.time()
            if (now - self._last_recalc) < 3600:
                return dict(self._weights)
            self._last_recalc = now
            losses = []
            for m in self.model_names:
                hist = self._loss_history.get(m, [])
                avg_loss = np.mean(hist[-self.window :]) if hist else 1.0
                losses.append(avg_loss)
            losses = np.array(losses)
            exp_neg = np.exp(-losses)
            weights = exp_neg / max(exp_neg.sum(), 1e-9)
            self._weights = {m: float(w) for m, w in zip(self.model_names, weights)}
            return dict(self._weights)


class CausalFeatureSelector:
    def __init__(self, p_value_threshold: float = 0.1):
        self.p_value_threshold = p_value_threshold
        self._selected_features: List[str] = []
        self._scores: Dict[str, float] = {}

    def select(self, X: np.ndarray, y: np.ndarray, feature_names: List[str]) -> List[str]:
        if X.shape[0] < 20 or X.shape[1] < 2:
            return feature_names
        from sklearn.linear_model import LassoCV
        from sklearn.model_selection import cross_val_predict

        residuals_y = y - np.mean(y)
        valid_mask = np.isfinite(residuals_y)
        if np.sum(valid_mask) < 20:
            return feature_names
        X_clean = X[valid_mask]
        y_clean = residuals_y[valid_mask]
        n_samples, n_features = X_clean.shape
        if n_samples <= n_features + 1:
            return feature_names
        try:
            lasso = LassoCV(cv=3, max_iter=2000)
            y_pred = cross_val_predict(lasso, X_clean, y_clean, cv=3)
            residuals_f = y_clean - y_pred
            valid_f = np.isfinite(residuals_f) & np.isfinite(y_pred)
            if np.sum(valid_f) < 10:
                return feature_names
            theta_hat = np.zeros(n_features)
            p_values = np.ones(n_features)
            for j in range(n_features):
                x_j = X_clean[valid_f, j]
                y_r = residuals_f[valid_f]
                x_r = residuals_f[valid_f]
                mask = np.isfinite(x_j) & np.isfinite(y_r) & np.isfinite(x_r)
                if np.sum(mask) < 10:
                    continue
                x_j_c = x_j[mask]
                y_r_c = y_r[mask]
                x_r_c = x_r[mask]
                from sklearn.linear_model import LinearRegression

                model = LinearRegression()
                model.fit(x_r_c.reshape(-1, 1), x_j_c)
                v_j = x_j_c - model.predict(x_r_c.reshape(-1, 1))
                model2 = LinearRegression()
                model2.fit(v_j.reshape(-1, 1), y_r_c)
                theta_hat[j] = model2.coef_[0]
                ss_res = np.sum((y_r_c - model2.predict(v_j.reshape(-1, 1))) ** 2)
                ss_tot = np.sum((y_r_c - np.mean(y_r_c)) ** 2)
                r2 = 1 - ss_res / max(ss_tot, 1e-9)
                p_values[j] = max(0.0, min(1.0, 1.0 - r2))
            selected = []
            for i, name in enumerate(feature_names):
                if i < len(p_values) and p_values[i] < self.p_value_threshold:
                    selected.append(name)
                    self._scores[name] = (
                        float(theta_hat[i]) if i < len(theta_hat) else 0.0
                    )
            self._selected_features = selected if selected else feature_names[-10:]
            return self._selected_features
        except Exception as e:
            log.warning(f"Causal selection failed: {e}")
            return feature_names


