class LiquidityAwareExecutor:
    def __init__(self, max_single_order_pct: float = 0.02, split_interval_ms: int = 200):
        self.max_single_order_pct = max_single_order_pct
        self.split_interval_ms = split_interval_ms

    def compute_chunks(self, stake: float, available_liquidity: float) -> List[float]:
        if available_liquidity <= 0 or stake <= 0:
            return []
        max_chunk = available_liquidity * self.max_single_order_pct
        if max_chunk <= 0:
            return []
        if stake <= max_chunk:
            return [stake]
        chunks = []
        remaining = stake
        while remaining > 1e-9:
            this_chunk = min(max_chunk, remaining)
            chunks.append(this_chunk)
            remaining -= this_chunk
            if len(chunks) >= 20:
                chunks.append(remaining)
                break
        return chunks

    def should_split(self, stake: float, available_liquidity: float) -> bool:
        if available_liquidity <= 0:
            return False
        return stake > available_liquidity * self.max_single_order_pct


class SlippagePredictor:
    def __init__(self):
        self._model = None
        self._fallback_mode = True
        try:
            from sklearn.ensemble import GradientBoostingRegressor

            self._model = GradientBoostingRegressor(n_estimators=50, max_depth=3)
            self._fallback_mode = False
        except ImportError:
            log.warning("sklearn not available. Using fixed slippage.")

    def fit(self, X: np.ndarray, y: np.ndarray):
        if self._fallback_mode or self._model is None:
            return
        try:
            self._model.fit(X, y)
        except Exception as e:
            log.warning(f"SlippagePredictor fit failed: {e}")

    def predict(self, volatility: float, spread: float, order_depth: float) -> float:
        if self._fallback_mode or self._model is None:
            return 0.005
        try:
            features = np.array([[volatility, spread, order_depth]])
            pred = self._model.predict(features)[0]
            return max(0.0, min(0.05, float(pred)))
        except Exception:
            return 0.005


class BookmakerRouter:
    def __init__(self, max_stake_per_book_pct: float = 0.03):
        self.max_stake_per_book_pct = max_stake_per_book_pct
        self._book_limits: Dict[str, float] = {}

    def update_limit(self, bookmaker: str, max_stake: float):
        self._book_limits[bookmaker] = max_stake

    def route(self, total_stake: float, bookmakers: List[str]) -> Dict[str, float]:
        if not bookmakers:
            return {}
        per_book = total_stake / max(1, len(bookmakers))
        allocation: Dict[str, float] = {}
        remaining = total_stake
        for bm in bookmakers:
            limit = self._book_limits.get(bm, float("inf"))
            cap = min(per_book, limit * self.max_stake_per_book_pct)
            alloc = min(cap, remaining)
            if alloc > 0:
                allocation[bm] = alloc
                remaining -= alloc
            if remaining <= 1e-9:
                break
        return allocation


class AtomicBetUnit:
    def __init__(self):
        self._reservations: Dict[str, Dict[str, Any]] = {}

    def reserve(self, bet_id: str, bookmakers: List[str], stakes: Dict[str, float]) -> bool:
        try:
            self._reservations[bet_id] = {
                "bookmakers": list(bookmakers),
                "stakes": dict(stakes),
                "ts": time.time(),
            }
            return True
        except Exception:
            return False

    def commit(self, bet_id: str) -> bool:
        return bet_id in self._reservations

    def cancel(self, bet_id: str):
        self._reservations.pop(bet_id, None)

    def get_reservation(self, bet_id: str) -> Optional[Dict[str, Any]]:
        return self._reservations.get(bet_id)


# ======================================================================
# GROUP E: PORTFOLIO RISK & KELLY UPGRADE
# ======================================================================
class CovarianceKelly:
    def __init__(self, lookback: int = 50):
        self.lookback = lookback
        self._returns: Dict[str, List[float]] = {}

    def update_return(self, bet_id: str, ret: float):
        self._returns.setdefault(bet_id, []).append(ret)
        if len(self._returns[bet_id]) > self.lookback:
            self._returns[bet_id] = self._returns[bet_id][-self.lookback :]

    def covariance_matrix(self, bet_ids: List[str]) -> np.ndarray:
        n = len(bet_ids)
        if n == 0:
            return np.eye(0)
        series = []
        for bid in bet_ids:
            hist = self._returns.get(bid, [])
            if len(hist) < 2:
                series.append(np.zeros(self.lookback))
            else:
                arr = np.array(hist[-self.lookback :], dtype=float)
                if arr.size < self.lookback:
                    arr = np.pad(arr, (0, self.lookback - arr.size), mode="edge")
                series.append(arr)
        mat = np.vstack(series)
        if mat.shape[1] < 2:
            return np.eye(n) * 0.01
        cov = np.cov(mat)
        if cov.shape != (n, n):
            cov = np.eye(n) * 0.01
        return cov

    @staticmethod
    def optimal_weights(mu: np.ndarray, cov: np.ndarray, risk_free: float = 0.01) -> np.ndarray:
        n = len(mu)
        if n == 0:
            return np.array([])
        try:
            from scipy.optimize import minimize

            def objective(w):
                w = np.array(w)
                ret = np.dot(w, mu)
                risk = np.sqrt(np.dot(w, np.dot(cov, w)))
                if risk <= 1e-9:
                    return 1e6
                return -(ret - risk_free) / risk

            constraints = [{"type": "eq", "fun": lambda w: np.sum(w) - 1}]
            bounds = [(0, 0.15)] * n
            init = np.ones(n) / n
            result = minimize(
                objective, init, method="SLSQP", bounds=bounds, constraints=constraints
            )
            if result.success:
                return result.x
        except Exception:
            pass
        return np.ones(n) / n


class DrawdownAwareKelly:
    def __init__(self, max_drawdown: float = 0.20, dd_kelly_scale: bool = True):
        self.max_drawdown = max_drawdown
        self.dd_kelly_scale = dd_kelly_scale

    def scale(self, base_fraction: float, current_drawdown: float) -> float:
        if not self.dd_kelly_scale:
            return base_fraction
        if current_drawdown <= 0.05:
            return base_fraction
        scale_factor = max(0.0, 1.0 - (current_drawdown / self.max_drawdown))
        return base_fraction * scale_factor


class TailHedge:
    def __init__(self, vol_spike_threshold: float = 2.0):
        self.vol_spike_threshold = vol_spike_threshold
        self._active = False

    def check(self, recent_vol: float, baseline_vol: float) -> bool:
        if baseline_vol <= 1e-9:
            return False
        ratio = recent_vol / baseline_vol
        self._active = ratio >= self.vol_spike_threshold
        return self._active

    def hedge_stake(self, base_stake: float) -> float:
        if not self._active:
            return 0.0
        return base_stake * 0.1


# ======================================================================
# GROUP F: OBSERVABILITY & SELF-CORRECTION
# ======================================================================
class PnLAttributionEngine:
    def __init__(self):
        self._attribution_log: List[Dict[str, Any]] = []
        self._lock = threading.Lock()

    def record(self, bet_id: str, feature_group: str, pnl: float, shap_values: Dict[str, float]):
        with self._lock:
            self._attribution_log.append(
                {
                    "bet_id": bet_id,
                    "feature_group": feature_group,
                    "pnl": pnl,
                    "shap_values": shap_values,
                    "ts": time.time(),
                }
            )

    def group_summary(self) -> Dict[str, Dict[str, float]]:
        summary: Dict[str, Dict[str, float]] = {}
        with self._lock:
            for entry in self._attribution_log:
                fg = entry["feature_group"]
                if fg not in summary:
                    summary[fg] = {"total_pnl": 0.0, "count": 0, "shap_sum": 0.0}
                summary[fg]["total_pnl"] += entry["pnl"]
                summary[fg]["count"] += 1
                summary[fg]["shap_sum"] += sum(abs(v) for v in entry["shap_values"].values())
            for fg, stats in summary.items():
                stats["avg_pnl"] = stats["total_pnl"] / max(stats["count"], 1)
        return summary


class LivePerformanceMonitor:
    def __init__(self, rollback_roi_threshold: float = -0.03, rollback_bets: int = 20):
        self.rollback_roi_threshold = rollback_roi_threshold
        self.rollback_bets = rollback_bets
        self._champion_roi: float = 0.0
        self._challenger_roi: float = 0.0
        self._rollback_active: bool = False

    def update_champion(self, roi: float):
        self._champion_roi = roi

    def update_challenger(self, roi: float):
        self._challenger_roi = roi

    def should_rollback(self) -> bool:
        if self._rollback_active:
            return False
        delta = self._challenger_roi - self._champion_roi
        if delta < self.rollback_roi_threshold:
            log.warning(
                f"LivePerformanceMonitor: ROLLBACK TRIGGERED. Challenger ROI={self._challenger_roi:.3f} vs Champion={self._champion_roi:.3f}"
            )
            self._rollback_active = True
            return True
        return False

    def reset_rollback(self):
        self._rollback_active = False


class ShadowTester:
    def __init__(self, max_variants: int = 3):
        self.max_variants = max_variants
        self._variants: Dict[str, Dict[str, Any]] = {}
        self._lock = threading.Lock()

    def register_variant(self, variant_id: str, model_type: str):
        with self._lock:
            self._variants[variant_id] = {
                "model_type": model_type,
                "bets": 0,
                "wins": 0,
                "stake": 0.0,
                "return": 0.0,
                "ts": time.time(),
            }

    def record_virtual_bet(self, variant_id: str, stake: float, won: bool, odds: float):
        with self._lock:
            v = self._variants.get(variant_id)
            if not v:
                return
            v["bets"] += 1
            v["stake"] += stake
            if won:
                v["wins"] += 1
                v["return"] += stake * odds
            else:
                v["return"] -= stake

    def leaderboard(self) -> List[Dict[str, Any]]:
        with self._lock:
            return sorted(
                self._variants.values(),
                key=lambda x: x["return"] / max(x["stake"], 1e-9),
                reverse=True,
            )


class DriftTelemetry:
    def __init__(self):
        self._psi_scores: Dict[str, float] = {}
        self._lock = threading.Lock()

    def update_psi(self, feature: str, psi: float):
        with self._lock:
            self._psi_scores[feature] = psi

    def get_psi(self, feature: str) -> float:
        with self._lock:
            return self._psi_scores.get(feature, 0.0)

    def alert_if_drifted(self, threshold: float = 0.2) -> List[str]:
        drifted = []
        with self._lock:
            for feature, psi in self._psi_scores.items():
                if psi > threshold:
                    drifted.append(feature)
        if drifted:
            log.warning(f"DriftTelemetry: PSI drift detected on {drifted}")
        return drifted


class ReplayEngine:
    def __init__(self, db):
        self.db = db

    async def replay_events(self, start_ts: float, end_ts: float) -> List[Dict[str, Any]]:
        try:
            rows = await self.db.fetchall(
                "SELECT timestamp, event_type, payload FROM events WHERE timestamp >= ? AND timestamp <= ? ORDER BY timestamp",
                (start_ts, end_ts),
            )
            events = []
            for row in rows:
                try:
                    payload = json.loads(row["payload"])
                    events.append(
                        {
                            "timestamp": row["timestamp"],
                            "event_type": row["event_type"],
                            "payload": payload,
                        }
                    )
                except Exception:
                    continue
            log.info(f"ReplayEngine: replayed {len(events)} events")
            return events
        except Exception as e:
            log.warning(f"ReplayEngine failed: {e}")
            return []


class EdgeDecayTracker:
    def __init__(self, window: int = 50, decay_threshold: float = 0.5):
        self.window = window
        self.decay_threshold = decay_threshold
        self._edges: List[Dict[str, float]] = []
        self._lock = threading.Lock()

    def record(self, expected_edge: float, realized_edge: float):
        with self._lock:
            self._edges.append(
                {
                    "expected": expected_edge,
                    "realized": realized_edge,
                    "ts": time.time(),
                }
            )
            if len(self._edges) > self.window:
                self._edges = self._edges[-self.window :]

    def check_decay(self) -> bool:
        with self._lock:
            if len(self._edges) < 10:
                return False
            recent = self._edges[-self.window :]
            avg_expected = np.mean([e["expected"] for e in recent])
            avg_realized = np.mean([e["realized"] for e in recent])
            if avg_expected <= 1e-9:
                return False
            ratio = avg_realized / avg_expected
            decayed = ratio < self.decay_threshold
            if decayed:
                log.warning(
                    f"EdgeDecayTracker: DECAY DETECTED. Realized/Expected={ratio:.2%} < {self.decay_threshold:.0%}"
                )
            return decayed

    def summary(self) -> Dict[str, float]:
        with self._lock:
            if not self._edges:
                return {}
            recent = self._edges[-self.window :]
            return {
                "avg_expected_edge": float(np.mean([e["expected"] for e in recent])),
                "avg_realized_edge": float(np.mean([e["realized"] for e in recent])),
                "decay_ratio": float(
                    np.mean([e["realized"] for e in recent])
                    / max(np.mean([e["expected"] for e in recent]), 1e-9)
                ),
            }


# ======================================================================
# ADAPTIVE INTELLIGENCE LAYER
# ----------------------------------------------------------------------
# Hardened for the worst real-world conditions:
#   * hardest / lowest-liquidity leagues
#   * multiple successive upsets
#   * long stretches of little or no information
#   * market-wide "hard times" (crashes, pandemics, structural breaks)
# All math is self-contained and degrades gracefully when optional libs
# are missing. Everything is written into this single file.
# ======================================================================
import math as _math
from collections import defaultdict as _defaultdict

# ----- tunables (env-overridable) ---------------------------------------
# Tuned per the LHM Backtest Loss Analysis & Gap Closure Plan:
#   * shrink harder toward the market when information is thin
#   * allow stronger upset correction when sharp money diverges
#   * sharper regime response + earlier crisis de-leverage
_AI_ENABLE = os.environ.get("LHM_AI_ENABLE", "1") == "1"
_AI_SPARSE_SHRINK = float(os.environ.get("LHM_AI_SPARSE_SHRINK", "0.70"))
_AI_UPSET_CAP = float(os.environ.get("LHM_AI_UPSET_CAP", "0.24"))
_AI_REGIME_SHOCK = float(os.environ.get("LHM_AI_REGIME_SHOCK", "2.8"))
_AI_CRISIS_MAX_DD = float(os.environ.get("LHM_AI_CRISIS_MAX_DD", "0.15"))
_AI_CAL_N = int(os.environ.get("LHM_AI_CAL_N", "240"))
_AI_MIN_INFO_CONF = float(os.environ.get("LHM_AI_MIN_INFO_CONF", "0.12"))
_AI_LOWINFO_CONF = float(os.environ.get("LHM_AI_LOWINFO_CONF", "0.45"))
_AI_DRAW_PARITY_BOOST = float(os.environ.get("LHM_AI_DRAW_PARITY_BOOST", "0.06"))
_AI_UPSET_SHARP_BONUS = float(os.environ.get("LHM_AI_UPSET_SHARP_BONUS", "0.12"))
_AI_SNAPSHOT_PATH = os.environ.get("LHM_AI_SNAPSHOT", "backups/ai_regime_snapshot.json")


def _ai_clip(x, lo, hi):
    return max(lo, min(hi, x))


def _ai_norm3(ph, pd_, pa):
    ph, pd_, pa = float(ph), float(pd_), float(pa)
    s = max(1e-9, ph + pd_ + pa)
    ph, pd_, pa = ph / s, pd_ / s, pa / s
    ph = _ai_clip(ph, 0.005, 0.99)
    pa = _ai_clip(pa, 0.005, 0.99)
    pd_ = _ai_clip(pd_, 0.005, 0.99)
    s = max(1e-9, ph + pd_ + pa)
    return ph / s, pd_ / s, pa / s


def _ai_market_implied(match_row):
    """Wisdom-of-the-crowd prior from closing odds (best estimator when OUR
    information is thin). De-overrounded so probabilities sum to 1."""
    oh = match_row.get("odds_home") or match_row.get("closing_odds", {}).get("home")
    od = match_row.get("odds_draw") or match_row.get("closing_odds", {}).get("draw")
    oa = match_row.get("odds_away") or match_row.get("closing_odds", {}).get("away")
    try:
        oh, od, oa = float(oh), float(od), float(oa)
        if min(oh, od, oa) <= 1.0:
            return None
        inv = (1.0 / oh, 1.0 / od, 1.0 / oa)
        return _ai_norm3(*inv)
    except (TypeError, ValueError):
        return None


def _ai_sigmoid(x):
    try:
        return 1.0 / (1.0 + _math.exp(-x))
    except OverflowError:
        return 0.0 if x < 0 else 1.0


class SparseInformationHandler:
    """Empirical-Bayes style handling of matches with little data.

    When our own signals are scarce we (a) measure how little we know and
    (b) shrink our probability estimate toward the market-consensus prior,
    which is far more reliable in low-information regimes than a model fit
    on thin data.
    """

    _SIGNAL_KEYS = (
        "home_xg", "away_xg", "form_home", "form_away",
        "h2h_home_win_rate", "h2h_avg_goals", "league_volatility",
        "injury_count", "lineups", "last5_home", "last5_away",
        "referee_id", "closing_odds",
    )

    @staticmethod
    def _has_full_odds(match_row):
        keys = ("odds_home", "odds_draw", "odds_away")
        if all(isinstance(match_row.get(k), (int, float)) and math.isfinite(float(match_row.get(k))) for k in keys):
            return True
        co = match_row.get("closing_odds")
        if isinstance(co, dict) and all(k in co for k in ("home", "draw", "away")):
            return True
        return False

    @staticmethod
    def _staleness_penalty(match_row):
        """Gap-closure: penalise confidence when the underlying signals are
        stale. Stale xG/form must not be allowed to dominate the live market
        prior, so we reduce the effective signal count and let the model
        defer to the consensus odds instead."""
        penalty = 0.0
        age_h = match_row.get("data_age_hours")
        if age_h is None:
            oas = match_row.get("odds_age_seconds")
            if isinstance(oas, (int, float)):
                age_h = float(oas) / 3600.0
        if isinstance(age_h, (int, float)) and math.isfinite(float(age_h)):
            penalty += _ai_clip((float(age_h) - 6.0) / 42.0, 0.0, 1.0)
        fad = match_row.get("form_age_days")
        if isinstance(fad, (int, float)) and math.isfinite(float(fad)):
            penalty += _ai_clip((float(fad) - 7.0) / 21.0, 0.0, 1.0)
        dsl = match_row.get("days_since_last_home") or match_row.get("days_since_last")
        if isinstance(dsl, (int, float)) and math.isfinite(float(dsl)):
            penalty += _ai_clip((float(dsl) - 10.0) / 20.0, 0.0, 0.8)
        # live enrichment restores confidence (Gap-closure: live enrichment)
        if match_row.get("live_enriched") or match_row.get("research_confidence"):
            penalty = max(0.0, penalty - 0.5)
        return _ai_clip(penalty, 0.0, 2.5)

    def information_confidence(self, match_row):
        present = 0
        for k in self._SIGNAL_KEYS:
            v = match_row.get(k)
            if v is None:
                continue
            if isinstance(v, (int, float)) and (not math.isfinite(float(v)) or float(v) == 0.0):
                continue
            if isinstance(v, (list, dict, str)) and len(v) == 0:
                continue
            present += 1
        # Market odds coverage is itself a strong informational signal:
        # when little else is known we can still defer to the wisdom of crowds.
        if self._has_full_odds(match_row):
            present += 1
        # Stale data erodes confidence (defer to the market when old).
        effective = max(0.0, present - self._staleness_penalty(match_row))
        # 0 -> ~0.0, 3 -> ~0.78, 6+ -> ~0.95  (diminishing returns)
        conf = 1.0 - _math.exp(-0.55 * effective)
        return _ai_clip(conf, 0.0, 0.99)

    def shrink_toward_market(self, probs3, market3, info_conf):
        if market3 is None:
            return probs3
        w = _ai_clip(info_conf * _AI_SPARSE_SHRINK, 0.0, 0.97)
        # Gap-closure fix #1: when we genuinely know little (< low-info
        # threshold) shrink even harder toward the wisdom-of-crowds prior so
        # a thin-data model cannot dominate the market estimate.
        if info_conf < _AI_LOWINFO_CONF:
            w *= _ai_clip(info_conf / _AI_LOWINFO_CONF, 0.05, 1.0)
        w = _ai_clip(w, 0.0, 0.97)
        ph = w * probs3[0] + (1.0 - w) * market3[0]
        pd_ = w * probs3[1] + (1.0 - w) * market3[1]
        pa = w * probs3[2] + (1.0 - w) * market3[2]
        return _ai_norm3(ph, pd_, pa)


class UpsetModel:
    """Respects upsets. In low-information and high-regime-risk contexts a
    dominant favourite is far more likely to be upset, so we bleed
    probability from the favourite into the draw and the underdog. The
    transfer is bounded so the model never becomes reckless.
    """

    def upset_index(self, gap, info_conf, regime_risk, sharp_divergence=0.0):
        g = _ai_clip(abs(gap), 0.0, 0.5)
        # Gap-closure fix #3: when sharp money diverges from the public line
        # (or public hype on the favourite is high) upsets become materially
        # more likely, so raise the effective transfer strength.
        sharp_bonus = _ai_clip(abs(sharp_divergence) * _AI_UPSET_SHARP_BONUS, 0.0, _AI_UPSET_SHARP_BONUS)
        return g * (1.0 - info_conf) * (0.3 + regime_risk + sharp_bonus)

    def effective_cap(self, sharp_divergence=0.0):
        # Gap-closure fix #3: dynamically widen the cap under sharp divergence.
        return _AI_UPSET_CAP + _ai_clip(abs(sharp_divergence) * _AI_UPSET_SHARP_BONUS, 0.0, _AI_UPSET_SHARP_BONUS)

    def draw_parity_boost(self, probs3, total_xg, form_parity):
        """Gap-closure fix #4: draws are chronically under-estimated in tight,
        low-scoring matches. When total expected goals are low and the two
        teams are in form parity, bleed a bounded amount into the draw.
        """
        if total_xg >= 2.2 or form_parity < 0.5:
            return probs3
        ph, pd_, pa = probs3
        boost = _ai_clip(_AI_DRAW_PARITY_BOOST * (1.0 - _ai_clip((total_xg - 1.0) / 1.2, 0.0, 1.0)), 0.0, _AI_DRAW_PARITY_BOOST)
        boost *= _ai_clip((form_parity - 0.5) / 0.5, 0.0, 1.0)
        if boost <= 0.0:
            return probs3
        # pull equally from favourite and underdog, add to draw
        side = ph if ph >= pa else pa
        if ph >= pa:
            ph -= boost * 0.5
            pa -= boost * 0.5
        else:
            pa -= boost * 0.5
            ph -= boost * 0.5
        pd_ += boost
        return _ai_norm3(ph, pd_, pa)

    def adjust(self, probs3, gap, info_conf, regime_risk, sharp_divergence=0.0):
        ph, pd_, pa = probs3
        cap = self.effective_cap(sharp_divergence)
        boost = _ai_clip(self.upset_index(gap, info_conf, regime_risk, sharp_divergence), 0.0, cap)
        if boost <= 0.0:
            return probs3
        if gap >= 0:  # home favourite -> protect against home upset
            to_draw = boost * 0.45
            to_away = boost * 0.55
            ph = ph - boost
            pd_ = pd_ + to_draw
            pa = pa + to_away
        else:         # away favourite
            to_draw = boost * 0.45
            to_home = boost * 0.55
            pa = pa - boost
            pd_ = pd_ + to_draw
            ph = ph + to_home
        return _ai_norm3(ph, pd_, pa)


class RegimeDetector:
    """Online, single-pass regime classifier. Tracks a per-league EWMA of
    goal/scoring volatility plus a global surprise EWMA. The hardest leagues
    (high, persistent volatility) thus raise regime_risk and throttle
    exposure. Returns regime_risk in [0,1] (1 = most dangerous: structural
    break / crisis league).
    """

    def __init__(self):
        self._vol = 0.5
        self._league_vol = _defaultdict(lambda: 0.5)
        self._surprise = 0.0
        self._surprise_fast = 0.0
        self._lock = threading.Lock()

    @staticmethod
    def _safe_vol(league_volatility, default=0.5):
        try:
            v = float(league_volatility)
            if not math.isfinite(v):
                return default
            return v
        except (TypeError, ValueError):
            return default

    def update(self, league_volatility, surprise=0.0, league=None):
        vol = _ai_clip(self._safe_vol(league_volatility), 0.0, 3.0)
        with self._lock:
            if league:
                cur = self._league_vol.get(league, 0.5)
                # Gap-closure fix #2: per-league volatility floor. Once a
                # league has shown real volatility it can never silently read
                # as "calm" again (prevents EWMA lag masking a tough league).
                self._league_vol[league] = max(0.5, 0.10 * vol + 0.90 * cur)
            self._vol = 0.05 * vol + 0.95 * self._vol
            if math.isfinite(surprise):
                self._surprise = 0.1 * abs(surprise) + 0.9 * self._surprise
                # fast surprise term reacts within a few matches
                self._surprise_fast = 0.35 * abs(surprise) + 0.65 * self._surprise_fast

    def snapshot(self, path):
        """Gap-closure: persist per-league volatility + shock state so the
        engine warm-starts (continuous learning across restarts/sessions)."""
        try:
            import json as _json
            payload = {
                "league_vol": dict(self._league_vol),
                "vol": self._vol,
                "surprise": self._surprise,
                "surprise_fast": self._surprise_fast,
            }
            _dir = os.path.dirname(path)
            if _dir:
                os.makedirs(_dir, exist_ok=True)
            with open(path, "w", encoding="utf-8") as f:
                _json.dump(payload, f)
        except Exception:
            pass

    def load_snapshot(self, path):
        try:
            import json as _json
            if not os.path.exists(path):
                return
            with open(path, "r", encoding="utf-8") as f:
                d = _json.load(f)
            self._league_vol.update({k: float(v) for k, v in d.get("league_vol", {}).items()})
            self._vol = float(d.get("vol", self._vol))
            self._surprise = float(d.get("surprise", 0.0))
            self._surprise_fast = float(d.get("surprise_fast", 0.0))
        except Exception:
            pass

    def _vol_for(self, league):
        if league and league in self._league_vol:
            return self._league_vol[league]
        return self._vol

    def risk_multiplier(self, league=None):
        with self._lock:
            v = self._vol_for(league)
            shock = _ai_clip(max(self._surprise, self._surprise_fast), 0.0, 1.0)
        # Gap-closure fix #2: sharper response + stronger shock influence
        base = _ai_sigmoid((v - 0.55) * _AI_REGIME_SHOCK)
        return _ai_clip(0.6 * base + 0.4 * shock, 0.0, 1.0)

    def regime(self, league=None):
        with self._lock:
            v = self._vol_for(league)
        if v > 0.9:
            return "crisis"
        if v > 0.7:
            return "volatile"
        if v > 0.45:
            return "normal"
        return "calm"

    def read_only_risk(self):
        return self.risk_multiplier()


class CrisisDetector:
    """Drawdown + market-wide shock defence. In 'hard times' (deep drawdown
    or a run of bad shocks) it scales stakes down hard but never to a full
    stop, so the engine can still recover on the rare high-edge spots.
    """

    def __init__(self):
        self._shock_ewma = 0.0
        self._lock = threading.Lock()

    def record_shock(self, negative_return):
        with self._lock:
            r = float(negative_return) if negative_return < 0 else 0.0
            self._shock_ewma = 0.15 * r + 0.85 * self._shock_ewma

    def update_drawdown(self, drawdown_fraction):
        with self._lock:
            dd = _ai_clip(float(drawdown_fraction), 0.0, 1.0)
            # smooth step: full size until 5% DD, then decays to ~0.1 by max DD
            lo, hi = 0.05, _AI_CRISIS_MAX_DD
            if dd <= lo:
                mult = 1.0
            elif dd >= hi:
                mult = 0.1
            else:
                mult = 1.0 - 0.9 * (dd - lo) / (hi - lo)
            # layer in market-wide shock signal
            mult *= _ai_clip(1.0 - self._shock_ewma * 0.5, 0.1, 1.0)
            return _ai_clip(mult, 0.05, 1.0)


class ConformalUncertainty:
    """Conformal-style uncertainty estimate per match: blends information
    deficit, regime risk, probability concentration (over-confidence in hard
    times) and a finite-sample calibration penalty (1/sqrt(n_cal)).
    """

    @staticmethod
    def estimate(probs3, info_conf, regime_risk, n_cal):
        ph, pd_, pa = probs3
        # normalized entropy in [0,1] (1 = maximally uncertain)
        ent = 0.0
        for p in (ph, pd_, pa):
            if p > 0:
                ent -= p * _math.log(p)
        ent /= _math.log(3.0)
        # Finite-sample calibration penalty: small and capped so that genuinely
        # high-confidence matches can fall below the 0.25 bet gate. (Earlier the
        # x3 factor floored uncertainty above 0.25 for EVERY match, silently
        # killing all bets.)
        cal_penalty = _ai_clip(1.0 / _math.sqrt(max(float(n_cal), 1.0)) * 1.2, 0.0, 0.10)
        unc = (
            0.45 * (1.0 - info_conf)
            + 0.30 * regime_risk
            + 0.15 * (1.0 - ent)
            + cal_penalty
        )
        return _ai_clip(unc, 0.0, 1.0)


class AdversarialStressTest:
    """Worst-case survival gate. Assumes, under stress, that our edge over
    the market shrinks by the uncertainty fraction. If the stressed edge is
    non-positive the bet is killed; otherwise the stake is scaled by the
    survivimg fraction times crisis & regime multipliers.
    """

    @staticmethod
    def stress_decision(decision, uncertainty, regime_risk, crisis_mult):
        try:
            odds = float(getattr(decision, "odds", 0.0) or 0.0)
            if odds <= 1.0:
                return 0.0
            base_edge = float(getattr(decision, "edge", 0.0) or 0.0)
            if base_edge <= 0.0:
                return 0.0
            prob = float(getattr(decision, "prob", 0.0) or 0.0)
            breakeven = 1.0 / odds
            stressed_prob = prob * (1.0 - uncertainty) + breakeven * uncertainty
            stressed_edge = stressed_prob - breakeven
            if stressed_edge <= 0.0:
                return 0.0
            surv = _ai_clip(stressed_edge / max(base_edge, 1e-9), 0.0, 1.0)
            surv *= float(crisis_mult)
            surv *= _ai_clip(1.0 - regime_risk * 0.4, 0.2, 1.0)
            return _ai_clip(surv, 0.0, 1.0)
        except Exception:
            return 0.5  # fail conservative, never silently full-size


# ======================================================================
# REAL-WORLD FRICTION LAYER
# ----------------------------------------------------------------------
# Fixes the backtest's misleading optimism. Real markets charge commission,
# slip on execution, limit winning accounts, and never offer systematic
# large edges. These classes make the engine (and any backtest using it)
# honest about those frictions.
# ======================================================================
class TransactionCostModel:
    """Net PnL after exchange commission (on winnings only) and slippage."""

    @staticmethod
    def net_odds(odds, slippage=0.0):
        return max(1.0001, float(odds) * (1.0 - max(0.0, float(slippage))))

    @staticmethod
    def settle(stake, odds, won, commission=0.0, slippage=0.0):
        stake = float(stake)
        if stake <= 0:
            return 0.0
        eff_odds = TransactionCostModel.net_odds(odds, slippage)
        if not won:
            return -stake
        gross_profit = stake * (eff_odds - 1.0)
        return gross_profit * (1.0 - max(0.0, float(commission)))


class AccountLimitModel:
    """Realistic bookmaker behaviour: after a few bets (or a daily stake
    ceiling) the account is 'limited' and accepted stake collapses toward 0.
    Returned multiplier scales the intended stake."""

    def __init__(self, daily_limit=None, limit_after_bets=None):
        self.daily_limit = float(daily_limit if daily_limit is not None else CONFIG.bookmaker_daily_limit)
        self.limit_after_bets = int(limit_after_bets if limit_after_bets is not None else CONFIG.bookmaker_limit_bets)
        self._used = 0.0
        self._bets = 0
        self._lock_until = 0.0
        self._lock = threading.Lock()

    def accept_stake(self, intended_stake, now=None):
        with self._lock:
            now = float(now if now is not None else time.time())
            if now < self._lock_until:
                return 0.0
            self._bets += 1
            # cumulative stake this "day" exceeds the ceiling -> limited
            if self._used + intended_stake > self.daily_limit:
                self._lock_until = now + 86400.0
                return 0.0
            # after N bets the book flags the account: scale down hard
            if self._bets > self.limit_after_bets:
                return 0.0
            # linear ramp-down in the approach to the limit bet
            room = max(0.0, self.daily_limit - self._used)
            allowed = min(intended_stake, room)
            self._used += allowed
            return allowed

    def reset_day(self, now=None):
        with self._lock:
            self._used = 0.0
            self._bets = 0
            self._lock_until = 0.0


class MarketEfficiencyGuard:
    """Edges above a realistic ceiling are stale/low-liquidity artefacts, not
    alpha. Cap the edge we actually act on so the engine never 'banks' a
    phantom 9% edge."""

    def __init__(self, max_edge=None):
        self.max_edge = float(max_edge if max_edge is not None else CONFIG.max_realistic_edge)

    def effective_edge(self, edge):
        return _ai_clip(float(edge), -1.0, self.max_edge)

    def is_suspicious(self, edge):
        return float(edge) > self.max_edge


class DataQualityInjector:
    """Inject the messiness of real data into a clean synthetic match so the
    self-repair backtest tests robustness instead of memorising the generator.
    Returns a new dict (does not mutate input)."""

    _FIELDS = ("home_xg", "away_xg", "odds_home", "odds_draw", "odds_away")

    def __init__(self, missing_rate=0.18, noise=0.12, swap_rate=0.04, rng_seed=7):
        self.missing_rate = missing_rate
        self.noise = noise
        self.swap_rate = swap_rate
        self._rng = random.Random(rng_seed)

    def inject(self, match: Dict[str, Any]) -> Dict[str, Any]:
        m = dict(match)
        for f in self._FIELDS:
            if self._rng.random() < self.missing_rate:
                m.pop(f, None)
            elif isinstance(m.get(f), (int, float)):
                m[f] = float(m[f]) * (1.0 + self._rng.uniform(-self.noise, self.noise))
        # occasional corrupted / nonsensical value
        if self._rng.random() < 0.05:
            m[self._rng.choice(self._FIELDS)] = self._rng.choice([-1.0, 0.0, 999.0, "n/a"])
        # occasional result swap (data entry error)
        if self._rng.random() < self.swap_rate:
            m["home_goals"], m["away_goals"] = m.get("away_goals", 0), m.get("home_goals", 0)
        return m


# Expose ready-made singletons so callers don't re-instantiate per match.
_TX_COST = TransactionCostModel()
_ACC_LIMIT = AccountLimitModel()
_EFF_GUARD = MarketEfficiencyGuard()
_DATA_INJECTOR = DataQualityInjector()


def backtest_settle(stake, odds, won, commission=None, slippage=None,
                    account=None, edge=None):
    """One helper that applies ALL real-world frictions for a settled bet:
    market-efficiency edge cap, slippage, commission, and account limits.
    Returns (net_pnl, accepted_stake)."""
    commission = CONFIG.backtest_commission if commission is None else commission
    slippage = CONFIG.execution_slippage if slippage is None else slippage
    if edge is not None:
        edge = _EFF_GUARD.effective_edge(edge)
    accepted = float(stake)
    if account is not None:
        accepted = account.accept_stake(accepted)
    pnl = _TX_COST.settle(accepted, odds, won, commission, slippage)
    return pnl, accepted


class AdaptiveIntelligence:
    """Singleton orchestrator tying the above together. Safe to call from
    anywhere in the file at runtime (defined at module bottom)."""

    _instance = None
    _lock = threading.Lock()

    def __new__(cls):
        with cls._lock:
            if cls._instance is None:
                cls._instance = super().__new__(cls)
                cls._instance._init()
            return cls._instance

    def _init(self):
        self.sparse = SparseInformationHandler()
        self.upset = UpsetModel()
        self.regime = RegimeDetector()
        self.crisis = CrisisDetector()
        self.conformal = ConformalUncertainty()
        self.stress = AdversarialStressTest()
        self.n_cal = _AI_CAL_N
        self.enabled = _AI_ENABLE
        self._log_once = False
        self._last_league = None
        self._bayes_updater = None
        self._team_resolver = None
        self._settle_count = 0
        # Gap-closure: warm start from a persisted regime snapshot - disabled
        try:
            pass
        except Exception:
            pass

    def save_snapshot(self):
        try:
            pass
        except Exception:
            pass

    @classmethod
    def is_ready(cls):
        return _AI_ENABLE

    def feature_contributions(self, fixture_id, match_row):
        """Lightweight feature injection for FeatureEngine._apply_upgrades."""
        if not self.enabled:
            return {}
        info_conf = self.sparse.information_confidence(match_row)
        league = match_row.get("league") or match_row.get("competition")
        regime_risk = self.regime.risk_multiplier(league)
        mkt = _ai_market_implied(match_row)
        gap = 0.0
        if mkt is not None:
            gap = (float(match_row.get("home_xg", 1.2)) - float(match_row.get("away_xg", 1.0)))
        upset_idx = self.upset.upset_index(gap, info_conf, regime_risk)
        return {
            "ai_info_conf": info_conf,
            "ai_regime_risk": regime_risk,
            "ai_upset_index": upset_idx,
            "ai_market_lean": (mkt[0] - mkt[2]) if mkt else 0.0,
        }

    def process(self, match_row, probs3, bankroll, state):
        ph, pd_, pa = _ai_norm3(*probs3)
        if not self.enabled:
            return {
                "probs": (ph, pd_, pa), "uncertainty": 0.0, "regime_risk": 0.0,
                "crisis_mult": 1.0, "info_conf": 0.5, "regime": self.regime.regime(),
            }
        if not self._log_once:
            self._log_once = True
            log.info("AdaptiveIntelligence layer active (sparse/upset/regime/crisis/conformal).")

        league = match_row.get("league") or match_row.get("competition")
        self._last_league = league
        info_conf = self.sparse.information_confidence(match_row)
        market3 = _ai_market_implied(match_row)
        ph, pd_, pa = self.sparse.shrink_toward_market((ph, pd_, pa), market3, info_conf)

        # sharp-money divergence proxies (optional, from live feed / CLV tracker)
        sharp_div = float(match_row.get("sharp_divergence", 0.0) or 0.0)
        sharp_div = max(sharp_div, float(match_row.get("clv_divergence", 0.0) or 0.0))

        self.regime.update(match_row.get("league_volatility"), 0.0, league)
        regime_risk = self.regime.risk_multiplier(league)
        regime_name = self.regime.regime(league)

        gap = ph - pa
        ph, pd_, pa = self.upset.adjust((ph, pd_, pa), gap, info_conf, regime_risk, sharp_div)
        # Gap-closure fix #4: draw parity boost (tight, low-scoring matches)
        total_xg = float(match_row.get("home_xg", 1.2) or 1.2) + float(match_row.get("away_xg", 1.0) or 1.0)
        fh = float(match_row.get("form_home", 0.5) or 0.5)
        fa = float(match_row.get("form_away", 0.5) or 0.5)
        form_parity = 1.0 - min(1.0, abs(fh - fa))
        ph, pd_, pa = self.upset.draw_parity_boost((ph, pd_, pa), total_xg, form_parity)

        # Gap-closure (AdaptiveIntelligence enhancements): continent/league
        # specific home-advantage priors. Some leagues (e.g. African/CAF)
        # exhibit a much stronger home bias than the European top-5, so we
        # shift a bounded amount of probability from away/draw to the home
        # side, scaled down when regime risk is high (don't override the
        # market in uncertain times).
        home_boost = self._league_home_boost(league) * (1.0 - 0.5 * regime_risk)
        if home_boost > 0.0:
            take = _ai_clip(home_boost, 0.0, min(max(pa, 0.0), max(pd_, 0.0)))
            ph += take
            pa -= take * 0.6
            pd_ -= take * 0.4
            ph, pd_, pa = _ai_norm3(ph, pd_, pa)

        peak = float((state or {}).get("peak_bankroll", bankroll) or bankroll)
        dd = max(0.0, (peak - float(bankroll or peak)) / max(peak, 1e-9))
        crisis_mult = self.crisis.update_drawdown(dd)

        uncertainty = self.conformal.estimate((ph, pd_, pa), info_conf, regime_risk, self.n_cal)

        return {
            "probs": (ph, pd_, pa),
            "uncertainty": uncertainty,
            "regime_risk": regime_risk,
            "crisis_mult": crisis_mult,
            "info_conf": info_conf,
            "regime": regime_name,
        }

    @staticmethod
    def _league_home_boost(league):
        """Return a bounded home-advantage boost [0, 0.06] per league/continent.
        Strongest for African/CAF leagues, moderate for AFC, default for the
        European majors, slightly elevated for lower/obscure leagues."""
        if not league:
            return 0.02
        s = str(league).lower()
        if any(k in s for k in ("caf", "africa", "african", "nigeria", "egypt", "morocc",
                                "south africa", "ghana", "tunis", "alger", "ethiop", "kenya",
                                "cameroon", "senegal", "ivory", "mali", "zambia", "congo")):
            return 0.06
        if any(k in s for k in ("afc", "asia", "japan", "korea", "china", "india",
                                "thai", "viet", "saudi", "uae", "qatar", "iran", "iraq")):
            return 0.035
        if any(k in s for k in ("conmebol", "libertadores", "brasil", "brazil", "argent",
                                "chile", "colomb", "uruguay", "peru", "ecuador")):
            return 0.03
        if any(k in s for k in ("mls", "usa", "mexic", "concacaf")):
            return 0.03
        # European majors + rest: modest baseline home advantage
        return 0.02

    def stress_decision(self, decision, uncertainty, regime_risk, crisis_mult):
        return self.stress.stress_decision(decision, uncertainty, regime_risk, crisis_mult)

    def register_bayesian_updater(self, updater, team_resolver=None):
        """Gap-closure: hook the production BayesianPoissonModel (or a
        RecursiveBayesianUpdater) so every settled bet refines team strength.
        `team_resolver(fixture_id) -> (home_team, away_team, is_home_dict)`."""
        try:
            self._bayes_updater = updater
            self._team_resolver = team_resolver
        except Exception:
            pass

    def record_outcome(self, fixture_id, expected_goals, actual_goals, won, stake, pnl,
                       home_team=None, away_team=None):
        """Online learning hook: update regime surprise + crisis shock from
        settled results, and feed the Bayesian updater so team strengths
        adapt after every bet (Gap-closure: 'Bayesian updater on every
        settled bet'). Optional; safe to call from settlement code."""
        try:
            surprise = float(actual_goals - expected_goals)
            self.regime.update(self.regime._vol, surprise, self._last_league)
            if pnl is not None and stake:
                ret = float(pnl) / max(float(stake), 1e-9)
                self.crisis.record_shock(ret)
            upd = getattr(self, "_bayes_updater", None)
            if upd is not None and home_team is not None and away_team is not None:
                try:
                    if hasattr(upd, "update"):
                        upd.update(str(home_team), int(round(actual_goals * 0.5)), int(round(actual_goals * 0.5)), True)
                        upd.update(str(away_team), int(round(actual_goals * 0.5)), int(round(actual_goals * 0.5)), False)
                    elif callable(upd):
                        upd(home_team, away_team, actual_goals, won)
                except Exception:
                    pass
            # persist warm snapshot every 25 settled bets (continuity) - disabled
            self._settle_count = getattr(self, "_settle_count", 0) + 1
            if self._settle_count % 25 == 0:
                pass  # snapshot disabled
        except Exception:
            pass


_AI = AdaptiveIntelligence()


