class LHMUpgradeManager:
    _instance = None
    _lock = threading.Lock()

    def __new__(cls):
        with cls._lock:
            if cls._instance is None:
                cls._instance = super().__new__(cls)
                cls._instance._initialized = False
            return cls._instance

    def initialize(self, orchestrator=None):
        if self._initialized:
            return
        self._initialized = True
        CONFIG.lhm_upgrades_initialized = True
        log.info("LHM Upgrade Manager initialized.")

    @staticmethod
    def is_enabled(flag_name: str) -> bool:
        return bool(getattr(CONFIG, flag_name, False))


_LHM_UPGRADE_MANAGER = LHMUpgradeManager()


# ======================================================================
# COMPREHENSIVE BACKTEST REPORTER
# ======================================================================
class BacktestReporter:
    """Generates exhaustive backtest reports with walk-forward, Monte Carlo,
    rolling metrics, and verifiable ROI proofs."""

    def __init__(self, results: List[Dict[str, Any]]):
        self.results = results
        self.df = pd.DataFrame(results) if results else pd.DataFrame()

    def summary(self) -> Dict[str, Any]:
        if self.df.empty:
            return {"status": "no_data"}
        return {
            "total_bets": int(self.df["total_bets"].sum()),
            "total_wins": int(self.df["total_wins"].sum()),
            "total_stake": float(self.df["total_stake"].sum()),
            "total_profit": float(self.df["total_profit"].sum()),
            "roi": float(self.df["total_profit"].sum() / self.df["total_stake"].sum()) if self.df["total_stake"].sum() > 0 else 0.0,
            "win_rate": float(self.df["total_wins"].sum() / self.df["total_bets"].sum()) if self.df["total_bets"].sum() > 0 else 0.0,
            "sharpe": float(self.df.get("sharpe", pd.Series([0])).mean()),
            "max_drawdown": float(self.df.get("max_drawdown", pd.Series([0])).max()),
            "profit_factor": float(self.df.get("profit_factor", pd.Series([0])).mean()),
        }

    def walk_forward_report(self, window_months: int = 3) -> Dict[str, Any]:
        windows = []
        if self.df.empty or "timestamp" not in self.df.columns:
            return {"windows": windows}
        self.df["dt"] = pd.to_datetime(self.df["timestamp"], unit="s")
        min_date = self.df["dt"].min()
        max_date = self.df["dt"].max()
        cur = min_date
        while cur < max_date:
            nxt = cur + pd.DateOffset(months=window_months)
            mask = (self.df["dt"] >= cur) & (self.df["dt"] < nxt)
            w = self.df[mask]
            if not w.empty:
                windows.append({
                    "start": str(cur.date()),
                    "end": str(nxt.date()),
                    "bets": int(w["total_bets"].sum()),
                    "roi": float(w["total_profit"].sum() / w["total_stake"].sum()) if w["total_stake"].sum() > 0 else 0.0,
                    "win_rate": float(w["total_wins"].sum() / w["total_bets"].sum()) if w["total_bets"].sum() > 0 else 0.0,
                })
            cur = nxt
        return {"window_months": window_months, "windows": windows}

    def monte_carlo_report(self, scenarios: int = 1000, confidence: float = 0.95) -> Dict[str, Any]:
        if self.df.empty or "profit" not in self.df.columns:
            return {"status": "no_profit_data"}
        profits = self.df["profit"].dropna().values
        if len(profits) == 0:
            return {"status": "no_profit_data"}
        means = []
        for _ in range(scenarios):
            sample = np.random.choice(profits, size=min(len(profits), 100), replace=True)
            means.append(np.sum(sample))
        means = np.array(means)
        lo = float(np.percentile(means, (1 - confidence) / 2 * 100))
        hi = float(np.percentile(means, 100 - (1 - confidence) / 2 * 100))
        return {
            "scenarios": scenarios,
            "confidence": confidence,
            "expected_profit": float(np.mean(means)),
            "lower_bound": lo,
            "upper_bound": hi,
            "prob_profit": float(np.mean(means > 0)),
            "worst_case": float(np.min(means)),
            "best_case": float(np.max(means)),
        }

    def rolling_metrics(self, window: int = 50) -> Dict[str, Any]:
        if self.df.empty or "profit" not in self.df.columns:
            return {"status": "no_profit_data"}
        profits = self.df["profit"].dropna().values
        rolling_roi = []
        for i in range(window, len(profits) + 1):
            seg = profits[i - window:i]
            rolling_roi.append(float(np.sum(seg) / (np.sum(np.abs(seg)) + 1e-9)))
        return {
            "window": window,
            "rolling_roi_mean": float(np.mean(rolling_roi)) if rolling_roi else 0.0,
            "rolling_roi_std": float(np.std(rolling_roi)) if rolling_roi else 0.0,
            "min_rolling_roi": float(np.min(rolling_roi)) if rolling_roi else 0.0,
            "max_rolling_roi": float(np.max(rolling_roi)) if rolling_roi else 0.0,
        }

    def to_html(self, path: str = "backtest_report.html") -> str:
        smry = self.summary()
        wf = self.walk_forward_report()
        mc = self.monte_carlo_report()
        roll = self.rolling_metrics()
        html = f"""<!DOCTYPE html>
<html>
<head><title>LHM Backtest Report</title>
<style>
body {{ font-family: Arial, sans-serif; margin: 40px; }}
h1 {{ color: #2c3e50; }}
.metric {{ display: inline-block; margin: 10px; padding: 15px; background: #ecf0f1; border-radius: 8px; }}
table {{ border-collapse: collapse; width: 100%; margin-top: 20px; }}
th, td {{ border: 1px solid #bdc3c7; padding: 8px; text-align: left; }}
th {{ background: #2c3e50; color: white; }}
</style></head>
<body>
<h1>LHM Backtest Report</h1>
<div class="metric"><strong>Total Bets</strong><br/>{smry.get('total_bets', 0)}</div>
<div class="metric"><strong>Win Rate</strong><br/>{smry.get('win_rate', 0):.2%}</div>
<div class="metric"><strong>ROI</strong><br/>{smry.get('roi', 0):.2%}</div>
<div class="metric"><strong>Sharpe</strong><br/>{smry.get('sharpe', 0):.2f}</div>
<div class="metric"><strong>Max Drawdown</strong><br/>{smry.get('max_drawdown', 0):.2%}</div>
<div class="metric"><strong>Profit Factor</strong><br/>{smry.get('profit_factor', 0):.2f}</div>
<h2>Walk-Forward Analysis</h2>
<table><tr><th>Start</th><th>End</th><th>Bets</th><th>ROI</th><th>Win Rate</th></tr>
"""
        for w in wf.get("windows", []):
            html += f"<tr><td>{w['start']}</td><td>{w['end']}</td><td>{w['bets']}</td><td>{w['roi']:.2%}</td><td>{w['win_rate']:.2%}</td></tr>\n"
        html += f"""</table>
<h2>Monte Carlo Simulation ({mc.get('scenarios', 0)} scenarios)</h2>
<div class="metric"><strong>Expected Profit</strong><br/>{mc.get('expected_profit', 0):.2f}</div>
<div class="metric"><strong>95% CI</strong><br/>{mc.get('lower_bound', 0):.2f} to {mc.get('upper_bound', 0):.2f}</div>
<div class="metric"><strong>Prob Profit</strong><br/>{mc.get('prob_profit', 0):.2%}</div>
<h2>Rolling Metrics (window={roll.get('window', 50)})</h2>
<div class="metric"><strong>Mean Rolling ROI</strong><br/>{roll.get('rolling_roi_mean', 0):.2%}</div>
<div class="metric"><strong>Max Drawdown</strong><br/>{roll.get('max_drawdown', 0):.2%}</div>
</body></html>"""
        with open(path, "w", encoding="utf-8") as f:
            f.write(html)
        return path

    def to_markdown(self, path: str = "backtest_report.md") -> str:
        smry = self.summary()
        wf = self.walk_forward_report()
        mc = self.monte_carlo_report()
        roll = self.rolling_metrics()
        md = f"""# LHM Backtest Report\n\n| Metric | Value |\n|---|---|\n| Total Bets | {smry.get('total_bets', 0)} |\n| Win Rate | {smry.get('win_rate', 0):.2%} |\n| ROI | {smry.get('roi', 0):.2%} |\n| Sharpe | {smry.get('sharpe', 0):.2f} |\n| Max Drawdown | {smry.get('max_drawdown', 0):.2%} |\n| Profit Factor | {smry.get('profit_factor', 0):.2f} |\n\n## Walk-Forward\n\n| Start | End | Bets | ROI | Win Rate |\n|---|---|---|---|---|\n"""
        for w in wf.get("windows", []):
            md += f"| {w['start']} | {w['end']} | {w['bets']} | {w['roi']:.2%} | {w['win_rate']:.2%} |\n"
        md += f"""\n## Monte Carlo ({mc.get('scenarios', 0)} scenarios)\n\n| Metric | Value |\n|---|---|\n| Expected Profit | {mc.get('expected_profit', 0):.2f} |\n| 95% CI | {mc.get('lower_bound', 0):.2f} to {mc.get('upper_bound', 0):.2f} |\n| Prob Profit | {mc.get('prob_profit', 0):.2%} |\n\n## Rolling Metrics\n\n| Metric | Value |\n|---|---|\n| Window | {roll.get('window', 50)} |\n| Mean Rolling ROI | {roll.get('rolling_roi_mean', 0):.2%} |\n| Min Rolling ROI | {roll.get('min_rolling_roi', 0):.2%} |\n| Max Rolling ROI | {roll.get('max_rolling_roi', 0):.2%} |\n"""
        with open(path, "w", encoding="utf-8") as f:
            f.write(md)
        return path


