# FASTAPI SERVER
# ======================================================================
class APIServer:
    """Minimal HTTP API for predictions, backtest, and status."""

    def __init__(self, port: int = 8080):
        self.port = port
        self._app = None

    def create_app(self) -> Any:
        try:
            from fastapi import FastAPI
            from fastapi.responses import HTMLResponse, JSONResponse
        except ImportError:
            log.warning("FastAPI not installed. Install with: pip install fastapi uvicorn")
            return None

        app = FastAPI(title="LHM API", version="1.0.0")
        reporter = BacktestReporter([])

        @app.get("/health")
        async def health():
            return JSONResponse({"status": "ok", "model": "LHM", "version": "1.0.0"})

        @app.get("/backtest/report")
        async def backtest_report():
            return JSONResponse(reporter.summary())

        @app.get("/backtest/html")
        async def backtest_html():
            path = reporter.to_html()
            with open(path, "r", encoding="utf-8") as f:
                return HTMLResponse(f.read())

        @app.post("/predict")
        async def predict(payload: Dict[str, Any]):
            return JSONResponse({"prediction": "stub", "input": payload})

        self._app = app
        return app

    def run(self):
        app = self.create_app()
        if app is None:
            return
        try:
            import uvicorn
            uvicorn.run(app, host="0.0.0.0", port=self.port)
        except ImportError:
            log.warning("uvicorn not installed. Install with: pip install uvicorn")


