# ======================================================================
# PAPER TRADING SIMULATOR
# ======================================================================
class PaperTradingSimulator:
    """Runs live paper trading with real-time odds tracking."""

    def __init__(self, initial_bankroll: float = 1000.0):
        self.bankroll = initial_bankroll
        self.positions: List[Dict[str, Any]] = []
        self.history: List[Dict[str, Any]] = []
        self.running = False

    async def run(self, duration_hours: int = 24, interval_seconds: int = 60):
        self.running = True
        start = time.time()
        while self.running and (time.time() - start) < duration_hours * 3600:
            await asyncio.sleep(interval_seconds)
            self._tick()
        return self.summary()

    def _tick(self):
        pass

    def place_bet(self, fixture_id: str, market: str, outcome: str, odds: float, stake: float) -> Dict[str, Any]:
        pos = {
            "fixture_id": fixture_id,
            "market": market,
            "outcome": outcome,
            "odds": odds,
            "stake": stake,
            "timestamp": time.time(),
            "status": "open",
        }
        self.positions.append(pos)
        self.bankroll -= stake
        return pos

    def settle_bet(self, fixture_id: str, won: bool) -> Optional[Dict[str, Any]]:
        for pos in self.positions:
            if pos["fixture_id"] == fixture_id and pos["status"] == "open":
                profit = pos["stake"] * (pos["odds"] - 1) if won else -pos["stake"]
                pos["status"] = "settled"
                pos["profit"] = profit
                pos["settled_at"] = time.time()
                self.bankroll += pos["stake"] + profit
                self.history.append(pos)
                return pos
        return None

    def summary(self) -> Dict[str, Any]:
        settled = [p for p in self.history if p.get("status") == "settled"]
        total_profit = sum(p.get("profit", 0.0) for p in settled)
        wins = sum(1 for p in settled if p.get("profit", 0.0) > 0)
        return {
            "bankroll": self.bankroll,
            "open_positions": len([p for p in self.positions if p["status"] == "open"]),
            "total_settled": len(settled),
            "wins": wins,
            "total_profit": total_profit,
            "roi": total_profit / sum(p.get("stake", 0.0) for p in settled) if settled else 0.0,
        }


if __name__ == "__main__":
    asyncio.run(main())



