class _HumanBehaviorEngine:
    """Generates human-like timing distributions for mouse movements and keystrokes."""
    @staticmethod
    def lognormal_delay(mean: float = 0.0, sigma: float = 0.5) -> float:
        delay = _np.random.lognormal(mean=mean, sigma=sigma)
        return min(float(delay), 5.0)

    @staticmethod
    def bezier_curve(start, end, duration, num_points: int = 50):
        t = _np.linspace(0, 1, num_points)
        p0 = _np.array(start, dtype=float)
        p3 = _np.array(end, dtype=float)
        mid = (p0 + p3) / 2
        offset = _np.random.normal(0, 0.1, 2)
        p1 = mid + offset
        p2 = mid - offset
        points = []
        for ti in t:
            point = (1-ti)**3 * p0 + 3*(1-ti)**2 * ti * p1 + 3*(1-ti) * ti**2 * p2 + ti**3 * p3
            points.append((float(point[0]), float(point[1])))
        return points

    @staticmethod
    def add_micro_movements(x: int, y: int, intensity: float = 0.5):
        dx = int(_np.random.normal(0, intensity))
        dy = int(_np.random.normal(0, intensity))
        return x + dx, y + dy

    @staticmethod
    def generate_typing_pattern(text: str):
        delays = []
        for char in text:
            if char == ' ':
                delay = _np.random.uniform(0.1, 0.3)
            elif char in '.,!?':
                delay = _np.random.uniform(0.2, 0.5)
            elif char.isupper():
                delay = _np.random.uniform(0.1, 0.2)
            else:
                delay = _np.random.uniform(0.03, 0.08)
            if random.random() < 0.05:
                delay += _np.random.uniform(0.2, 0.8)
            delays.append(delay)
        return delays

