    async def navigate(self, url: str, wait_for_load: bool = True):
        if not self.page:
            return False
        try:
            await asyncio.sleep(_HumanBehaviorEngine.lognormal_delay(0.0, 0.3))
            response = await self.page.goto(url, wait_until="domcontentloaded", timeout=30000)
            if wait_for_load:
                await asyncio.sleep(_HumanBehaviorEngine.lognormal_delay(0.5, 0.4))
            return response.status == 200 if response else False
        except Exception as e:
            log.error(f"Navigation failed: {e}")
            return False

    async def get_page_content(self) -> str:
        if not self.page:
            return ""
        try:
            await self._human_scroll()
            await asyncio.sleep(_HumanBehaviorEngine.lognormal_delay(0.2, 0.3))
            return await self.page.content()
        except Exception as e:
            log.error(f"Failed to get page content: {e}")
            return ""

    async def _human_scroll(self):
        if not self.page:
            return
        try:
            height = await self.page.evaluate("document.body.scrollHeight")
            current = 0
            while current < height:
                scroll_amount = random.randint(100, 300)
                current += scroll_amount
                await self.page.evaluate(f"window.scrollBy(0, {scroll_amount})")
                await asyncio.sleep(_HumanBehaviorEngine.lognormal_delay(0.3, 0.4))
            await self.page.evaluate("window.scrollTo(0, 0)")
        except Exception as e:
            log.warning(f"Scroll simulation failed: {e}")

    async def close(self):
        try:
            if self.page:
                await self.page.close()
            if self.context:
                await self.context.close()
            if self.browser:
                await self.browser.close()
            if self._playwright:
                await self._playwright.stop()
        except Exception:
            pass

