class _ComputerVisionEngine:
    def __init__(self):
        self.tesseract_available = False
        self._check_tesseract()

    def _check_tesseract(self):
        try:
            import pytesseract
            from PIL import Image
            self.tesseract_available = True
        except ImportError:
            log.warning("Tesseract not available, OCR disabled")

    def find_element_by_text(self, screenshot, target_text: str, confidence: float = 0.7):
        if not self.tesseract_available:
            return None
        try:
            import pytesseract
            from PIL import Image
            if hasattr(screenshot, 'screenshot'):
                image = screenshot.screenshot()
            else:
                image = screenshot
            data = pytesseract.image_to_data(image, output_type=pytesseract.Output.DICT)
            for i, text in enumerate(data['text']):
                if target_text.lower() in text.lower():
                    confidence_score = int(data['conf'][i])
                    if confidence_score >= confidence * 100:
                        x = data['left'][i] + data['width'][i] // 2
                        y = data['top'][i] + data['height'][i] // 2
                        return (x, y)
            return None
        except Exception as e:
            log.error(f"OCR failed: {e}")
            return None

class _HardwareHIDInterface:
    def __init__(self, config):
        self.config = config
