    @staticmethod
    def collect_network_entropy() -> bytes:
        try:
            sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
            sock.connect(("8.8.8.8", 53))
            ts = struct.pack("<d", time.perf_counter())
            sock.close()
            return ts
        except Exception:
            return os.urandom(8)

